import PS_PT:Integration:IRequestHandler;
import C_PORTAL_PKG:Util:*;
import C_META_DATA_PKG:Utility:*;

class Demo implements PS_PT:Integration:IRequestHandler
   method Demo();

   method OnRequest(&message As Message) Returns Message;
private

   Constant &OperationName = "MCP_OPER_APP_ENGINE_POST";
   Constant &DateTimeFormat = "yyyy/MM/dd HH:mm:ss";
   instance string &_ErrText;
   instance C_PORTAL_PKG:Util:JsonUtil &JsonUtil;
   instance C_PORTAL_PKG:Util:CommonUtil &CommUtil;
   instance C_META_DATA_PKG:Utility:MappingUtil &MappingUtil;
end-class;


method Demo
   &_ErrText = "";
   &JsonUtil = create C_PORTAL_PKG:Util:JsonUtil();
   &CommUtil = create C_PORTAL_PKG:Util:CommonUtil();
   &MappingUtil = create C_META_DATA_PKG:Utility:MappingUtil();
end-method;


method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;
   Local JsonObject &ReqObject, &RespObject;

   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());

      /** 这里只做请求参数传递和方法路由，具体的业务代码请单独封装函数 **/


      If &_ErrText = "" Then
         &RespMsg = &JsonUtil.CreateSuccessMessage(&OperationName, &RespObject);
      Else
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
      End-If;
   catch Exception &ex
      &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 500, &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

import C_META_DATA_PKG:Utility:PeopleCodeDeletion;
import %metadata:Key;
import %metadata:SqlRepositoryDefn:*;
import %metadata:PeopleCodeProgram:*;
import PS_PT:Integration:IRequestHandler;
import C_PORTAL_PKG:Util:JsonUtil;
import C_PORTAL_PKG:Util:CommonUtil;
import C_META_DATA_PKG:Utility:MappingUtil;

class OperAppEngineDefn implements PS_PT:Integration:IRequestHandler
   method OperAppEngineDefn();

   method OnRequest(&message As Message) Returns Message;
private
   method DeletePeopleCode(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_stepId As string, &p_req As JsonObject) Returns JsonObject;
   method ViewAppEngineStruct() Returns JsonObject;
   method CreateApplicationEngine(&p_descr As string, &p_programType As string, &p_disableRestart As string, &p_appLibrary As string, &p_tempInstance As number, &p_useDeleteforTruncateTable As string, &p_shareTableinOnlineMode As string, &batchOnly As string, &p_nonShareCannotAssigned As string, &p_comment As string, &p_sections As JsonArray);
   method InsertSection(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_descr As string, &p_autoCommit As string, &p_sectionType As string, &p_publicAccess As string, &p_steps As JsonArray);
   method InsertStep(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_stepId As string, &p_descr As string, &p_afterStep As string, &p_commitAfter As string, &p_abendAction As string, &p_actions As JsonArray);
   method InsertAction(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_stepId As string, &p_actionType As string, &p_descr As string, &p_reuseStatement As string, &p_doSelectType As string, &p_callSectionId As string, &p_callSectionAEId As string, &p_msgSetNbr As integer, &p_msgNbr As integer, &p_msgParameter As string, &p_pcOnReturn As string);
   method InsertStateRecord(&p_recName As string, &p_isDefault As string);
   method InsertTempTable(&p_recName As string);
   method ViewSQL(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_stepId As string, &p_actionType As string) Returns JsonObject;
   method ModifySQL(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_stepId As string, &p_actionType As string, &p_sqlText As string);
   method ViewPeopleCode(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_stepId As string) Returns JsonObject;
   method ModifyPeopleCode(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_stepId As string, &p_peoplecode As string);

   method GetSectionInfo(&p_aeid As string, &p_section As string) Returns JsonObject;
   method GetStepsBySection(&p_aeid As string, &p_section As string, &p_market As string, &p_dbtype As string, &p_effdt As date) Returns JsonArray;
   method GetActionsByStep(&p_aeid As string, &p_section As string, &p_market As string, &p_dbtype As string, &p_effdt As date, &p_step As string) Returns JsonArray;
   method GetStateRecords(&p_aeid As string) Returns JsonArray;
   method GetTempTables(&p_aeid As string) Returns JsonArray;

   method DoesSectionExist(&p_section As string) Returns boolean;
   method DoesStepExist(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_step As string) Returns boolean;
   method DoesActionExist(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_step As string, &p_action As string) Returns boolean;
   method GetNewSectionId() Returns string;
   method GetNewStepId(&p_section As string, &p_market As string, &p_dbType As string, &p_effdt As date, &p_afterStep As string) Returns string;
   method CheckNewStepIdExistOrNot(&p_rs As Rowset, &p_newStepId As string) Returns boolean;
   method GetSQLId(&p_section As string, &p_step As string, &p_action As string) Returns string;
   method GetAERecUse(&p_recUse As integer) Returns array of string;

   Constant &OperationName = "AI_OPER_APP_ENGINE_POST";
   Constant &DateTimeFormat = "yyyy/MM/dd HH:mm:ss";
   Constant &AEM = "AEM";
   Constant &AES = "AES";
   Constant &SYS = "SYS";

   instance string &_AEId;
   instance string &_ErrText;
   instance string &_InsertStep;
   instance boolean &_AEMLock;
   instance boolean &_AESLock;
   instance C_PORTAL_PKG:Util:JsonUtil &JsonUtil;
   instance C_PORTAL_PKG:Util:CommonUtil &CommUtil;
   instance C_META_DATA_PKG:Utility:MappingUtil &MappingUtil;
end-class;


method OperAppEngineDefn
   &_ErrText = "";
   &_AESLock = False;
   &_AEMLock = False;
   &JsonUtil = create C_PORTAL_PKG:Util:JsonUtil();
   &CommUtil = create C_PORTAL_PKG:Util:CommonUtil();
   &MappingUtil = create C_META_DATA_PKG:Utility:MappingUtil();
end-method;


method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;
   Local JsonObject &ReqObject, &RespObject;
   Local JsonArray &Actions, &Sections, &Steps;
   Local string &OperationType, &SectionId, &StepId, &Descr, &AfterStepId, &CommitAfter, &AbendAction, &MessageParameter;
   Local string &ActionType, &Market, &DbType, &OnNoRows, &ReuseStatement, &DoSelectType, &CallSectionId, &CallSectionAEId, &PCOnReturn;
   Local string &AutoCommit, &SectionType, &PublicAccess, &ProgramType, &DisableRestart, &AppLibrary, &Comment, &SQLText, &PeopleCode;
   Local string &UseDeleteforTruncateTable, &ShareTableinOnlineMode, &BatchOnly, &NonShareCannotAssigned;
   Local date &Effdt;
   Local integer &CommitFrequency, &MessageSetNbr, &MessageNbr, &TempTblInce, &RecordUse;

   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());
      If Not &ReqObject.IsExist("aeId") Then
         &_ErrText = &_ErrText | "缺少aeId";
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
         Return &RespMsg;
      End-If;

      If Not &ReqObject.IsExist("operationType") Then
         &OperationType = "struct";
      Else
         &OperationType = &ReqObject.GetString("operationType");
      End-If;
      &_AEId = &ReqObject.GetString("aeId");
      Evaluate &OperationType
      When "struct"
         /* 查看AE结构 */
         &RespObject = %This.ViewAppEngineStruct();
         Break;
      When "createApplicationEngine"
         /* 创建一个AE */
         If &ReqObject.IsExist("descr") Then
            &Descr = &ReqObject.GetString("descr");
         End-If;
         If &ReqObject.IsExist("programType") Then
            &ProgramType = &ReqObject.GetString("programType");
         End-If;
         If &ReqObject.IsExist("tempTblInstance") Then
            &TempTblInce = &ReqObject.GetNumber("tempTblInstance");
         End-If;
         If &ReqObject.IsExist("recordUse") Then
            &RecordUse = &ReqObject.GetNumber("recordUse");
         End-If;
         If &ReqObject.IsExist("comment") Then
            &Comment = &CommUtil.UnEscapeJSON(&ReqObject.GetString("comment"));
         End-If;
         If &ReqObject.IsExist("disableRestart") Then
            &DisableRestart = &ReqObject.GetString("disableRestart");
         End-If;
         If &ReqObject.IsExist("appLibrary") Then
            &AppLibrary = &ReqObject.GetString("appLibrary");
         End-If;
         If &ReqObject.IsExist("Sections") Then
            &Sections = &ReqObject.GetJsonArray("Sections");
         End-If;
         If &ReqObject.IsExist("useDeleteforTruncateTable") Then
            &UseDeleteforTruncateTable = &ReqObject.GetString("useDeleteforTruncateTable");
         End-If;
         If &ReqObject.IsExist("shareTableinOnlineMode") Then
            &ShareTableinOnlineMode = &ReqObject.GetString("shareTableinOnlineMode");
         End-If;
         If &ReqObject.IsExist("batchOnly") Then
            &BatchOnly = &ReqObject.GetString("batchOnly");
         End-If;
         If &ReqObject.IsExist("non-sharedCannotAssigned") Then
            &NonShareCannotAssigned = &ReqObject.GetString("non-sharedCannotAssigned");
         End-If;
         %This.CreateApplicationEngine(&Descr, &ProgramType, &DisableRestart, &AppLibrary, &TempTblInce, &UseDeleteforTruncateTable, &ShareTableinOnlineMode, &BatchOnly, &NonShareCannotAssigned, &Comment, &Sections);
         Break;
      When "insertSection"
         /* 插入Section */
         If &ReqObject.IsExist("sectionId") Then
            &SectionId = &ReqObject.GetString("sectionId");
         End-If;
         If &ReqObject.IsExist("market") Then
            &Market = &ReqObject.GetString("market");
         End-If;
         If &ReqObject.IsExist("dbType") Then
            &DbType = &ReqObject.GetString("dbType");
         End-If;
         If &ReqObject.IsExist("effdt") Then
            &Effdt = Date(&ReqObject.GetString("effdt"));
         End-If;
         If &ReqObject.IsExist("descr") Then
            &Descr = &ReqObject.GetString("descr");
         End-If;
         If &ReqObject.IsExist("autoCommit") Then
            &AutoCommit = &ReqObject.GetString("autoCommit");
         End-If;
         If &ReqObject.IsExist("sectionType") Then
            &SectionType = &ReqObject.GetString("sectionType");
         End-If;
         If &ReqObject.IsExist("publicAccess") Then
            &PublicAccess = &ReqObject.GetString("publicAccess");
         End-If;
         If &ReqObject.IsExist("steps") Then
            &Steps = &ReqObject.GetJsonArray("steps");
         End-If;
         %This.InsertSection(&SectionId, &Market, &DbType, &Effdt, &Descr, &AutoCommit, &SectionType, &PublicAccess, &Steps);
         Break;
      When "insertStep"
         /* 插入一个Step */
         If Not &ReqObject.IsExist("sectionId") Then
            &_ErrText = &_ErrText | "sectionId is required in insertStep Operation";
         End-If;
         If Not &ReqObject.IsExist("market") Then
            &_ErrText = &_ErrText | "market is required in insertStep Operation";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_ErrText = &_ErrText | "dbType is required in insertStep Operation";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_ErrText = &_ErrText | "effdt is required in insertStep Operation";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         &SectionId = &ReqObject.GetString("sectionId");
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         If &ReqObject.IsExist("stepId") Then
            &StepId = &ReqObject.GetString("stepId");
         End-If;
         If &ReqObject.IsExist("descr") Then
            &Descr = &ReqObject.GetString("descr");
         End-If;
         If &ReqObject.IsExist("afterStepId") Then
            &AfterStepId = &ReqObject.GetString("afterStepId");
         End-If;
         If &ReqObject.IsExist("commitAfter") Then
            &CommitAfter = &ReqObject.GetString("commitAfter");
         End-If;
         If &ReqObject.IsExist("abendAction") Then
            &AbendAction = &ReqObject.GetString("abendAction");
         End-If;
         If &ReqObject.IsExist("actions") Then
            &Actions = &ReqObject.GetJsonArray("actions");
         End-If;
         %This.InsertStep(&SectionId, &Market, &DbType, &Effdt, &StepId, &Descr, &AfterStepId, &CommitAfter, &AbendAction, &Actions);
         Break;
      When "insertAction"
         /* 插入一个Action */
         If Not &ReqObject.IsExist("sectionId") Then
            &_ErrText = &_ErrText | "sectionId is required in insertAction Operation";
         End-If;
         If Not &ReqObject.IsExist("market") Then
            &_ErrText = &_ErrText | "market is required in insertAction Operation";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_ErrText = &_ErrText | "dbType is required in insertAction Operation";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_ErrText = &_ErrText | "effdt is required in insertAction Operation";
         End-If;
         If Not &ReqObject.IsExist("stepId") Then
            &_ErrText = &_ErrText | "stepId is required in insertAction Operation";
         End-If;
         If Not &ReqObject.IsExist("actionType") Then
            &_ErrText = &_ErrText | "actionType is required in insertAction Operation";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         &SectionId = &ReqObject.GetString("sectionId");
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         &StepId = &ReqObject.GetString("stepId");
         &ActionType = &ReqObject.GetString("actionType");
         If &ReqObject.IsExist("descr") Then
            &Descr = &ReqObject.GetString("descr");
         End-If;
         If &ReqObject.IsExist("reuseStatement") Then
            &ReuseStatement = &ReqObject.GetString("reuseStatement");
         End-If;
         If &ReqObject.IsExist("doSelectType") Then
            &DoSelectType = &ReqObject.GetString("doSelectType");
         End-If;
         If &ReqObject.IsExist("callSectionAeId") Then
            &CallSectionAEId = &ReqObject.GetString("callSectionAeId");
         End-If;
         If &ReqObject.IsExist("callSectionId") Then
            &CallSectionId = &ReqObject.GetString("callSectionId");
         End-If;
         If &ReqObject.IsExist("messageSetNbr") Then
            &MessageSetNbr = &ReqObject.GetNumber("messageSetNbr");
         End-If;
         If &ReqObject.IsExist("messageNbr") Then
            &MessageNbr = &ReqObject.GetNumber("messageNbr");
         End-If;
         If &ReqObject.IsExist("messageParameter") Then
            &MessageParameter = &ReqObject.GetString("messageParameter");
         End-If;
         If &ReqObject.IsExist("peoplecodeOnReturn") Then
            &PCOnReturn = &ReqObject.GetString("peoplecodeOnReturn");
         End-If;
         %This.InsertAction(&SectionId, &Market, &DbType, &Effdt, &StepId, &ActionType, &Descr, &ReuseStatement, &DoSelectType, &CallSectionAEId, &CallSectionId, &MessageSetNbr, &MessageNbr, &MessageParameter, &PCOnReturn);
         Break;
      When "viewSQL"
         /* 查看SQL */
         If Not &ReqObject.IsExist("sectionId") Then
            &_ErrText = &_ErrText | "sectionId is required in viewSQL Operation";
         End-If;
         If Not &ReqObject.IsExist("market") Then
            &_ErrText = &_ErrText | "market is required in viewSQL Operation";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_ErrText = &_ErrText | "dbType is required in viewSQL Operation";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_ErrText = &_ErrText | "effdt is required in viewSQL Operation";
         End-If;
         If Not &ReqObject.IsExist("stepId") Then
            &_ErrText = &_ErrText | "stepId is required in viewSQL Operation";
         End-If;
         If Not &ReqObject.IsExist("actionType") Then
            &_ErrText = &_ErrText | "actionType is required in viewSQL Operation";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         &SectionId = &ReqObject.GetString("sectionId");
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         &StepId = &ReqObject.GetString("stepId");
         &ActionType = &ReqObject.GetString("actionType");
         &RespObject = %This.ViewSQL(&SectionId, &Market, &DbType, &Effdt, &StepId, &ActionType);
         Break;
      When "modifySQL"
         /* 修改SQL */
         If Not &ReqObject.IsExist("sectionId") Then
            &_ErrText = &_ErrText | "sectionId is required in modifySQL Operation";
         End-If;
         If Not &ReqObject.IsExist("market") Then
            &_ErrText = &_ErrText | "market is required in modifySQL Operation";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_ErrText = &_ErrText | "dbType is required in modifySQL Operation";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_ErrText = &_ErrText | "effdt is required in modifySQL Operation";
         End-If;
         If Not &ReqObject.IsExist("stepId") Then
            &_ErrText = &_ErrText | "stepId is required in modifySQL Operation";
         End-If;
         If Not &ReqObject.IsExist("actionType") Then
            &_ErrText = &_ErrText | "actionType is required in modifySQL Operation";
         End-If;
         If Not &ReqObject.IsExist("sqlText") Then
            &_ErrText = &_ErrText | "sqlText is required in modifySQL Operation";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         &SectionId = &ReqObject.GetString("sectionId");
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         &StepId = &ReqObject.GetString("stepId");
         &ActionType = &ReqObject.GetString("actionType");
         &SQLText = &CommUtil.UnEscapeJSON(&ReqObject.GetString("sqlText"));
         %This.ModifySQL(&SectionId, &Market, &DbType, &Effdt, &StepId, &ActionType, &SQLText);
         Break;
      When "viewPeopleCode"
         /* 查看PeopleCode */
         If Not &ReqObject.IsExist("sectionId") Then
            &_ErrText = &_ErrText | "sectionId is required in viewPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("market") Then
            &_ErrText = &_ErrText | "market is required in viewPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_ErrText = &_ErrText | "dbType is required in viewPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_ErrText = &_ErrText | "effdt is required in viewPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("stepId") Then
            &_ErrText = &_ErrText | "stepId is required in viewPeopleCode Operation";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         &SectionId = &ReqObject.GetString("sectionId");
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         &StepId = &ReqObject.GetString("stepId");
         &ActionType = &ReqObject.GetString("actionType");
         &RespObject = %This.ViewPeopleCode(&SectionId, &Market, &DbType, &Effdt, &StepId);
         Break;
      When "deletePeopleCode"
         /* 查看PeopleCode */
         If Not &ReqObject.IsExist("sectionId") Then
            &_ErrText = &_ErrText | "sectionId is required in deletePeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("market") Then
            &_ErrText = &_ErrText | "market is required in deletePeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_ErrText = &_ErrText | "dbType is required in deletePeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_ErrText = &_ErrText | "effdt is required in deletePeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("stepId") Then
            &_ErrText = &_ErrText | "stepId is required in deletePeopleCode Operation";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         &SectionId = &ReqObject.GetString("sectionId");
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         &StepId = &ReqObject.GetString("stepId");
         &RespObject = %This.DeletePeopleCode(&SectionId, &Market, &DbType, &Effdt, &StepId, &ReqObject);
         Break;
      When "modifyPeopleCode"
         /* 修改PeopleCode */
         If Not &ReqObject.IsExist("sectionId") Then
            &_ErrText = &_ErrText | "sectionId is required in modifyPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("market") Then
            &_ErrText = &_ErrText | "market is required in modifyPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_ErrText = &_ErrText | "dbType is required in modifyPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_ErrText = &_ErrText | "effdt is required in modifyPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("stepId") Then
            &_ErrText = &_ErrText | "stepId is required in modifyPeopleCode Operation";
         End-If;
         If Not &ReqObject.IsExist("peopleCode") Then
            &_ErrText = &_ErrText | "peopleCode is required in modifyPeopleCode Operation";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         &SectionId = &ReqObject.GetString("sectionId");
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         &StepId = &ReqObject.GetString("stepId");
         &ActionType = &ReqObject.GetString("actionType");
         &PeopleCode = &CommUtil.UnEscapeJSON(&ReqObject.GetString("peopleCode"));
         %This.ModifyPeopleCode(&SectionId, &Market, &DbType, &Effdt, &StepId, &PeopleCode);
         Break;
      When "insertStateRecord"
         If Not &ReqObject.IsExist("recName") Then
            &_ErrText = &_ErrText | "recName is required";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         %This.InsertStateRecord(&ReqObject.GetString("recName"), &ReqObject.GetString("isDefault"));
         Break;
      When "insertTempTable"
         If Not &ReqObject.IsExist("recName") Then
            &_ErrText = &_ErrText | "recName is required";
         End-If;
         If &_ErrText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
            Return &RespMsg;
         End-If;
         %This.InsertTempTable(&ReqObject.GetString("recName"));
         Break;
      When-Other
         &_ErrText = &_ErrText | "unknow operationType";
      End-Evaluate;

      If &_ErrText = "" Then
         &RespMsg = &JsonUtil.CreateSuccessMessage(&OperationName, &RespObject);
      Else
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
      End-If;
   catch Exception &ex
      &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 999, "Error: " | &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

method ViewAppEngineStruct
   /+ Returns JsonObject +/
   Local JsonObject &StructObj;
   Local string &Descr, &LastUpdOprid, &DescrLong, &AppLibrary, &DisableRestart, &ProgramType;
   Local datetime &LastUpdDttm;
   Local number &MessageSet, &TempTableInstance, &RecUse;

   &StructObj = CreateJsonObject();
   /* AE的基本信息 */
   SQLExec("SELECT DESCR,DESCRLONG,LASTUPDDTTM,LASTUPDOPRID,MESSAGE_SET_NBR,AE_APPLLIBRARY,AE_DISABLE_RESTART,AEPROGTYPE,TEMPTBLINSTANCES,RECUSE FROM PSAEAPPLDEFN WHERE AE_APPLID = :1", &_AEId, &Descr, &DescrLong, &LastUpdDttm, &LastUpdOprid, &MessageSet, &AppLibrary, &DisableRestart, &ProgramType, &TempTableInstance, &RecUse);
   &StructObj.AddProperty("messageSet", &MessageSet);
   &StructObj.AddProperty("programType", &ProgramType);
   &StructObj.AddProperty("disableRestart", &DisableRestart);
   &StructObj.AddProperty("applicationLibrary", &AppLibrary);
   &StructObj.AddProperty("descr", &Descr);
   &StructObj.AddProperty("comment", &CommUtil.EscapeJSON(&DescrLong));
   Local array of string &RecUseArr = %This.GetAERecUse(&RecUse);
   If &RecUseArr.Find("useDeleteforTruncateTable") > 0 Then
      &StructObj.AddProperty("useDeleteforTruncateTable", "Y");
   Else
      &StructObj.AddProperty("useDeleteforTruncateTable", "N");
   End-If;
   If &RecUseArr.Find("shareTableinOnlineMode") > 0 Then
      &StructObj.AddProperty("shareTableinOnlineMode", "Y");
   Else
      &StructObj.AddProperty("shareTableinOnlineMode", "N");
   End-If;
   If &RecUseArr.Find("batchOnly") > 0 Then
      &StructObj.AddProperty("batchOnly", "Y");
   Else
      &StructObj.AddProperty("batchOnly", "N");
   End-If;
   If &RecUseArr.Find("non-sharedCannotAssigned") > 0 Then
      &StructObj.AddProperty("non-sharedCannotAssigned", "Abort");
   Else
      &StructObj.AddProperty("non-sharedCannotAssigned", "Continue");
   End-If;
   &StructObj.AddProperty("lastUpdate", "Last updated by: " | &LastUpdOprid | ", " | DateTimeToLocalizedString(&LastUpdDttm, &DateTimeFormat));
   &StructObj.AddJsonObject("program", %This.GetSectionInfo(&_AEId, "MAIN"));
   &StructObj.AddJsonArray("stateRecords", %This.GetStateRecords(&_AEId));
   &StructObj.AddJsonArray("tempTables", %This.GetTempTables(&_AEId));
   Return &StructObj;
end-method;

method CreateApplicationEngine
   /+ &p_descr as String, +/
   /+ &p_programType as String, +/
   /+ &p_disableRestart as String, +/
   /+ &p_appLibrary as String, +/
   /+ &p_tempInstance as Number, +/
   /+ &p_useDeleteforTruncateTable as String, +/
   /+ &p_shareTableinOnlineMode as String, +/
   /+ &batchOnly as String, +/
   /+ &p_nonShareCannotAssigned as String, +/
   /+ &p_comment as String, +/
   /+ &p_sections as JsonArray +/
   Local datetime &LastUpdDttm;
   Local JsonArray &Steps;
   Local string &AEExist, &LastUpdOprid, &LicenseCode;
   Local number &AEMVersion, &AESVersion, &i, &RecUse;
   Local boolean &SectionExist, &MAINSectionExist;
   Local Record &PSAEAPPLDEFN;

   /* 检查AE是否已存在 */
   SQLExec("SELECT 'Y' FROM PSAEAPPLDEFN WHERE AE_APPLID = :1", &_AEId, &AEExist);
   If All(&AEExist) Then
      &_ErrText = &_ErrText | "AE " | &_AEId | " already exists,";
      Return;
   End-If;

   If None(&p_programType) Then
      &p_programType = "0";
   End-If;

   If None(&p_disableRestart) Then
      &p_disableRestart = "N";
   End-If;

   If None(&p_appLibrary) Then
      &p_appLibrary = "N";
   End-If;
   &LicenseCode = %IntBroker.AELicence(&_AEId);

   /* 新建的AE 默认带MAIN Section和一个Step */
   &SectionExist = True;
   If &p_sections = Null Then
      &SectionExist = False;
   Else
      If &p_sections.Size = 0 Then
         &SectionExist = False;
      End-If;
   End-If;

   If Not &SectionExist Then
      /** 没带Section参数，自动创建一个MAIN Section **/
      &p_sections = CreateJsonArray();
      Local JsonObject &SectionObj = CreateJsonObject();
      &Steps = CreateJsonArray();
      &SectionObj.AddProperty("sectionId", "MAIN");
      &SectionObj.AddProperty("publicAccess", "Y");
      &SectionObj.AddProperty("steps", &Steps);
      Local JsonObject &StepObj = CreateJsonObject();
      &StepObj.AddProperty("stepId", "Step01");
      &Steps.AddJsonObjectElement("", &StepObj);
      &p_sections.AddJsonObjectElement("", &SectionObj);
   Else
      /** 带了Section参数，检查是否存在MAIN Section **/
      &MAINSectionExist = False;
      For &i = 1 To &p_sections.Size
         &SectionObj = &p_sections.GetJsonObject(&i);
         If &SectionObj.GetString("sectionId") = "MAIN" Then
            /* 检查是否携带publicAccess参数 */
            If &SectionObj.IsExist("publicAccess") Then
               If &SectionObj.GetString("publicAccess") <> "Y" Then
                  &_ErrText = &_ErrText | "publicAccess must be yes in MAIN Section";
                  Return;
               End-If;
            Else
               &SectionObj.AddProperty("publicAccess", "Y");
            End-If;
            &MAINSectionExist = True;
            Break;
         End-If;
      End-For;
      If &MAINSectionExist = False Then
         &_ErrText = &_ErrText | "Sections parameter is not right,";
         Return;
      End-If;
   End-If;

   /* 计算RecUse */
   &RecUse = 0;
   If &p_useDeleteforTruncateTable = "Y" Then
      &RecUse = &RecUse + 8;
   End-If;
   If &p_shareTableinOnlineMode = "Y" Then
      &RecUse = &RecUse + 4;
   End-If;
   If &batchOnly = "Y" Then
      &RecUse = &RecUse + 2;
   End-If;
   If &p_nonShareCannotAssigned = "Abort" Then
      &RecUse = &RecUse + 1;
   End-If;

   /* 锁表PSLOCK */
   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &AEM, &AEMVersion);
   &_AEMLock = True;

   /* 让PSLOCK的Version + 1 */
   SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &AEM);
   &AEMVersion = &AEMVersion + 1;

   &LastUpdDttm = %Datetime;
   &LastUpdOprid = %UserId;

   /* 插入AE定义 */
   &PSAEAPPLDEFN = CreateRecord(Record.PSAEAPPLDEFN);
   &PSAEAPPLDEFN.AE_APPLID.Value = &_AEId;
   If All(&p_descr) Then
      &PSAEAPPLDEFN.DESCR.Value = &p_descr;
   End-If;
   &PSAEAPPLDEFN.AE_DATE_OVERRIDE.Value = "N";
   &PSAEAPPLDEFN.AE_APPLLIBRARY.Value = &p_appLibrary;
   &PSAEAPPLDEFN.AE_DISABLE_RESTART.Value = &p_disableRestart;
   &PSAEAPPLDEFN.VERSION.Value = &AEMVersion;
   &PSAEAPPLDEFN.LASTUPDOPRID.Value = &LastUpdOprid;
   &PSAEAPPLDEFN.LASTUPDDTTM.Value = &LastUpdDttm;
   &PSAEAPPLDEFN.AEPROGTYPE.Value = &p_programType;
   &PSAEAPPLDEFN.TEMPTBLINSTANCES.Value = &p_tempInstance;
   &PSAEAPPLDEFN.RECUSE.Value = &RecUse;
   &PSAEAPPLDEFN.LICENSE_CODE.Value = &LicenseCode;
   If All(&p_comment) Then
      &PSAEAPPLDEFN.DESCRLONG.Value = &p_comment;
   End-If;
   If Not &PSAEAPPLDEFN.Insert() Then
      &_ErrText = &_ErrText | "Insert PSAEAPPLDEFN failed";
      Return;
   End-If;

   /* 创建Section */
   For &i = 1 To &p_sections.Size
      Local string &SectionId, &Market, &DbType, &SectionDescr, &AutoCommit, &SectionType, &PublicAccess;
      Local date &Effdt;
      &SectionObj = &p_sections.GetJsonObject(&i);
      If &SectionObj.IsExist("sectionId") Then
         &SectionId = &SectionObj.GetString("sectionId");
      End-If;
      If &SectionObj.IsExist("market") Then
         &Market = &SectionObj.GetString("market");
      End-If;
      If &SectionObj.IsExist("dbType") Then
         &DbType = &SectionObj.GetString("dbType");
      End-If;
      If &SectionObj.IsExist("effdt") Then
         &Effdt = Date(&SectionObj.GetString("effdt"));
      End-If;
      If &SectionObj.IsExist("descr") Then
         &SectionDescr = &SectionObj.GetString("descr");
      End-If;
      If &SectionObj.IsExist("autoCommit") Then
         &AutoCommit = &SectionObj.GetString("autoCommit");
      End-If;
      If &SectionObj.IsExist("sectionType") Then
         &SectionType = &SectionObj.GetString("sectionType");
      End-If;
      If &SectionObj.IsExist("publicAccess") Then
         &PublicAccess = &SectionObj.GetString("publicAccess");
      End-If;
      If &SectionObj.IsExist("steps") Then
         &Steps = &SectionObj.GetJsonArray("steps");
      End-If;
      %This.InsertSection(&SectionId, &Market, &DbType, &Effdt, &SectionDescr, &AutoCommit, &SectionType, &PublicAccess, &Steps);
      If &_ErrText <> "" Then
         Return;
      End-If;
   End-For;

   /* 更新版本 */
   SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS);
   SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &AEM, &AEMVersion);
   CommitWork();

   &_AEMLock = False;
end-method;

method InsertSection
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_descr as String, +/
   /+ &p_autoCommit as String, +/
   /+ &p_sectionType as String, +/
   /+ &p_publicAccess as String, +/
   /+ &p_steps as JsonArray +/
   Local integer &i;
   Local string &StepId, &Descr, &AfterStepId, &CommitAfter, &AbendAction;
   Local JsonObject &StepObj;
   Local JsonArray &Actions;
   Local Record &PSAESECTDEFN, &PSAESECTDTLDEFN;
   Local boolean &SectionAEMLock;

   If None(&p_section) Then
      &p_section = %This.GetNewSectionId();
   End-If;

   If None(&p_market) Then
      &p_market = "GBL";
   End-If;

   If None(&p_effdt) Then
      &p_effdt = Date3(1900, 1, 1);
   End-If;

   If None(&p_descr) Then
      &p_descr = &p_section | " description";
   End-If;

   If None(&p_autoCommit) Then
      &p_autoCommit = "N";
   End-If;

   If None(&p_sectionType) Then
      &p_sectionType = "P";
   End-If;

   If None(&p_publicAccess) Then
      &p_publicAccess = "N";
   End-If;

   /* insertSection Begin */
   Local datetime &LastUpdDttm;
   Local string &LastUpdOprid;
   Local number &AESVersion, &AEMVersion;

   /** 锁上AES **/
   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &AES, &AESVersion);
   &_AESLock = True;
   SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &AES);
   &AESVersion = &AESVersion + 1;

   /** 如果AEM已经锁上，不重复追加Version **/
   &SectionAEMLock = False;
   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &AEM, &AEMVersion);
   If &_AEMLock = False Then
      SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &AEM);
      &AEMVersion = &AEMVersion + 1;
      &_AEMLock = True;
      &SectionAEMLock = True;
   End-If;

   &LastUpdDttm = %Datetime;
   &LastUpdOprid = %UserId;

   /** 插入Section **/
   &PSAESECTDEFN = CreateRecord(Record.PSAESECTDEFN);
   &PSAESECTDEFN.AE_APPLID.Value = &_AEId;
   &PSAESECTDEFN.AE_SECTION.Value = &p_section;
   &PSAESECTDEFN.VERSION.Value = &AESVersion;
   &PSAESECTDEFN.LASTUPDOPRID.Value = &LastUpdOprid;
   &PSAESECTDEFN.LASTUPDDTTM.Value = &LastUpdDttm;
   &PSAESECTDEFN.AE_SECTION_TYPE.Value = &p_sectionType;
   &PSAESECTDEFN.AE_PUBLIC_SW.Value = &p_publicAccess;
   If Not &PSAESECTDEFN.Insert() Then
      &_ErrText = &_ErrText | "Insert PSAESECTDEFN failed";
      Return;
   End-If;

   /** DTL **/
   &PSAESECTDTLDEFN = CreateRecord(Record.PSAESECTDTLDEFN);
   &PSAESECTDTLDEFN.AE_APPLID.Value = &_AEId;
   &PSAESECTDTLDEFN.AE_SECTION.Value = &p_section;
   &PSAESECTDTLDEFN.MARKET.Value = &p_market;
   &PSAESECTDTLDEFN.DBTYPE.Value = &p_dbType;
   &PSAESECTDTLDEFN.EFFDT.Value = &p_effdt;
   &PSAESECTDTLDEFN.EFF_STATUS.Value = "A";
   &PSAESECTDTLDEFN.DESCR.Value = &p_descr;
   &PSAESECTDTLDEFN.AE_AUTO_COMMIT.Value = &p_autoCommit;
   If Not &PSAESECTDTLDEFN.Insert() Then
      &_ErrText = &_ErrText | "Insert PSAESECTDTLDEFN failed";
      Return;
   End-If;

   /** 插入Step **/
   If &p_steps <> Null Then
      For &i = 1 To &p_steps.Size
         &StepObj = &p_steps.GetJsonObject(&i);
         If &StepObj.IsExist("stepId") Then
            &StepId = &StepObj.GetString("stepId");
         End-If;
         If &StepObj.IsExist("descr") Then
            &Descr = &StepObj.GetString("descr");
         End-If;
         If &StepObj.IsExist("afterStepId") Then
            &AfterStepId = &StepObj.GetString("afterStepId");
         End-If;
         If &StepObj.IsExist("commitAfter") Then
            &CommitAfter = &StepObj.GetString("commitAfter");
         End-If;
         If &StepObj.IsExist("abendAction") Then
            &AbendAction = &StepObj.GetString("abendAction");
         End-If;
         If &StepObj.IsExist("actions") Then
            &Actions = &StepObj.GetJsonArray("actions");
         End-If;
         %This.InsertStep(&p_section, &p_market, &p_dbType, &p_effdt, &StepId, &Descr, &AfterStepId, &CommitAfter, &AbendAction, &Actions);
         If &_ErrText <> "" Then
            Return;
         End-If;
      End-For;
   End-If;

   /** 更新PSVERSION版本 **/
   SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &AES, &AESVersion);

   /** 如果是Section阶段上的AEM锁，这时也要在Section阶段释放锁 **/
   If &SectionAEMLock = True Then
      /** 更新AE为最新Version **/
      SQLExec("UPDATE PSAEAPPLDEFN SET VERSION = :1,LASTUPDDTTM = :2,LASTUPDOPRID = :3 WHERE AE_APPLID = :4", &AEMVersion, &LastUpdDttm, &LastUpdOprid, &_AEId);
      SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &AEM, &AEMVersion);
      SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS);
      CommitWork();
      &_AEMLock = False;
   End-If;
   &_AESLock = False;
end-method;

method InsertStep
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_stepId as String, +/
   /+ &p_descr as String, +/
   /+ &p_afterStep as String, +/
   /+ &p_commitAfter as String, +/
   /+ &p_abendAction as String, +/
   /+ &p_actions as JsonArray +/
   Local boolean &ExistActions, &StepAesLock;
   Local number &AeSeqNum, &i;
   Local string &SQLId, &ActionDescr, &ActionType, &ReuseStatement, &DoSelectType, &CallSectionAEId, &CallSectionId;
   Local string &MessageParameter, &PCOnReturn;
   Local integer &MessageSetNbr, &MessageNbr;
   Local Record &PSAESTEPDEFN;

   /* 校验Section是否存在 */
   If Not %This.DoesSectionExist(&p_section) Then
      &_ErrText = &_ErrText | "Section is not exist,";
   End-If;

   /* 校验Step是否存在 */
   If All(&p_stepId) Then
      If %This.DoesStepExist(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId) Then
         &_ErrText = &_ErrText | "Step is ready exist,";
      End-If;
   End-If;

   /* 校验afterStep是否存在 */
   If All(&p_afterStep) Then
      If Not %This.DoesStepExist(&p_section, &p_market, &p_dbType, &p_effdt, &p_afterStep) Then
         &_ErrText = &_ErrText | "AfterStep" | &p_afterStep | " is not exist,";
      End-If;
   End-If;

   If &_ErrText <> "" Then
      Return;
   End-If;

   /* 确认stepId */
   If None(&p_stepId) Then
      &p_stepId = %This.GetNewStepId(&p_section, &p_market, &p_dbType, &p_effdt, &p_afterStep);
   End-If;

   /* 获取插入序号 - 优先查询Section中序号最大的Step */
   If None(&p_afterStep) Then
      SQLExec("SELECT AE_STEP FROM PSAESTEPDEFN WHERE AE_APPLID = :1 AND AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5 AND AE_SEQ_NUM = (SELECT MAX(AE_SEQ_NUM) FROM PSAESTEPDEFN WHERE AE_APPLID = :1 AND AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5)", &_AEId, &p_section, &p_market, &p_dbType, &p_effdt, &p_afterStep);
   End-If;
   If All(&p_afterStep) Then
      SQLExec("SELECT AE_SEQ_NUM + 1 FROM PSAESTEPDEFN WHERE AE_APPLID = :1 AND AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5 AND AE_STEP = :6", &_AEId, &p_section, &p_market, &p_dbType, &p_effdt, &p_afterStep, &AeSeqNum);
   Else
      &AeSeqNum = 1;
   End-If;

   /* 默认描述 */
   If None(&p_descr) Then
      &p_descr = &p_stepId | " description";
   End-If;

   /* 默认出错时处理方式 */
   If None(&p_abendAction) Then
      &p_abendAction = "A";
   End-If;

   /* 默认commitAfter */
   If None(&p_commitAfter) Then
      &p_commitAfter = "D";
   End-If;

   /* insertStep Begin */
   Local datetime &LastUpdDttm;
   Local string &LastUpdOprid;
   Local number &AESVersion;

   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &AES, &AESVersion);
   If &_AESLock = False Then
      SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &AES);
      &AESVersion = &AESVersion + 1;
      &_AESLock = True;
      &StepAesLock = True;
   End-If;

   &LastUpdDttm = %Datetime;
   &LastUpdOprid = %UserId;

   /** 插入Step **/
   &PSAESTEPDEFN = CreateRecord(Record.PSAESTEPDEFN);
   &PSAESTEPDEFN.AE_APPLID.Value = &_AEId;
   &PSAESTEPDEFN.AE_SECTION.Value = &p_section;
   &PSAESTEPDEFN.MARKET.Value = &p_market;
   &PSAESTEPDEFN.DBTYPE.Value = &p_dbType;
   &PSAESTEPDEFN.EFFDT.Value = &p_effdt;
   &PSAESTEPDEFN.AE_STEP.Value = &p_stepId;
   &PSAESTEPDEFN.AE_SEQ_NUM.Value = &AeSeqNum;
   &PSAESTEPDEFN.AE_ACTIVE_STATUS.Value = "A";
   &PSAESTEPDEFN.AE_ABEND_ACTION.Value = &p_abendAction;
   &PSAESTEPDEFN.AE_COMMIT_AFTER.Value = &p_commitAfter;
   &PSAESTEPDEFN.AE_DYNAMIC_DO.Value = "N";
   &PSAESTEPDEFN.AE_ON_NOROWS.Value = "C";
   &PSAESTEPDEFN.DESCR.Value = &p_descr;
   &PSAESTEPDEFN.PTAE_LOGGING_SQL.Value = "N";
   If Not &PSAESTEPDEFN.Insert() Then
      &_ErrText = &_ErrText | "Insert PSAESTEPDEFN failed";
      Return;
   End-If;

   /* 插入Actions */
   If &p_actions <> Null Then
      If &p_actions.Size > 0 Then
         &ExistActions = True;
      End-If;
   End-If;
   If Not &ExistActions Then
      /* 如果没有传actions参数，插入一个默认的SQL Action */
      &ActionType = "S";
      %This.InsertAction(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId, &ActionType, &ActionDescr, &ReuseStatement, &DoSelectType, &CallSectionAEId, &CallSectionId, &MessageSetNbr, &MessageNbr, &MessageParameter, &PCOnReturn);
      If &_ErrText <> "" Then
         Return;
      End-If;
   Else
      /* 插入actions */
      For &i = 1 To &p_actions.Size
         Local JsonObject &ActionObj = &p_actions.GetJsonObject(&i);
         If Not &ActionObj.IsExist("actionType") Then
            Continue;
         Else
            &ActionType = &ActionObj.GetString("actionType");
         End-If;
         If &ActionObj.IsExist("descr") Then
            &ActionDescr = &ActionObj.GetString("descr");
         End-If;
         If &ActionObj.IsExist("reuseStatement") Then
            &ReuseStatement = &ActionObj.GetString("reuseStatement");
         End-If;
         If &ActionObj.IsExist("doSelectType") Then
            &DoSelectType = &ActionObj.GetString("doSelectType");
         End-If;
         If &ActionObj.IsExist("callSectionAeId") Then
            &CallSectionAEId = &ActionObj.GetString("callSectionAeId");
         End-If;
         If &ActionObj.IsExist("callSectionId") Then
            &CallSectionId = &ActionObj.GetString("callSectionId");
         End-If;
         If &ActionObj.IsExist("messageSetNbr") Then
            &MessageSetNbr = &ActionObj.GetNumber("messageSetNbr");
         End-If;
         If &ActionObj.IsExist("messageNbr") Then
            &MessageNbr = &ActionObj.GetNumber("messageNbr");
         End-If;
         If &ActionObj.IsExist("messageParameter") Then
            &MessageParameter = &ActionObj.GetString("messageParameter");
         End-If;
         If &ActionObj.IsExist("peoplecodeOnReturn") Then
            &PCOnReturn = &ActionObj.GetString("peoplecodeOnReturn");
         End-If;
         %This.InsertAction(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId, &ActionType, &ActionDescr, &ReuseStatement, &DoSelectType, &CallSectionAEId, &CallSectionId, &MessageSetNbr, &MessageNbr, &MessageParameter, &PCOnReturn);
         If &_ErrText <> "" Then
            Return;
         End-If;
      End-For;
   End-If;

   If &StepAesLock = True Then
      SQLExec("UPDATE PSAESECTDEFN SET VERSION = :1,LASTUPDDTTM = :2,LASTUPDOPRID = :3 WHERE AE_APPLID = :4 AND AE_SECTION = :5", &AESVersion, &LastUpdDttm, &LastUpdOprid, &_AEId, &p_section);
      SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS);
      SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &AES, &AESVersion);
      CommitWork();
      &_AESLock = False;
   End-If;
   &StepAesLock = False;
end-method;

method InsertAction
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_stepId as String, +/
   /+ &p_actionType as String, +/
   /+ &p_descr as String, +/
   /+ &p_reuseStatement as String, +/
   /+ &p_doSelectType as String, +/
   /+ &p_callSectionId as String, +/
   /+ &p_callSectionAEId as String, +/
   /+ &p_msgSetNbr as Integer, +/
   /+ &p_msgNbr as Integer, +/
   /+ &p_msgParameter as String, +/
   /+ &p_pcOnReturn as String +/
   Local boolean &StepExist, &ActionExist, &CallSectExist, &SQLExist, &ActionAesLock;
   Local string &SQLId, &LastUpdOprid;
   Local Record &PSAESTMTDEFN, &PSAESTEPDEFN, &PSAESTEPMSGDEFN;
   Local datetime &LastUpdDttm;
   Local number &AESVersion;

   &StepExist = %This.DoesStepExist(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId);
   If Not &StepExist Then
      &_ErrText = &_ErrText | "Step " | &p_stepId | " is not exist, please create step first";
   End-If;
   &ActionExist = %This.DoesActionExist(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId, &p_actionType);
   If &ActionExist Then
      &_ErrText = &_ErrText | "Action " | &p_actionType | " is readly exist, can not create action repetitive";
   End-If;

   /* SQL和Call Section是互斥的，不能同时存在与一个Step中 */
   If &p_actionType = "S" Then
      &CallSectExist = %This.DoesActionExist(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId, "C");
      If &CallSectExist Then
         &_ErrText = &_ErrText | "Call Section and SQL are mutually exclusive actions";
      End-If;
   End-If;
   If &p_actionType = "C" Then
      &SQLExist = %This.DoesActionExist(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId, "S");
      If &SQLExist Then
         &_ErrText = &_ErrText | "Call Section and SQL are mutually exclusive actions";
      End-If;
      If None(&p_callSectionId, &p_callSectionAEId) Then
         &_ErrText = &_ErrText | "callSectionId and callSectionAEId is required in CallSection action";
      End-If;
   End-If;

   /* 校验不通过的不继续处理 */
   If &_ErrText <> "" Then
      Return;
   End-If;

   /* insertAction Begin */
   If None(&p_reuseStatement) Then
      &p_reuseStatement = "N";
   End-If;

   If None(&p_descr) Then
      Evaluate &p_actionType
      When "S"
         &p_descr = "SQL";
         Break;
      When "P"
         &p_descr = "PeopleCode";
         Break;
      When "M"
         &p_descr = "Log Message";
         Break;
      When "W"
         &p_descr = "Do While";
         Break;
      When "C"
         &p_descr = "Call Section";
         Break;
      When "H"
         &p_descr = "Do When";
         Break;
      When "N"
         &p_descr = "Do Util";
         Break;
      When "X"
         &p_descr = "XSLT";
         Break;
      When "D"
         &p_descr = "Do Select";
         Break;
      End-Evaluate;
      &p_descr = &p_descr | " description";
   End-If;

   /** 锁表PSLOCK(如果前面已经上锁,这里就不重复上锁) **/
   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &AES, &AESVersion);
   If &_AESLock = False Then
      SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &AES);
      &AESVersion = &AESVersion + 1;
      &_AESLock = True;
      &ActionAesLock = True;
   End-If;

   &LastUpdDttm = %Datetime;
   &LastUpdOprid = %UserId;

   /** 创建SQLID **/
   If &p_actionType = "S" Or
         &p_actionType = "H" Or
         &p_actionType = "D" Or
         &p_actionType = "W" Or
         &p_actionType = "N" Then
      &SQLId = %This.GetSQLId(&p_section, &p_stepId, &p_actionType);
   End-If;

   /** DoSelectType默认值问题，非SQL类型的Action默认值是F，SQL类型的默认值是空 **/
   If &p_actionType = "P" Or
         &p_actionType = "C" Or
         &p_actionType = "M" Then
      &p_doSelectType = "F";
   End-If;

   /** 插入Action **/
   &PSAESTMTDEFN = CreateRecord(Record.PSAESTMTDEFN);
   &PSAESTMTDEFN.AE_APPLID.Value = &_AEId;
   &PSAESTMTDEFN.AE_SECTION.Value = &p_section;
   &PSAESTMTDEFN.MARKET.Value = &p_market;
   &PSAESTMTDEFN.DBTYPE.Value = &p_dbType;
   &PSAESTMTDEFN.EFFDT.Value = &p_effdt;
   &PSAESTMTDEFN.AE_STEP.Value = &p_stepId;
   &PSAESTMTDEFN.AE_STMT_TYPE.Value = &p_actionType;
   &PSAESTMTDEFN.AE_REUSE_STMT.Value = &p_reuseStatement;
   &PSAESTMTDEFN.AE_DO_SELECT_TYPE.Value = &p_doSelectType;
   &PSAESTMTDEFN.SQLID.Value = &SQLId;
   &PSAESTMTDEFN.DESCR.Value = &p_descr;
   If Not &PSAESTMTDEFN.Insert() Then
      &_ErrText = &_ErrText | "Insert PSAESTMTDEFN failed";
      Return;
   End-If;

   /** Call Section **/
   If &p_actionType = "C" Then
      &PSAESTEPDEFN = CreateRecord(Record.PSAESTEPDEFN);
      &PSAESTEPDEFN.AE_APPLID.Value = &_AEId;
      &PSAESTEPDEFN.AE_SECTION.Value = &p_section;
      &PSAESTEPDEFN.MARKET.Value = &p_market;
      &PSAESTEPDEFN.DBTYPE.Value = &p_dbType;
      &PSAESTEPDEFN.EFFDT.Value = &p_effdt;
      &PSAESTEPDEFN.AE_STEP.Value = &p_stepId;
      &PSAESTEPDEFN.AE_DO_SECTION.Value = &p_callSectionId;
      &PSAESTEPDEFN.AE_DO_APPL_ID.Value = &p_callSectionAEId;
      If Not &PSAESTEPDEFN.Update() Then
         &_ErrText = &_ErrText | "Update PSAESTEPDEFN failed";
         Return;
      End-If;
   End-If;

   /** Log Message **/
   If &p_actionType = "M" Then
      &PSAESTEPDEFN = CreateRecord(Record.PSAESTEPDEFN);
      &PSAESTEPDEFN.AE_APPLID.Value = &_AEId;
      &PSAESTEPDEFN.AE_SECTION.Value = &p_section;
      &PSAESTEPDEFN.MARKET.Value = &p_market;
      &PSAESTEPDEFN.DBTYPE.Value = &p_dbType;
      &PSAESTEPDEFN.EFFDT.Value = &p_effdt;
      &PSAESTEPDEFN.AE_STEP.Value = &p_stepId;
      &PSAESTEPDEFN.MESSAGE_SET_NBR.Value = &p_msgSetNbr;
      &PSAESTEPDEFN.MESSAGE_NBR.Value = &p_msgNbr;
      If Not &PSAESTEPDEFN.Update() Then
         &_ErrText = &_ErrText | "Update PSAESTEPDEFN failed";
         Return;
      End-If;

      &PSAESTEPMSGDEFN = CreateRecord(Record.PSAESTEPMSGDEFN);
      &PSAESTEPMSGDEFN.AE_APPLID.Value = &_AEId;
      &PSAESTEPMSGDEFN.AE_SECTION.Value = &p_section;
      &PSAESTEPMSGDEFN.MARKET.Value = &p_market;
      &PSAESTEPMSGDEFN.DBTYPE.Value = &p_dbType;
      &PSAESTEPMSGDEFN.EFFDT.Value = &p_effdt;
      &PSAESTEPMSGDEFN.AE_STEP.Value = &p_stepId;
      If &PSAESTEPMSGDEFN.SelectByKey() Then
         &PSAESTEPMSGDEFN.AE_MESSAGE_PARMS.Value = &p_msgParameter;
         If Not &PSAESTEPMSGDEFN.Update() Then
            &_ErrText = &_ErrText | "Insert PSAESTEPMSGDEFN failed";
            Return;
         End-If;
      Else
         &PSAESTEPMSGDEFN.AE_APPLID.Value = &_AEId;
         &PSAESTEPMSGDEFN.AE_SECTION.Value = &p_section;
         &PSAESTEPMSGDEFN.MARKET.Value = &p_market;
         &PSAESTEPMSGDEFN.DBTYPE.Value = &p_dbType;
         &PSAESTEPMSGDEFN.EFFDT.Value = &p_effdt;
         &PSAESTEPMSGDEFN.AE_STEP.Value = &p_stepId;
         &PSAESTEPMSGDEFN.AE_MESSAGE_PARMS.Value = &p_msgParameter;
         If Not &PSAESTEPMSGDEFN.Insert() Then
            &_ErrText = &_ErrText | "Update PSAESTEPMSGDEFN failed";
            Return;
         End-If;
      End-If;
   End-If;

   /** PeopleCode **/
   If &p_actionType = "P" Then
      If None(&p_pcOnReturn) Then
         &p_pcOnReturn = "S";
      End-If;
      &PSAESTEPDEFN = CreateRecord(Record.PSAESTEPDEFN);
      &PSAESTEPDEFN.AE_APPLID.Value = &_AEId;
      &PSAESTEPDEFN.AE_SECTION.Value = &p_section;
      &PSAESTEPDEFN.MARKET.Value = &p_market;
      &PSAESTEPDEFN.DBTYPE.Value = &p_dbType;
      &PSAESTEPDEFN.EFFDT.Value = &p_effdt;
      &PSAESTEPDEFN.AE_STEP.Value = &p_stepId;
      &PSAESTEPDEFN.AE_PC_ON_FALSE.Value = &p_pcOnReturn;
      If Not &PSAESTEPDEFN.Update() Then
         &_ErrText = &_ErrText | "Update PSAESTEPDEFN failed";
         Return;
      End-If;
   End-If;

   If &ActionAesLock Then
      SQLExec("UPDATE PSAESECTDEFN SET VERSION = :1,LASTUPDDTTM = :2,LASTUPDOPRID = :3 WHERE AE_APPLID = :4 AND AE_SECTION = :5", &AESVersion, &LastUpdDttm, &LastUpdOprid, &_AEId, &p_section);
      SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS);
      SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &AES, &AESVersion);
      CommitWork();
      &_AESLock = False;
   End-If;
   &ActionAesLock = False;
end-method;

method InsertStateRecord
   /+ &p_recName as String, +/
   /+ &p_isDefault as String +/
   Local string &RecExist, &PIFieldExist, &ExistingRec, &LastUpdOprid;
   Local boolean &StateLock;
   Local number &AEMVersion;
   Local datetime &LastUpdDttm;

   SQLExec("SELECT 'Y' FROM PSRECDEFN WHERE RECTYPE = 0 AND RECNAME = :1", &p_recName, &RecExist);
   If &RecExist <> "Y" Then
      &_ErrText = &_ErrText | "Record not exists,";
      Return;
   End-If;
   SQLExec("SELECT 'Y' FROM PSRECFIELD WHERE RECNAME = :1 AND FIELDNAME = 'PROCESS_INSTANCE' AND KEYCOUNT > 0", &p_recName, &PIFieldExist);
   If &PIFieldExist <> "Y" Then
      &_ErrText = &_ErrText | "PROCESS_INSTANCE not a Key field,";
      Return;
   End-If;
   SQLExec("SELECT 'Y' FROM PSAEAPPLSTATE WHERE AE_APPLID = :1 AND RECNAME = :2", &_AEId, &p_recName, &ExistingRec);
   If &ExistingRec = "Y" Then
      &_ErrText = &_ErrText | "State record already exists,";
      Return;
   End-If;
   If None(&p_isDefault) Then
      &p_isDefault = "N";
   End-If;

   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &AEM, &AEMVersion);
   If &_AEMLock = False Then
      SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &AEM);
      &AEMVersion = &AEMVersion + 1;
      &_AEMLock = True;
      &StateLock = True;
   End-If;

   &LastUpdDttm = %Datetime;
   &LastUpdOprid = %UserId;
   SQLExec("INSERT INTO PSAEAPPLSTATE (AE_APPLID, RECNAME, DEFAULT_STATE_REC) VALUES(:1, :2, :3)", &_AEId, &p_recName, &p_isDefault);

   If &StateLock Then
      SQLExec("UPDATE PSAEAPPLDEFN SET VERSION = :1,LASTUPDDTTM = :2,LASTUPDOPRID = :3 WHERE AE_APPLID = :4", &AEMVersion, &LastUpdDttm, &LastUpdOprid, &_AEId);
      SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS);
      SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &AEM, &AEMVersion);
      CommitWork();
      &_AEMLock = False;
   End-If;
   &StateLock = False;
end-method;

method InsertTempTable
   /+ &p_recName as String +/
   Local boolean &TempLock;
   Local string &LastUpdOprid, &RecExist, &PIFieldExist, &ExistingRec;
   Local number &AEMVersion;
   Local datetime &LastUpdDttm;

   /** 校验 **/
   SQLExec("SELECT 'Y' FROM PSRECDEFN WHERE RECTYPE = 0 AND RECNAME = :1", &p_recName, &RecExist);
   If &RecExist <> "Y" Then
      &_ErrText = &_ErrText | "Record not exists,";
      Return;
   End-If;
   SQLExec("SELECT 'Y' FROM PSRECFIELD WHERE RECNAME = :1 AND FIELDNAME = 'PROCESS_INSTANCE' AND KEYCOUNT > 0", &p_recName, &PIFieldExist);
   If &PIFieldExist <> "Y" Then
      &_ErrText = &_ErrText | "PROCESS_INSTANCE not a Key field,";
      Return;
   End-If;
   SQLExec("SELECT 'Y' FROM PSAEAPPLTEMPTBL WHERE AE_APPLID = :1 AND RECNAME = :2", &_AEId, &p_recName, &ExistingRec);
   If &ExistingRec = "Y" Then
      &_ErrText = &_ErrText | "Temp table already exists,";
      Return;
   End-If;

   /** 锁表 **/
   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &AEM, &AEMVersion);
   If &_AEMLock = False Then
      SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &AEM);
      &AEMVersion = &AEMVersion + 1;
      &_AEMLock = True;
      &TempLock = True;
   End-If;

   &LastUpdDttm = %Datetime;
   &LastUpdOprid = %UserId;
   SQLExec("INSERT INTO PSAEAPPLTEMPTBL (AE_APPLID, RECNAME) VALUES(:1, :2)", &_AEId, &p_recName);

   If &TempLock Then
      SQLExec("UPDATE PSAEAPPLDEFN SET VERSION = :1,LASTUPDDTTM = :2,LASTUPDOPRID = :3 WHERE AE_APPLID = :4", &AEMVersion, &LastUpdDttm, &LastUpdOprid, &_AEId);
      SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS);
      SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &AEM, &AEMVersion);
      CommitWork();
      &_AEMLock = False;
   End-If;
   &TempLock = False;
end-method;

method ViewSQL
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_stepId as String, +/
   /+ &p_actionType as String +/
   /+ Returns JsonObject +/
   Local JsonObject &RespObj;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgrSrm;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &SrmDefn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &StmtDefn;
   Local %metadata:Key &Key;
   Local string &SqlText, &SqlId, &SqlType, &ActionExist;
   Local integer &i;

   &RespObj = CreateJsonObject();
   &SqlId = %This.GetSQLId(&p_section, &p_stepId, &p_actionType);
   &SqlType = "1";
   &mgrSrm = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &Key = create %metadata:Key(Key:Class_Sql, &SqlId, Key:Class_SqlType, &SqlType);

   If Not &mgrSrm.DefnExists(&Key) Then
      rem 检查一下是否有对应的Action;
      SQLExec("SELECT 'Y' FROM PSAESTMTDEFN WHERE AE_APPLID = :1 AND AE_SECTION = :2 AND AE_STEP = :3 AND AE_STMT_TYPE = :4", &_AEId, &p_section, &p_stepId, &p_actionType, &ActionExist);
      If &ActionExist <> "Y" Then
         &_ErrText = &_ErrText | "Action not exists";
         Return &RespObj;
      Else
         &RespObj.AddProperty("sqlId", &SqlId);
         &RespObj.AddProperty("sqlType", &SqlType);
         &RespObj.AddProperty("sqlText", "");
         Return &RespObj;
      End-If;
   End-If;

   &SrmDefn = &mgrSrm.GetDefn(&Key);
   For &i = 1 To &SrmDefn.Count_StmtT
      &StmtDefn = &SrmDefn.Get_StmtT(&i);
      If &StmtDefn.Market = &p_market And
            &StmtDefn.DbType = &MappingUtil.GetDbTypeCode(&p_dbType) And
            &StmtDefn.EffDt = &p_effdt Then
         &SqlText = &StmtDefn.SqlText;
      End-If;
   End-For;

   &RespObj.AddProperty("sqlId", &SqlId);
   &RespObj.AddProperty("sqlType", &SqlType);
   &RespObj.AddProperty("sqlText", &CommUtil.EscapeJSON(&SqlText));
   &RespObj.AddProperty("stmtCount", &SrmDefn.Count_StmtT);
   &RespObj.AddProperty("lastUpdate", "Last updated by: " | &SrmDefn.LastUpdOprId | ", " | DateTimeToLocalizedString(&SrmDefn.LastUpdDttm, &DateTimeFormat));

   Return &RespObj;
end-method;

method ModifySQL
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_stepId as String, +/
   /+ &p_actionType as String, +/
   /+ &p_sqlText as String +/
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgrSrm;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &SrmDefn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &StmtDefn;
   Local %metadata:Key &Key;
   Local string &SqlText, &SqlId, &SqlType, &ActionExist;
   Local integer &i, &StmtCount;
   Local boolean &SQLExist, &SaveFlg;

   rem 校验Action是否存在;
   SQLExec("SELECT 'Y' FROM PSAESTMTDEFN WHERE AE_APPLID = :1 AND AE_SECTION = :2 AND AE_STEP = :3 AND AE_STMT_TYPE = :4", &_AEId, &p_section, &p_stepId, &p_actionType, &ActionExist);
   If &ActionExist <> "Y" Then
      &_ErrText = &_ErrText | "Action not exists";
      Return;
   End-If;

   &SqlId = %This.GetSQLId(&p_section, &p_stepId, &p_actionType);
   &SqlType = "1";
   &mgrSrm = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &Key = create %metadata:Key(Key:Class_Sql, &SqlId, Key:Class_SqlType, &SqlType);

   If Not &mgrSrm.DefnExists(&Key) Then
      &SrmDefn = &mgrSrm.CreateDefn();
      &SQLExist = False;
   Else
      &SrmDefn = &mgrSrm.GetDefnToUpdate(&Key);
      &SQLExist = True;
   End-If;

   /* 使用正则表达式去除 
 */
   &p_sqlText = &CommUtil.ReplaceWithRegex(&p_sqlText, "\s+", " ");

   /* 保存SQL */
   If &SQLExist Then
      /** 更新SQL **/
      For &i = 1 To &SrmDefn.Count_StmtT
         &StmtDefn = &SrmDefn.Get_StmtT(&i);
         If &StmtDefn.Market = &p_market And
               &StmtDefn.DbType = &MappingUtil.GetDbTypeCode(&p_dbType) And
               &StmtDefn.EffDt = &p_effdt Then
            &StmtDefn.SqlText = &p_sqlText;
            Break;
         End-If;
      End-For;
      &SaveFlg = &SrmDefn.UpdateDefn();
   Else
      /** 创建SQL(如果是指定数据库的SQL，需要建2条记录，一条默认数据库，一条特殊数据) **/
      &SrmDefn.SqlId = &SqlId;
      &SrmDefn.SqlType = &SqlType;
      &StmtDefn = &SrmDefn.Get_StmtT(1);
      &StmtDefn.Market = &p_market;
      &StmtDefn.DbType = &MappingUtil.GetDbTypeCode(&p_dbType);
      &StmtDefn.EffDt = &p_effdt;
      &StmtDefn.SqlText = &p_sqlText;
      If &p_dbType <> "" Then
         &StmtDefn = &SrmDefn.Append_StmtT(1);
         &StmtDefn.Market = &p_market;
         &StmtDefn.DbType = &MappingUtil.GetDbTypeCode(&p_dbType);
         &StmtDefn.EffDt = &p_effdt;
         &StmtDefn.SqlText = &p_sqlText;
      End-If;
      &SaveFlg = &SrmDefn.SaveNewDefn();
   End-If;

   If Not &SaveFlg Then
      &_ErrText = &_ErrText | "Save failed";
   End-If;
end-method;

method ViewPeopleCode
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_stepId as String +/
   /+ Returns JsonObject +/
   Local JsonObject &RespObj;
   Local boolean &ActionExist;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &PeopleCodeProgram;
   Local %metadata:Key &Key;

   &RespObj = CreateJsonObject();
   &ActionExist = %This.DoesActionExist(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId, "P");
   If Not &ActionExist Then
      &_ErrText = &_ErrText | "Action not exist";
      Return &RespObj;
   End-If;

   &p_dbType = &MappingUtil.GetDbTypeName(&p_dbType);
   &mgrPeopleCodeProgram = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   &Key = create %metadata:Key(Key:Class_AEApplicationId, &_AEId);
   &Key.AddItem(Key:Class_AESection, &p_section);
   &Key.AddItem(Key:Class_Market, &p_market);
   &Key.AddItem(Key:Class_DBType, &p_dbType);
   &Key.AddItem(Key:Class_EffDt, String(&p_effdt));
   &Key.AddItem(Key:Class_AEStep, &p_stepId);
   &Key.AddItem(Key:Class_Method, "OnExecute");

   &RespObj.AddProperty("programExists", &mgrPeopleCodeProgram.DefnExists(&Key));
   If &mgrPeopleCodeProgram.DefnExists(&Key) Then
      /* 获取代码 */
      &PeopleCodeProgram = &mgrPeopleCodeProgram.GetDefn(&Key);
      &RespObj.AddProperty("peoplecode", &CommUtil.EscapeJSON(&PeopleCodeProgram.GetProgram()));
      &RespObj.AddProperty("lastUpdate", "Last updated by: " | &PeopleCodeProgram.LastUpdOprId | ", " | DateTimeToLocalizedString(&PeopleCodeProgram.LastUpdDttm, &DateTimeFormat));
   Else
      /* 没有代码 */
      &RespObj.AddProperty("peoplecode", "");
      &RespObj.AddProperty("lastUpdate", "");
   End-If;

   Return &RespObj;
end-method;

method ModifyPeopleCode
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_stepId as String, +/
   /+ &p_peoplecode as String +/
   Local boolean &ActionExist, &CompileResult, &SaveResult;
   Local string &ErrorMsg;
   Local integer &Position1, &Position2;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &PeopleCodeProgram;
   Local %metadata:Key &Key;

   &ActionExist = %This.DoesActionExist(&p_section, &p_market, &p_dbType, &p_effdt, &p_stepId, "P");
   If Not &ActionExist Then
      &_ErrText = &_ErrText | "Action not exist";
      Return;
   End-If;

   &p_dbType = &MappingUtil.GetDbTypeName(&p_dbType);

   Local string &NonBlankCode = &p_peoplecode;
   &NonBlankCode = Substitute(&NonBlankCode, Char(9), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(10), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(11), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(12), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(13), "");
   If Len(LTrim(RTrim(&NonBlankCode))) = 0 Then
      throw CreateException(0, 0, "Empty PeopleCode is not deletion; use deletePeopleCode");
   End-If;
   &mgrPeopleCodeProgram = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   &Key = create %metadata:Key(Key:Class_AEApplicationId, &_AEId);
   &Key.AddItem(Key:Class_AESection, &p_section);
   &Key.AddItem(Key:Class_Market, &p_market);
   &Key.AddItem(Key:Class_DBType, &p_dbType);
   &Key.AddItem(Key:Class_EffDt, String(&p_effdt));
   &Key.AddItem(Key:Class_AEStep, &p_stepId);
   &Key.AddItem(Key:Class_Method, "OnExecute");

   If &mgrPeopleCodeProgram.DefnExists(&Key) Then
      /* 更新代码 */
      &PeopleCodeProgram = &mgrPeopleCodeProgram.GetDefnToUpdate(&Key);
      &CompileResult = &PeopleCodeProgram.UpdateProgram(&p_peoplecode, &ErrorMsg, &Position1, &Position2);
      If &CompileResult Then
         If Not &PeopleCodeProgram.UpdateDefn() Then
            &_ErrText = &_ErrText | "Error saving PeopleCode.";
         End-If;
      Else
         &_ErrText = &_ErrText | MsgGetText(158, 20153, "PeopleCode Error") | " - " | &ErrorMsg | " " | &Position1 | " " | &Position2;
      End-If;

   Else
      /* 插入代码 */
      &PeopleCodeProgram = &mgrPeopleCodeProgram.CreateDefn();
      &PeopleCodeProgram.ObjectID#0# = key:Class_AEApplicationId;
      &PeopleCodeProgram.ObjectValue#0# = &_AEId;
      &PeopleCodeProgram.ObjectID#1# = key:Class_AESection;
      &PeopleCodeProgram.ObjectValue#1# = &p_section;
      &PeopleCodeProgram.ObjectID#2# = key:Class_Market;
      &PeopleCodeProgram.ObjectValue#2# = &p_market;
      &PeopleCodeProgram.ObjectID#3# = key:Class_DBType;
      &PeopleCodeProgram.ObjectValue#3# = &p_dbType;
      &PeopleCodeProgram.ObjectID#4# = key:Class_EffDt;
      &PeopleCodeProgram.ObjectValue#4# = String(&p_effdt);
      &PeopleCodeProgram.ObjectID#5# = key:Class_AEStep;
      &PeopleCodeProgram.ObjectValue#5# = &p_stepId;
      &PeopleCodeProgram.ObjectID#6# = key:Class_Method;
      &PeopleCodeProgram.ObjectValue#6# = "OnExecute";
      &CompileResult = &PeopleCodeProgram.UpdateProgram(&p_peoplecode, &ErrorMsg, &Position1, &Position2);
      If &CompileResult Then
         If Not &PeopleCodeProgram.SaveNewDefn() Then
            &_ErrText = &_ErrText | "Error saving new PeopleCode.";
         End-If;
      Else
         &_ErrText = &_ErrText | MsgGetText(158, 20153, "PeopleCode Error") | " - " | &ErrorMsg | " " | &Position1 | " " | &Position2;
      End-If;
   End-If;
end-method;

method GetSectionInfo
   /+ &p_aeid as String, +/
   /+ &p_section as String +/
   /+ Returns JsonObject +/
   Local JsonObject &SectionObj, &DetailObj;
   Local JsonArray &Detail;
   Local Rowset &Rs;
   Local Record &Rec;
   Local integer &i;
   Local string &SectionType, &PublicAccess;

   &SectionObj = CreateJsonObject();
   &Detail = CreateJsonArray();
   /* 获取Section基本信息 */
   SQLExec(SQL.C_AI_SEL_AE_SECT2, &p_aeid, &p_section, &SectionType, &PublicAccess);
   &SectionObj.AddProperty("sectionType", &SectionType);
   &SectionObj.AddProperty("publicAccess", &PublicAccess);
   &SectionObj.AddJsonArray("detail", &Detail);

   /* Section明细 */
   &Rs = CreateRowset(Record.PSAESECTDTLDEFN);
   &Rs.Flush();
   &Rs.Fill(" WHERE AE_APPLID = :1 AND AE_SECTION = :2", &p_aeid, &p_section);
   For &i = 1 To &Rs.ActiveRowCount
      &Rec = &Rs(&i).GetRecord(1);
      &DetailObj = CreateJsonObject();
      &DetailObj.AddProperty("market", &Rec.MARKET.Value);
      &DetailObj.AddProperty("dbType", &Rec.DBTYPE.Value);
      &DetailObj.AddProperty("descr", &Rec.DESCR.Value);
      &DetailObj.AddProperty("effdt", &Rec.EFFDT.Value);
      &DetailObj.AddProperty("effStatus", &Rec.EFF_STATUS.Value);
      &DetailObj.AddProperty("autoCommit", &Rec.AE_AUTO_COMMIT.Value);
      &DetailObj.AddJsonArray("steps", %This.GetStepsBySection(&p_aeid, &p_section, &Rec.MARKET.Value, &Rec.DBTYPE.Value, &Rec.EFFDT.Value));
      &Detail.AddJsonObjectElement("", &DetailObj);
   End-For;

   Return &SectionObj;
end-method;

method GetStepsBySection
   /+ &p_aeid as String, +/
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbtype as String, +/
   /+ &p_effdt as Date +/
   /+ Returns JsonArray +/
   Local JsonArray &StepArr;
   Local Rowset &Rs;
   Local Record &Rec;
   Local integer &i;

   &StepArr = CreateJsonArray();
   &Rs = CreateRowset(Record.PSAESTEPDEFN);
   &Rs.Flush();
   &Rs.Fill(" WHERE AE_APPLID = :1 AND AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5 ", &p_aeid, &p_section, &p_market, &p_dbtype, &p_effdt);
   &Rs.Sort(PSAESTEPDEFN.AE_SEQ_NUM, "A");
   For &i = 1 To &Rs.ActiveRowCount
      &Rec = &Rs(&i).GetRecord(1);
      Local JsonObject &StepObject = CreateJsonObject();
      &StepObject.AddProperty("stepId", &Rec.AE_STEP.Value);
      &StepObject.AddProperty("activeStatus", &Rec.AE_ACTIVE_STATUS.Value);
      &StepObject.AddProperty("abendAction", &Rec.AE_ABEND_ACTION.Value);
      &StepObject.AddProperty("commitAfter", &Rec.AE_COMMIT_AFTER.Value);
      &StepObject.AddProperty("descr", &Rec.DESCR.Value);
      &StepObject.AddJsonArray("actions", %This.GetActionsByStep(&p_aeid, &p_section, &p_market, &p_dbtype, &p_effdt, &Rec.AE_STEP.Value));
      &StepArr.AddJsonObjectElement("", &StepObject);
   End-For;

   Return &StepArr;
end-method;

method GetActionsByStep
   /+ &p_aeid as String, +/
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbtype as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_step as String +/
   /+ Returns JsonArray +/
   Local JsonArray &ActionArr;
   Local SQL &StatementSql;
   Local string &StmtType, &ReuseStmt, &DoSelectType, &SQLID, &Descr;

   &ActionArr = CreateJsonArray();
   &StatementSql = CreateSQL("SELECT A.AE_STMT_TYPE,A.AE_REUSE_STMT,A.AE_DO_SELECT_TYPE,A.SQLID,A.DESCR FROM PSAESTMTDEFN A LEFT JOIN PS_C_AE_ACTION_SEQ Q ON A.AE_STMT_TYPE = Q.C_AE_ACTN_TYPE WHERE A.AE_APPLID = :1 AND A.AE_SECTION = :2 AND A.MARKET = :3 AND A.DBTYPE = :4 AND A.EFFDT = :5 AND A.AE_STEP = :6 ORDER BY Q.SEQNO", &_AEId, &p_section, &p_market, &p_dbtype, &p_effdt, &p_step);
   While &StatementSql.Fetch(&StmtType, &ReuseStmt, &DoSelectType, &SQLID, &Descr)
      Local JsonObject &ActionObj = CreateJsonObject();
      &ActionObj.AddProperty("actionType", &StmtType);

      /* 与SQL有关的Action特有的属性 */
      If &StmtType = "H" Or
            &StmtType = "W" Or
            &StmtType = "N" Or
            &StmtType = "D" Or
            &StmtType = "S" Then
         /* 是否反复使用SqlStatement，为Y时SQL只需编译一次即可多次执行，提高性能 */
         &ActionObj.AddProperty("reuseStatement", &ReuseStmt);
         &ActionObj.AddProperty("sqlId", &SQLID);
      End-If;

      /* DoSelect特有属性;Fetch一次性抓取，不可断点续传；Re-Select 每次都重查，天然可重启；Restartable：一次性抓取，但允许断点续传； */
      If &StmtType = "D" Then
         &ActionObj.AddProperty("doSelectType", &DoSelectType);
      End-If;
      &ActionObj.AddProperty("descr", &Descr);

      /* Call Section */
      If &StmtType = "C" Then
         Local string &ApplId, &SectionId;
         SQLExec("SELECT AE_DO_SECTION,AE_DO_APPL_ID FROM PSAESTEPDEFN D WHERE D.AE_APPLID = :1 AND D.AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5 AND AE_STEP = :6", &_AEId, &p_section, &p_market, &p_dbtype, &p_effdt, &p_step, &SectionId, &ApplId);
         &ActionObj.AddProperty("callSectionAeId", &ApplId);
         &ActionObj.AddProperty("callSectionId", &SectionId);
         &ActionObj.AddJsonObject("section", %This.GetSectionInfo(&ApplId, &SectionId));
      End-If;

      /* Log Message */
      If &StmtType = "M" Then
         Local number &MessageSetNbr, &MessageNbr;
         Local string &Parameters;
         SQLExec("SELECT MESSAGE_SET_NBR,MESSAGE_NBR FROM PSAESTEPDEFN D WHERE D.AE_APPLID = :1 AND D.AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5 AND AE_STEP = :6", &_AEId, &p_section, &p_market, &p_dbtype, &p_effdt, &p_step, &MessageSetNbr, &MessageNbr);
         SQLExec("SELECT AE_MESSAGE_PARMS FROM PSAESTEPMSGDEFN D WHERE D.AE_APPLID = :1 AND D.AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5 AND AE_STEP = :6", &_AEId, &p_section, &p_market, &p_dbtype, &p_effdt, &p_step, &Parameters);
         &ActionObj.AddProperty("messageSetNumber", &MessageSetNbr);
         &ActionObj.AddProperty("messageNumber", &MessageNbr);
         &ActionObj.AddProperty("messageParameters", &Parameters);
      End-If;
      &ActionArr.AddJsonObjectElement("", &ActionObj);
   End-While;

   Return &ActionArr;
end-method;

method GetStateRecords
   /+ &p_aeid as String +/
   /+ Returns JsonArray +/
   Local JsonArray &StateRecords;
   Local SQL &StateSQL;
   Local string &RecName, &DefaultState;

   &StateRecords = CreateJsonArray();
   &StateSQL = CreateSQL("SELECT AE_STATE_RECNAME,AE_DEFAULT_STATE FROM PSAEAPPLSTATE WHERE AE_APPLID = :1", &p_aeid);
   While &StateSQL.Fetch(&RecName, &DefaultState)
      Local JsonObject &StateRecObj = CreateJsonObject();
      &StateRecObj.AddProperty("recordName", &RecName);
      &StateRecObj.AddProperty("defaultState", &DefaultState);
      &StateRecords.AddJsonObjectElement("", &StateRecObj);
   End-While;

   Return &StateRecords;
end-method;

method GetTempTables
   /+ &p_aeid as String +/
   /+ Returns JsonArray +/
   Local JsonArray &TempTables;
   Local SQL &TempSQL;
   Local string &TempTable;

   &TempTables = CreateJsonArray();
   &TempSQL = CreateSQL("SELECT RECNAME FROM PSAEAPPLTEMPTBL WHERE AE_APPLID = :1", &p_aeid);
   While &TempSQL.Fetch(&TempTable)
      &TempTables.AddElement(&TempTable);
   End-While;

   Return &TempTables;
end-method;

method DoesSectionExist
   /+ &p_section as String +/
   /+ Returns Boolean +/
   Local boolean &Exist;
   Local string &Flag;
   SQLExec("SELECT 'Y' FROM PSAESECTDEFN WHERE AE_APPLID = :1 AND AE_SECTION = :2", &_AEId, &p_section, &Flag);
   If &Flag = "Y" Then
      &Exist = True;
   End-If;
   Return &Exist;
end-method;

method DoesStepExist
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_step as String +/
   /+ Returns Boolean +/
   Local boolean &Exist;
   Local string &Flag;

   SQLExec("SELECT 'Y' FROM PSAESTEPDEFN WHERE AE_APPLID = :1 AND AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5 AND AE_STEP = :6", &_AEId, &p_section, &p_market, &p_dbType, &p_effdt, &p_step, &Flag);
   If &Flag = "Y" Then
      &Exist = True;
   End-If;

   Return &Exist;
