method DoesActionExist
   /+ &p_section as String, +/
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_step as String, +/
   /+ &p_action as String +/
   /+ Returns Boolean +/
   Local boolean &Exist;
   Local string &Flag;

   SQLExec("SELECT 'Y' FROM PSAESTMTDEFN WHERE AE_APPLID = :1 AND AE_SECTION = :2 AND MARKET = :3 AND DBTYPE = :4 AND EFFDT = :5 AND AE_STEP = :6 AND AE_STMT_TYPE = :7", &_AEId, &p_section, &p_market, &p_dbType, &p_effdt, &p_step, &p_action, &Flag);
   If &Flag = "Y" Then
      &Exist = True;
   End-If;

