method OperRecordDefn
   &_ErrText = "";
   &JsonUtil = create C_PORTAL_PKG:Util:JsonUtil();
   &CommUtil = create C_PORTAL_PKG:Util:CommonUtil();
   &MappingUtil = create C_META_DATA_PKG:Utility:MappingUtil();
   &RecordUseEdit = create C_META_DATA_PKG:Utility:RecordUseEdit();
end-method;


method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;
   Local JsonObject &ReqObject, &RespObject;
   Local string &OperationType;
   Local JsonArray &JArr;
   Local integer &i;

   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());
      Local C_PORTAL_PKG:Util:JSONObject &CustObj = create C_PORTAL_PKG:Util:JSONObject(&ReqObject);

      If Not &ReqObject.IsExist("recordName") Then
         &_ErrText = &_ErrText | "recordName is required, ";
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
         Return &RespMsg;
      End-If;
      If &CustObj.IsNullProperty("recordName") Then
         &_ErrText = &_ErrText | "recordName is null, ";
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
         Return &RespMsg;
      End-If;
      &_RecName = &ReqObject.GetString("recordName");

      If Not &ReqObject.IsExist("operationType") Then
         &OperationType = "struct";
      Else
         &OperationType = &ReqObject.GetString("operationType");
      End-If;

      Evaluate &OperationType
      When "struct"
         &RespObject = %This.GetRecordStruct();
         Break;
      When "createRecord"
         %This.CreateRecordCli(&ReqObject);
         Break;
      When "buildRecord"
         If &ReqObject.IsExist("createTable") Then
            &JArr = &ReqObject.GetJsonArray("createTable");
            For &i = 1 To &JArr.Size
               %This.BuildRecordCli(&JArr.GetString(&i));
            End-For;
         End-If;
         If &ReqObject.IsExist("alterTable") Then
            &JArr = &ReqObject.GetJsonArray("alterTable");
            For &i = 1 To &JArr.Size
               %This.AlterRecordCli(&JArr.GetString(&i));
            End-For;
         End-If;
         If &ReqObject.IsExist("createView") Then
            &JArr = &ReqObject.GetJsonArray("createView");
            For &i = 1 To &JArr.Size
               %This.CreateViewCli(&JArr.GetString(&i));
            End-For;
         End-If;
         Break;
      When "modifyRecord"
         %This.ModifyRecordCli(&ReqObject);
         Break;
      When "viewPeopleCode"
         &RespObject = %This.ViewPeopleCodeCli(&ReqObject);
         Break;
      When "deletePeopleCode"
         &RespObject = %This.DeletePeopleCodeCli(&ReqObject);
         Break;
      When "modifyPeopleCode"
         %This.ModifyPeopleCodeCli(&ReqObject);
         Break;
      When "viewSQL"
         &RespObject = %This.ViewSqlCli(&ReqObject);
         Break;
      When "modifySQL"
         %This.ModifySqlCli(&ReqObject);
         Break;
      When-Other
         &_ErrText = &_ErrText | "unknow operationType, ";
      End-Evaluate;

      If &_ErrText = "" Then
         &RespMsg = &JsonUtil.CreateSuccessMessage(&OperationName, &RespObject);
      Else
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_ErrText);
      End-If;
   catch Exception &ex
      SQLExec("rollback");
      &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 999, "Error: " | &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

method GetRecordStruct
   /+ Returns JsonObject +/
   Local JsonObject &RecordStruct, &RecFieldObj, &SubRecFldObj, &IndexObj, &IndexFldObj;
   Local JsonArray &RecFields, &SubRecFieldArr, &IndexArr, &IndexFldArr, &RecordPeople;
   Local Rowset &RsPSRECFIELD, &RsSubRecField, &RsPSINDEXDEFN, &RsPSKEYDEFN;
   Local Record &PSRECDEFN, &PSRECFIELD, &PSSUBRECFIELD, &PSINDEXDEFN, &PSKEYDEFN, &PSDBFIELD;
   Local integer &i, &j;
   Local boolean &Bool;

   &RecordStruct = CreateJsonObject();
   &PSRECDEFN = CreateRecord(Record.PSRECDEFN);
   &PSRECDEFN.RECNAME.Value = &_RecName;
   If Not &PSRECDEFN.SelectByKey() Then
      &_ErrText = &_ErrText | "Record not exist, ";
      Return &RecordStruct;
   End-If;

   &RecordStruct.AddProperty("recName", &PSRECDEFN.RECNAME.Value);
   &RecordStruct.AddProperty("fieldCount", &PSRECDEFN.GetField(Field.FIELDCOUNT).Value);
   &RecordStruct.AddProperty("indexCount", &PSRECDEFN.INDEXCOUNT.Value);
   &RecordStruct.AddProperty("DDLCount", &PSRECDEFN.DDLCOUNT.Value);
   &RecordStruct.AddProperty("auditRecName", &PSRECDEFN.AUDITRECNAME.Value);
   &RecordStruct.AddJsonArray("auditOption", &RecordUseEdit.GetRecordUseProperty(&PSRECDEFN.RECUSE.Value));
   &RecordStruct.AddProperty("recordType", &PSRECDEFN.RECTYPE.Value);
   &RecordStruct.AddProperty("setControlField", &PSRECDEFN.SETCNTRLFLD.Value);
   &RecordStruct.AddProperty("relateLanguageRecord", &PSRECDEFN.GetField(Field.RELLANGRECNAME).Value);
   &RecordStruct.AddProperty("analyticDeleteRecord", &PSRECDEFN.OPTDELRECNAME.Value);
   &RecordStruct.AddProperty("descr", &PSRECDEFN.RECDESCR.Value);
   &RecordStruct.AddProperty("parentRecName", &PSRECDEFN.PARENTRECNAME.Value);
   &RecordStruct.AddProperty("querySecurityRecord", &PSRECDEFN.QRYSECRECNAME.Value);
   &RecordStruct.AddProperty("sqlTableName", &PSRECDEFN.SQLTABLENAME.Value);
   &RecordStruct.AddProperty("buildSqlNo", &PSRECDEFN.BUILDSEQNO.Value);
   &RecordStruct.AddProperty("lastUpdate", "Last updated by: " | &PSRECDEFN.LASTUPDOPRID.Value | ", " | DateTimeToLocalizedString(&PSRECDEFN.LASTUPDDTTM.Value, &DateTimeFormat));
   &RecordStruct.AddProperty("comment", &CommUtil.EscapeJSON(&PSRECDEFN.DESCRLONG.Value));

   &RecFields = CreateJsonArray();
   &RsPSRECFIELD = CreateRowset(Record.PSRECFIELD);
   &RsPSRECFIELD.Flush();
   &RsPSRECFIELD.Fill(" WHERE RECNAME = :1", &_RecName);
   &RsPSRECFIELD.Sort(PSRECFIELD.FIELDNUM, "A");
   &RecordPeople = %This.GetPeopleCodeEventByRecord(&_RecName);
   For &i = 1 To &RsPSRECFIELD.ActiveRowCount
      &PSRECFIELD = &RsPSRECFIELD(&i).GetRecord(1);
      &RecFieldObj = CreateJsonObject();

      &RecFieldObj.AddProperty("fieldName", &PSRECFIELD.FIELDNAME.Value);
      If &PSRECFIELD.SUBRECORD.Value = "N" Then
         &PSDBFIELD = CreateRecord(Record.PSDBFIELD);
         &PSDBFIELD.FIELDNAME.Value = &PSRECFIELD.FIELDNAME.Value;
         If &PSDBFIELD.SelectByKey() Then
            &RecFieldObj.AddProperty("fieldType", &MappingUtil.GetFieldTypeName(&PSDBFIELD.FIELDTYPE.Value, &PSDBFIELD.IMAGE_FMT.Value));
            &RecFieldObj.AddProperty("length", &PSDBFIELD.LENGTH.Value);
         Else
            &_ErrText = &_ErrText | "Field not exist, " | &PSRECFIELD.FIELDNAME.Value | ", ";
         End-If;
      End-If;
      &RecFieldObj.AddProperty("defaultRecName", &PSRECFIELD.DEFRECNAME.Value);
      &RecFieldObj.AddProperty("defaultFieldName", &PSRECFIELD.DEFFIELDNAME.Value);
      &RecFieldObj.AddProperty("editTable", &PSRECFIELD.EDITTABLE.Value);
      &RecFieldObj.AddProperty("subRecord", &PSRECFIELD.SUBRECORD.Value);
      &RecFieldObj.AddProperty("useEdit", &PSRECFIELD.USEEDIT.Value);
      &RecFieldObj.AddProperty("useEdit2", &PSRECFIELD.USEEDIT2.Value);
      &RecFieldObj.AddProperty("defGuiControl", &PSRECFIELD.DEFGUICONTROL.Value);
      &RecFieldObj.AddProperty("setControlField", &PSRECFIELD.SETCNTRLFLD.Value);
      &RecFieldObj.AddProperty("labelId", &PSRECFIELD.LABEL_ID.Value);
      &RecFieldObj.AddJsonArray("fieldProperty", &RecordUseEdit.GetFieldPropertyByUseEdit(&PSRECFIELD.USEEDIT.Value, &PSRECFIELD.USEEDIT2.Value));
      &RecFieldObj.AddProperty("lastUpdate", "Last updated by: " | &PSRECFIELD.LASTUPDOPRID.Value | ", " | DateTimeToLocalizedString(&PSRECFIELD.LASTUPDDTTM.Value, &DateTimeFormat));
      If &PSRECFIELD.SUBRECORD.Value = "Y" Then
         &SubRecFieldArr = %This.GetSubRecFields(&PSRECFIELD.FIELDNAME.Value);
         &RecFieldObj.AddJsonArray("subRecFields", &SubRecFieldArr);
      End-If;
      &RecFieldObj.AddJsonArray("events", %This.GetPeopleCodeEventByField(&PSRECFIELD.FIELDNAME.Value, &RecordPeople));
      &RecFields.AddJsonObjectElement("", &RecFieldObj);
   End-For;
   &RecordStruct.AddJsonArray("fields", &RecFields);


   &IndexArr = CreateJsonArray();
   &RsPSKEYDEFN = CreateRowset(Record.PSKEYDEFN);
   &RsPSINDEXDEFN = CreateRowset(Record.PSINDEXDEFN, &RsPSKEYDEFN);
   &RsPSINDEXDEFN.Flush();
   &RsPSINDEXDEFN.Fill(" WHERE RECNAME = :1", &_RecName);
   &RsPSINDEXDEFN.Sort(PSINDEXDEFN.INDEXID, "A");
   For &i = 1 To &RsPSINDEXDEFN.ActiveRowCount
      &RsPSKEYDEFN = &RsPSINDEXDEFN(&i).GetRowset(Scroll.PSKEYDEFN);
      &PSINDEXDEFN = &RsPSINDEXDEFN(&i).GetRecord(1);
      &IndexObj = CreateJsonObject();
      &IndexFldArr = CreateJsonArray();
      &IndexObj.AddProperty("indexId", &PSINDEXDEFN.INDEXID.Value);
      &IndexObj.AddProperty("indexType", &PSINDEXDEFN.INDEXTYPE.Value);
      &IndexObj.AddProperty("uniqueFlag", &PSINDEXDEFN.UNIQUEFLAG.Value);
      &IndexObj.AddProperty("clusterFlag", &PSINDEXDEFN.CLUSTERFLAG.Value);
      &IndexObj.AddProperty("keyCount", &PSINDEXDEFN.KEYCOUNT.Value);
      &IndexObj.AddProperty("DDLCount", &PSINDEXDEFN.DDLCOUNT.Value);
      &IndexObj.AddProperty("SQLBasePlatform", &PSINDEXDEFN.PLATFORM_SBS.Value);
      &IndexObj.AddProperty("DB2Platform", &PSINDEXDEFN.PLATFORM_DB2.Value);
      &IndexObj.AddProperty("OraclePlatform", &PSINDEXDEFN.PLATFORM_ORA.Value);
      &IndexObj.AddProperty("InformixPlatform", &PSINDEXDEFN.PLATFORM_INF.Value);
      &IndexObj.AddProperty("DB2UnixPlatform", &PSINDEXDEFN.PLATFORM_DBX.Value);
      &IndexObj.AddProperty("AllBasePlatform", &PSINDEXDEFN.PLATFORM_ALB.Value);
      &IndexObj.AddProperty("SybasePlatform", &PSINDEXDEFN.PLATFORM_SYB.Value);
      &IndexObj.AddProperty("SqlServerPlatform", &PSINDEXDEFN.PLATFORM_MSS.Value);
      &IndexObj.AddProperty("DB2/400Platform", &PSINDEXDEFN.PLATFORM_DB4.Value);
      &IndexObj.AddProperty("comment", &CommUtil.EscapeJSON(&PSINDEXDEFN.IDXCOMMENTS.Value));
      &IndexObj.AddProperty("indexFields", &IndexFldArr);
      &RsPSKEYDEFN.Flush();
      &RsPSKEYDEFN.Fill(" WHERE RECNAME = :1 AND INDEXID = :2", &_RecName, &PSINDEXDEFN.INDEXID.Value);
      &RsPSKEYDEFN.Sort(PSKEYDEFN.KEYPOSN, "A");
      For &j = 1 To &RsPSKEYDEFN.ActiveRowCount
         &IndexFldObj = CreateJsonObject();
         &PSKEYDEFN = &RsPSKEYDEFN(&j).GetRecord(1);
         &IndexFldObj.AddProperty("fieldName", &PSKEYDEFN.FIELDNAME.Value);
         &IndexFldObj.AddProperty("ascDesc", &PSKEYDEFN.ASCDESC.Value);
         &IndexFldArr.AddJsonObjectElement("", &IndexFldObj);
      End-For;
      &IndexArr.AddJsonObjectElement("", &IndexObj);
   End-For;
   &RecordStruct.AddJsonArray("indexes", &IndexArr);

   &RecordStruct.AddJsonArray("tableSpace", %This.GetTableSpace(&_RecName));

   Return &RecordStruct;
end-method;

method BuildPSRECDEFN
   /+ &p_obj as JsonObject, +/
   /+ &p_RecName as String, +/
   /+ &p_RecType as Integer, +/
   /+ &p_FieldCount as Integer +/
   /+ Returns Record +/
   Local Record &PSRECDEFN;

   &PSRECDEFN = CreateRecord(Record.PSRECDEFN);
   &PSRECDEFN.RECNAME.Value = &p_RecName;
   &PSRECDEFN.GetField(Field.FIELDCOUNT).Value = &p_FieldCount;
   &PSRECDEFN.DDLCOUNT.Value = 0;
   &PSRECDEFN.RECTYPE.Value = &p_RecType;
   If &p_obj.IsExist("auditRecName") Then
      &PSRECDEFN.AUDITRECNAME.Value = &p_obj.GetString("auditRecName");
   End-If;
   If &p_obj.IsExist("auditOption") Then
      &PSRECDEFN.RECUSE.Value = &RecordUseEdit.GetRecuseByRecordUseProperty(&p_obj.GetJsonArray("auditOption"));
   End-If;
   If &p_obj.IsExist("setControlField") Then
      &PSRECDEFN.SETCNTRLFLD.Value = &p_obj.GetString("setControlField");
   End-If;
   If &p_obj.IsExist("relateLanguageRecord") Then
      &PSRECDEFN.GetField(Field.RELLANGRECNAME).Value = &p_obj.GetString("relateLanguageRecord");
   End-If;
   If &p_obj.IsExist("analyticDeleteRecord") Then
      &PSRECDEFN.OPTDELRECNAME.Value = &p_obj.GetString("analyticDeleteRecord");
   End-If;
   If &p_obj.IsExist("descr") Then
      &PSRECDEFN.RECDESCR.Value = &p_obj.GetString("descr");
   End-If;
   If &p_obj.IsExist("parentRecName") Then
      &PSRECDEFN.PARENTRECNAME.Value = &p_obj.GetString("parentRecName");
   End-If;
   If &p_obj.IsExist("querySecurityRecord") Then
      &PSRECDEFN.QRYSECRECNAME.Value = &p_obj.GetString("querySecurityRecord");
   End-If;
   If &p_obj.IsExist("sqlTableName") Then
      &PSRECDEFN.SQLTABLENAME.Value = &p_obj.GetString("sqlTableName");
   End-If;
   If &p_obj.IsExist("buildSqlNo") Then
      &PSRECDEFN.BUILDSEQNO.Value = &p_obj.GetNumber("buildSqlNo");
   Else
      &PSRECDEFN.BUILDSEQNO.Value = 1;
   End-If;
   If &p_obj.IsExist("optTrigFlag") Then
      &PSRECDEFN.OPTTRIGFLAG.Value = &p_obj.GetString("optTrigFlag");
   End-If;
   If &p_obj.IsExist("objectOwnerId") Then
      &PSRECDEFN.OBJECTOWNERID.Value = &p_obj.GetString("objectOwnerId");
   End-If;
   &PSRECDEFN.LASTUPDDTTM.Value = %Datetime;
   &PSRECDEFN.LASTUPDOPRID.Value = %UserId;
   &PSRECDEFN.AUXFLAGMASK.Value = 0;
   If &p_obj.IsExist("comment") Then
      &PSRECDEFN.DESCRLONG.Value = &CommUtil.UnEscapeJSON(&p_obj.GetString("comment"));
   End-If;

   Return &PSRECDEFN;
end-method;


method BuildPSRECFIELDs
   /+ &JFields as JsonArray, +/
   /+ &p_RecName as String, +/
   /+ &UniqueKeyFields as JsonArray out +/
   /+ Returns Rowset +/
   Local integer &i, &j, &k, &ReqDpc, &FldType, &FldCnt, &XlatCnt, &ImgFmt;
   Local number &NewUseEdit2;
   Local string &FieldName, &Err, &EditTableVal;
   Local boolean &HasXlatB, &IsSubRecReq;
   Local Record &PSRECFIELD;
   Local Rowset &RsPSRECFIELDs;
   Local JsonObject &JRecFieldObj, &KeyFieldObj;
   Local JsonArray &JFieldProperty;
   Local boolean &IsDesc;

   &UniqueKeyFields = CreateJsonArray();
   &RsPSRECFIELDs = CreateRowset(Record.PSRECFIELD);

   For &i = 1 To &JFields.Size
      If &i <> 1 Then
         &RsPSRECFIELDs.InsertRow(&i - 1);
      End-If;

      &JRecFieldObj = &JFields.GetJsonObject(&i);
      &PSRECFIELD = &RsPSRECFIELDs(&i).GetRecord(1);
      If Not &JRecFieldObj.IsExist("fieldName") Then
         &_ErrText = &_ErrText | "fieldName is required, ";
      End-If;
      &FieldName = &JRecFieldObj.GetString("fieldName");
      &PSRECFIELD.GetField(Field.RECNAME).Value = &p_RecName;
      &PSRECFIELD.GetField(Field.FIELDNAME).Value = &FieldName;
      &PSRECFIELD.GetField(Field.FIELDNUM).Value = &i;
      If &JRecFieldObj.IsExist("defaultRecName") Then
         &PSRECFIELD.DEFRECNAME.Value = &JRecFieldObj.GetString("defaultRecName");
      End-If;
      If &JRecFieldObj.IsExist("defaultFieldName") Then
         &PSRECFIELD.DEFFIELDNAME.Value = &JRecFieldObj.GetString("defaultFieldName");
      End-If;
      If &JRecFieldObj.IsExist("editTable") Then
         &PSRECFIELD.EDITTABLE.Value = &JRecFieldObj.GetString("editTable");
      End-If;
      If &JRecFieldObj.IsExist("subRecord") Then
         &PSRECFIELD.SUBRECORD.Value = &JRecFieldObj.GetString("subRecord");
      Else
         &PSRECFIELD.SUBRECORD.Value = "N";
      End-If;
      If &JRecFieldObj.IsExist("fieldProperty") Then
         &JFieldProperty = &JRecFieldObj.GetJsonArray("fieldProperty");
      Else
         &JFieldProperty = CreateJsonArray();
      End-If;
      &PSRECFIELD.USEEDIT.Value = &RecordUseEdit.GetUseEditByFieldProperty(&JRecFieldObj);
      REM USEEDIT2在Record缓冲区是无符号字段（赋负数抛2,121）：PersistInMenu高位先写+2^32孪生值，CreateRecordCli插入后统一转回带符号;
      &NewUseEdit2 = &RecordUseEdit.GetUseEdit2ByFieldProperty(&JFieldProperty);
      If &NewUseEdit2 < 0 Then
         &PSRECFIELD.USEEDIT2.Value = &NewUseEdit2 + 4294967296;
      Else
         &PSRECFIELD.USEEDIT2.Value = &NewUseEdit2;
      End-If;

      REM 默认页面控件（GUI: Default Page Control），未提供时保持99=System Default;
      &ReqDpc = 99;
      If &JRecFieldObj.IsExist("defaultPageControl") Then
         &ReqDpc = %This.MapDefGuiControl(&JRecFieldObj.GetString("defaultPageControl"));
         If &ReqDpc = - 1 Then
            &_ErrText = &_ErrText | &FieldName | ": unknown defaultPageControl value '" | &JRecFieldObj.GetString("defaultPageControl") | "' (use System Default, Edit Box or a numeric code), ";
         End-If;
      End-If;
      &PSRECFIELD.DEFGUICONTROL.Value = &ReqDpc;

      REM 子记录引用字段：AD不提供属性面板，任何fieldProperty都拒绝（子记录定义不在PSDBFIELD，无需查存在性）;
      If &JRecFieldObj.GetString("subRecord") = "Y" Then
         &Err = &RecordUseEdit.ValidateFieldProperty(&JFieldProperty, "", "", 99, False, True);
         If &Err <> "" Then
            &_ErrText = &_ErrText | &FieldName | ": " | &Err;
         End-If;
      Else
         &FldCnt = 0;
         SQLExec("SELECT COUNT(*) FROM PSDBFIELD WHERE FIELDNAME = :1", &FieldName, &FldCnt);
         If &FldCnt = 0 Then
            &_ErrText = &_ErrText | &FieldName | ": field does not exist in PSDBFIELD, ";
         Else
            &FldType = 0;
            &ImgFmt = 0;
            SQLExec("SELECT FIELDTYPE, IMAGE_FMT FROM PSDBFIELD WHERE FIELDNAME = :1", &FieldName, &FldType, &ImgFmt);
            &EditTableVal = "";
            If &JRecFieldObj.IsExist("editTable") Then
               &EditTableVal = &JRecFieldObj.GetString("editTable");
            End-If;
            &XlatCnt = 0;
            SQLExec("SELECT COUNT(*) FROM PSXLATDEFN WHERE FIELDNAME = :1", &FieldName, &XlatCnt);
            &HasXlatB = (&XlatCnt > 0);
            &Err = &RecordUseEdit.ValidateFieldProperty(&JFieldProperty, &MappingUtil.GetFieldTypeName(&FldType, &ImgFmt), &EditTableVal, &ReqDpc, &HasXlatB, False);
            If &Err <> "" Then
               &_ErrText = &_ErrText | &FieldName | ": " | &Err;
            End-If;
         End-If;
      End-If;
      If &JRecFieldObj.IsExist("setControlField") Then
         &PSRECFIELD.SETCNTRLFLD.Value = &JRecFieldObj.GetString("setControlField");
      End-If;
      If &JRecFieldObj.IsExist("labelId") Then
         &PSRECFIELD.LABEL_ID.Value = &JRecFieldObj.GetString("labelId");
      End-If;
      &PSRECFIELD.LASTUPDOPRID.Value = %UserId;
      &PSRECFIELD.LASTUPDDTTM.Value = %Datetime;

      /* 收集Key字段（含升降序） */
      For &j = 1 To &JFieldProperty.Size
         If &JFieldProperty.GetString(&j) = "Key" Then
            &KeyFieldObj = CreateJsonObject();
            &KeyFieldObj.AddProperty("fieldName", &FieldName);
            /* 检查 DescendingKey */
            &IsDesc = False;
            For &k = 1 To &JFieldProperty.Size
               If &JFieldProperty.GetString(&k) = "DescendingKey" Then
                  &IsDesc = True;
                  Break;
               End-If;
            End-For;
            If &IsDesc Then
               &KeyFieldObj.AddProperty("ascDesc", "0");
            Else
               &KeyFieldObj.AddProperty("ascDesc", "1");
            End-If;
            &UniqueKeyFields.AddJsonObjectElement("", &KeyFieldObj);
            Break;
         End-If;
      End-For;

   End-For;

   Return &RsPSRECFIELDs;
end-method;

method CreateRecordCli
   /+ &p_obj as JsonObject +/
   Local integer &i, &j, &ci;
   Local string &RecName, &SafeRec, &ch;
   Local integer &RecType, &RDMVersion;
   Local Record &PSRECDEFN;
   Local Rowset &IndexRs, &RsFields;
   Local JsonArray &UniqueKeyFields;
   Local Rowset &RsFieldDB;
   Local JsonArray &JFields, &JIndexes;
   Local JsonArray &RequiredTableSpaceArr;
   Local boolean &HasAuditOption, &HasAuditRecName;
   Local JsonArray &AuditOptionArr;
   Local string &AuditRecName;

   /* 参数校验 */
   If Not &p_obj.IsExist("recName") Then
      &_ErrText = &_ErrText | "recName is required, ";
   End-If;
   If Not &p_obj.IsExist("recordType") Then
      &_ErrText = &_ErrText | "recordType is required, ";
   End-If;
   If Not &p_obj.IsExist("fields") Then
      &_ErrText = &_ErrText | "At least one field is required to create a Record, ";
   Else
      &JFields = &p_obj.GetJsonArray("fields");
      If &JFields.Size <= 0 Then
         &_ErrText = &_ErrText | "At least one field is required to create a Record, ";
      End-If;
   End-If;

   /* auditRecName 与 auditOption 双向校验 */
   &HasAuditOption = False;
   &HasAuditRecName = False;
   If &p_obj.IsExist("auditOption") Then
      &AuditOptionArr = &p_obj.GetJsonArray("auditOption");
      If &AuditOptionArr.Size > 0 Then
         &HasAuditOption = True;
      End-If;
   End-If;
   If &p_obj.IsExist("auditRecName") Then
      &AuditRecName = &p_obj.GetString("auditRecName");
      If &AuditRecName <> "" Then
         &HasAuditRecName = True;
      End-If;
   End-If;
   If &HasAuditOption Then
      If Not &HasAuditRecName Then
         &_ErrText = &_ErrText | "auditRecName is required when auditOption is enabled, ";
      End-If;
   End-If;
   If &HasAuditRecName Then
      If Not &HasAuditOption Then
         &_ErrText = &_ErrText | "at least one auditOption is required when auditRecName is provided, ";
      End-If;
   End-If;

   If &_ErrText <> "" Then
      Return;
   End-If;

   If &p_obj.IsExist("indexes") Then
      &JIndexes = &p_obj.GetJsonArray("indexes");
   End-If;

   &RecName = &p_obj.GetString("recName");
   &RecType = &p_obj.GetNumber("recordType");
   If &RecType = 0 Or
         &RecType = 7 Then
      If Not &p_obj.IsExist("tableSpace") Then
         &_ErrText = &_ErrText | "tableSpace is required for Table and Template Table records, ";
         Return;
      End-If;
      &RequiredTableSpaceArr = &p_obj.GetJsonArray("tableSpace");
      If &RequiredTableSpaceArr.Size <= 0 Then
         &_ErrText = &_ErrText | "tableSpace is required for Table and Template Table records, ";
         Return;
      End-If;
      For &i = 1 To &RequiredTableSpaceArr.Size
         If &RequiredTableSpaceArr.GetJsonObject(&i).GetString("spaceName") = "" Then
            &_ErrText = &_ErrText | "tableSpace.spaceName is required for Table and Template Table records, ";
            Return;
         End-If;
      End-For;
   End-If;

   /* 构建PSRECDEFN */
   &PSRECDEFN = %This.BuildPSRECDEFN(&p_obj, &RecName, &RecType, &JFields.Size);

   /* 构建PSRECFIELDs */
   &RsFields = %This.BuildPSRECFIELDs(&JFields, &RecName, &UniqueKeyFields);
   If &_ErrText <> "" Then
      Return;
   End-If;

   /* 转换为PSRECFIELDDB */
   &RsFieldDB = %This.BuildPSRECFIELDDBs(&RsFields);

   /* 构建索引 */
   If &JIndexes = Null Then
      &JIndexes = CreateJsonArray();
   End-If;
   If &UniqueKeyFields.Size > 0 And
         &RecType = 0 Then
      &JIndexes.AddJsonObjectElement("", %This.CreatePrimaryKeyIndexJson(&UniqueKeyFields));
   End-If;
   If &JIndexes.Size > 0 Then
      &IndexRs = %This.GetIndexRecord(&JIndexes);
      &PSRECDEFN.INDEXCOUNT.Value = &IndexRs.ActiveRowCount;
   Else
      &PSRECDEFN.INDEXCOUNT.Value = 0;
   End-If;

   /* 锁管理 */
   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &RDM, &RDMVersion);
   &_RDMLock = True;
   SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &RDM);
   &RDMVersion = &RDMVersion + 1;

   /** 插入Record定义 **/
   If Not &PSRECDEFN.Insert() Then
      &_ErrText = &_ErrText | "insert PSRECDEFN error";
      Return;
   End-If;

   /** 插入Record字段 **/
   For &i = 1 To &RsFields.ActiveRowCount
      If Not &RsFields(&i).GetRecord(1).Insert() Then
         &_ErrText = &_ErrText | "insert PSRECFIELD error";
         Return;
      End-If;
   End-For;
   For &i = 1 To &RsFieldDB.ActiveRowCount
      If Not &RsFieldDB(&i).GetRecord(1).Insert() Then
         &_ErrText = &_ErrText | "insert PSRECFIELDDB error";
         Return;
      End-If;
   End-For;

   REM PersistInMenu高位：插入时写的是+2^32孪生值，统一转回带符号（PSRECFIELDDB经CopyFieldsTo同为孪生值）;
   REM 记录名按字符白名单消毒后内联（本服务的BuildSelectSql同样内联recordName），避免UPDATE-WHERE绑定的运行时歧义;
   &SafeRec = "";
   &ch = " ";
   For &ci = 1 To Len(&RecName)
      &ch = Substring(&RecName, &ci, 1);
      If (&ch >= "A" And
            &ch <= "Z") Or
            (&ch >= "0" And
               &ch <= "9") Or
            &ch = "_" Then
         &SafeRec = &SafeRec | &ch;
      End-If;
   End-For;
   If &SafeRec <> "" Then
      SQLExec("UPDATE PSRECFIELD SET USEEDIT2 = USEEDIT2 - 4294967296 WHERE RECNAME = '" | &SafeRec | "' AND USEEDIT2 >= 2147483648");
      SQLExec("UPDATE PSRECFIELDDB SET USEEDIT2 = USEEDIT2 - 4294967296 WHERE (RECNAME = '" | &SafeRec | "' OR RECNAME_PARENT = '" | &SafeRec | "') AND USEEDIT2 >= 2147483648");
   End-If;

   /** 插入Record索引 **/
   If &JIndexes.Size > 0 Then
      For &i = 1 To &IndexRs.ActiveRowCount
         Local Rowset &KeyRs = &IndexRs(&i).GetRowset(Scroll.PSKEYDEFN);
         For &j = 1 To &KeyRs.ActiveRowCount
            If Not &KeyRs(&j).GetRecord(1).Insert() Then
               &_ErrText = &_ErrText | "insert PSKEYDEFN error";
               Return;
            End-If;
         End-For;
         If Not &IndexRs(&i).GetRecord(1).Insert() Then
            &_ErrText = &_ErrText | "insert PSINDEXDEFN error";
            Return;
         End-If;
      End-For;
   End-If;

   /** 插入Record表空间 **/
   If &p_obj.IsExist("tableSpace") Then
      Local JsonArray &TableSpaceArr = &p_obj.GetJsonArray("tableSpace");
      Local integer &ts;
      For &ts = 1 To &TableSpaceArr.Size
         Local JsonObject &SpaceObj = &TableSpaceArr.GetJsonObject(&ts);
         Local Record &PSRECTBLSPC = CreateRecord(Record.PSRECTBLSPC);
         &PSRECTBLSPC.GetField(Field.RECNAME).Value = &RecName;
         &PSRECTBLSPC.DDLSPACENAME.Value = &SpaceObj.GetString("spaceName");
         &PSRECTBLSPC.DBNAME.Value = &SpaceObj.GetString("dbName");
         If Not &PSRECTBLSPC.Insert() Then
            &_ErrText = &_ErrText | "insert PSRECTBLSPC error";
            Return;
         End-If;
      End-For;
   End-If;

   SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS);
   SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &RDM, &RDMVersion);
   &_RDMLock = False;
   CommitWork();
end-method;


method BuildRecordCli
   /+ &p_RecName as String +/
   Local string &RecName, &SqlTableName, &Sql, &FieldName, &OracleType, &SubRecord;
   Local string &SpaceName, &SqlIndex, &IdxFieldList, &IdxId, &IdxName;
   Local string &SubFieldName, &ClobFields, &BlobFields, &FieldDef;
   Local integer &i, &j, &k, &ColumnCount;
   Local integer &TableExists;
   Local integer &UniqueFlag;
   Local Rowset &RsFields, &RsSubFields, &RsIndex, &RsKey;
   Local boolean &IsFirst;

   &_ErrText = "";
   &RecName = &p_RecName;

   REM 第1步：确定SQL表名;
   &SqlTableName = "";
   SQLExec("SELECT NVL(SQLTABLENAME, '') FROM PSRECDEFN WHERE RECNAME = :1", &RecName, &SqlTableName);
   If &SqlTableName = "" Then
      &SqlTableName = "PS_" | &RecName;
   End-If;

   REM 第2步：构建CREATE TABLE SQL;
   REM CLOB/BLOB字段缓存后追加到末尾（与AD行为一致）;
   &Sql = "CREATE TABLE " | &SqlTableName | " (";
   &ClobFields = "";
   &BlobFields = "";
   &IsFirst = True;
   &ColumnCount = 0;

   &RsFields = CreateRowset(Record.PSRECFIELD);
   &RsFields.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &RecName);

   For &i = 1 To &RsFields.RowCount
      &FieldName = &RsFields.GetRow(&i).PSRECFIELD.FIELDNAME.Value;
      &SubRecord = &RsFields.GetRow(&i).PSRECFIELD.SUBRECORD.Value;

      If &SubRecord = "Y" Then
         REM 按顺序展开子记录字段;
         &RsSubFields = CreateRowset(Record.PSRECFIELD);
         &RsSubFields.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &FieldName);

         For &j = 1 To &RsSubFields.RowCount
            &SubFieldName = &RsSubFields.GetRow(&j).PSRECFIELD.FIELDNAME.Value;
            &OracleType = %This.GetFieldOracleType(&SubFieldName);
            If &OracleType = "" Then
               Continue;
            End-If;
            &FieldDef = &SubFieldName | " " | &OracleType;
            If &OracleType = "CLOB" Then
               If &ClobFields <> "" Then
                  &ClobFields = &ClobFields | ", ";
               End-If;
               &ClobFields = &ClobFields | &FieldDef;
            Else
               If &OracleType = "BLOB" Then
                  If &BlobFields <> "" Then
                     &BlobFields = &BlobFields | ", ";
                  End-If;
                  &BlobFields = &BlobFields | &FieldDef;
               Else
                  If Not &IsFirst Then
                     &Sql = &Sql | ", ";
                  End-If;
                  &Sql = &Sql | &FieldDef;
                  &IsFirst = False;
               End-If;
            End-If;
            &ColumnCount = &ColumnCount + 1;
         End-For;
      Else
         &OracleType = %This.GetFieldOracleType(&FieldName);
         If &OracleType = "" Then
            Continue;
         End-If;
         &FieldDef = &FieldName | " " | &OracleType;
         If &OracleType = "CLOB" Then
            If &ClobFields <> "" Then
               &ClobFields = &ClobFields | ", ";
            End-If;
            &ClobFields = &ClobFields | &FieldDef;
         Else
            If &OracleType = "BLOB" Then
               If &BlobFields <> "" Then
                  &BlobFields = &BlobFields | ", ";
               End-If;
               &BlobFields = &BlobFields | &FieldDef;
            Else
               If Not &IsFirst Then
                  &Sql = &Sql | ", ";
               End-If;
               &Sql = &Sql | &FieldDef;
               &IsFirst = False;
            End-If;
         End-If;
         &ColumnCount = &ColumnCount + 1;
      End-If;
   End-For;

   REM 追加CLOB字段;
   If &ClobFields <> "" Then
      If Not &IsFirst Then
         &Sql = &Sql | ", ";
      End-If;
      &Sql = &Sql | &ClobFields;
      &IsFirst = False;
   End-If;

   REM 追加BLOB字段;
   If &BlobFields <> "" Then
      If Not &IsFirst Then
         &Sql = &Sql | ", ";
      End-If;
      &Sql = &Sql | &BlobFields;
      &IsFirst = False;
   End-If;

   If &ColumnCount = 0 Then
      &_ErrText = &_ErrText | " No fields found for record ";
      Return;
   End-If;

   &Sql = &Sql | ")";

   REM 添加表空间;
   REM 添加表空间和存储参数;
   &SpaceName = "";
   SQLExec("SELECT DDLSPACENAME FROM PSRECTBLSPC WHERE RECNAME = :1 AND ROWNUM = 1", &RecName, &SpaceName);
   If &SpaceName = "" Then
      &_ErrText = &_ErrText | " Tablespace is required for record " | &RecName;
      Return;
   End-If;
   &Sql = &Sql | " TABLESPACE " | &SpaceName | " STORAGE (INITIAL 40000 NEXT 100000 MAXEXTENTS UNLIMITED PCTINCREASE 0) PCTFREE 10 PCTUSED 80";

   &TableExists = 0;
   SQLExec("SELECT COUNT(*) FROM USER_TABLES WHERE TABLE_NAME = UPPER(:1)", &SqlTableName, &TableExists);
   If &TableExists > 0 Then
      try
         SQLExec("DROP TABLE " | &SqlTableName);
      catch Exception &exDrop
         &_ErrText = &_ErrText | " DROP TABLE failed: " | &exDrop.ToString();
         Return;
      end-try;
   End-If;

   try
      SQLExec(&Sql);
   catch Exception &ex
      &_ErrText = &_ErrText | " CREATE TABLE failed: " | &ex.ToString();
      Return;
   end-try;

   REM 第4步：创建索引;
   &RsIndex = CreateRowset(Record.PSINDEXDEFN);
   &RsIndex.Fill("WHERE RECNAME = :1 ORDER BY INDEXID", &RecName);

   For &i = 1 To &RsIndex.RowCount
      &IdxId = &RsIndex.GetRow(&i).PSINDEXDEFN.INDEXID.Value;
      &UniqueFlag = &RsIndex.GetRow(&i).PSINDEXDEFN.UNIQUEFLAG.Value;

      If &IdxId = "_" Then
         &IdxName = "PS_" | &RecName;
      Else
         &IdxName = "PS" | &IdxId | &RecName;
      End-If;

      &RsKey = CreateRowset(Record.PSKEYDEFN);
      &RsKey.Fill("WHERE RECNAME = :1 AND INDEXID = :2 ORDER BY KEYPOSN", &RecName, &IdxId);

      &IdxFieldList = "";
      For &j = 1 To &RsKey.RowCount
         If &j > 1 Then
            &IdxFieldList = &IdxFieldList | ", ";
         End-If;
         &IdxFieldList = &IdxFieldList | &RsKey.GetRow(&j).PSKEYDEFN.FIELDNAME.Value;
         If &RsKey.GetRow(&j).PSKEYDEFN.ASCDESC.Value = 0 Then
            &IdxFieldList = &IdxFieldList | " DESC";
         End-If;
      End-For;

      If &IdxFieldList = "" Then
         Continue;
      End-If;

      If &UniqueFlag = 1 Then
         &SqlIndex = "CREATE UNIQUE  iNDEX " | &IdxName | " ON " | &SqlTableName | " (" | &IdxFieldList | ") TABLESPACE PSINDEX STORAGE (INITIAL 40000 NEXT 100000 MAXEXTENTS UNLIMITED PCTINCREASE 0) PCTFREE 10 PARALLEL NOLOGGING";
      Else
         &SqlIndex = "CREATE INDEX " | &IdxName | " ON " | &SqlTableName | " (" | &IdxFieldList | ") TABLESPACE PSINDEX STORAGE (INITIAL 40000 NEXT 100000 MAXEXTENTS UNLIMITED PCTINCREASE 0) PCTFREE 10 PARALLEL NOLOGGING";
      End-If;

      try
         SQLExec(&SqlIndex);
      catch Exception &ex2
         &_ErrText = &_ErrText | " INDEX " | &IdxName | ": " | &ex2.ToString() | "; ";
      end-try;

      REM 修改索引为NOPARALLEL LOGGING;
      try
         SQLExec("ALTER INDEX " | &IdxName | " NOPARALLEL LOGGING");
      catch Exception &ex3
      end-try;
   End-For;
end-method;

method GetFieldOracleType
   /+ &p_FieldName as String +/
   /+ Returns String +/
   Local integer &FieldType, &FieldLen, &DecimalPos;

   SQLExec("SELECT FIELDTYPE, LENGTH, DECIMALPOS FROM PSDBFIELD WHERE FIELDNAME = :1", &p_FieldName, &FieldType, &FieldLen, &DecimalPos);

   Evaluate &FieldType
   When 0 /* 字符 */
      Return "VARCHAR2(" | &FieldLen | ") NOT NULL";
      Break;
   When 1 /* 长字符 */
      Return "CLOB";
      Break;
   When 2 /* number */
      If &DecimalPos > 0 Then
         Return "DECIMAL(" | (&FieldLen - &DecimalPos) | ", " | &DecimalPos | ") NOT NULL";
      Else
         If &FieldLen <= 0 Then
            Return "NUMBER NOT NULL";
         Else
            If &FieldLen <= 4 Then
               Return "SMALLINT NOT NULL";
            Else
               If &FieldLen <= 9 Then
                  Return "INTEGER NOT NULL";
               Else
                  If &FieldLen <= 18 Then
                     Return "NUMBER(" | &FieldLen | ") NOT NULL";
                  Else
                     Return "NUMBER NOT NULL";
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;
      Break;
   When 3 /* 有符号数字 */
      If &DecimalPos > 0 Then
         Return "DECIMAL(" | (&FieldLen - &DecimalPos) | ", " | &DecimalPos | ") NOT NULL";
      Else
         If &FieldLen <= 0 Then
            Return "NUMBER NOT NULL";
         Else
            If &FieldLen <= 4 Then
               Return "SMALLINT NOT NULL";
            Else
               If &FieldLen <= 9 Then
                  Return "INTEGER NOT NULL";
               Else
                  If &FieldLen <= 18 Then
                     Return "NUMBER(" | &FieldLen | ") NOT NULL";
                  Else
                     Return "NUMBER NOT NULL";
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;
      Break;
   When 4 /* 日期 */
      Return "DATE";
      Break;
   When 5 /* 时间 */
      Return "TIMESTAMP";
      Break;
   When 6 /* 日期时间 */
      Return "tIMESTAMP";
      Break;
   When 8 /* 图像/附件 */
      Return "BLOB";
      Break;
   When 9 /* 图像引用 */
      Return "VARCHAR2(" | &FieldLen | ") NOT NULL";
      Break;
   When-Other
      Return "";
   End-Evaluate;
end-method;


method AlterRecordCli
   /+ &p_RecName as String +/
   Local string &RecName, &SqlTableName, &TempTableName, &Sql, &CommonCols;
   Local string &FieldName, &OracleType, &SubRecord, &SubFieldName, &SpaceName;
   Local string &SqlIndex, &IdxFieldList, &IdxId, &IdxName, &ColName;
   Local integer &i, &j, &UniqueFlag, &n, &exists, &SourceRows, &CopiedRows;
   Local Rowset &RsFields, &RsSubFields, &RsDefFields, &RsIndex, &RsKey;
   Local boolean &IsFirst;

   &_ErrText = "";
   &RecName = &p_RecName;

   &SqlTableName = "";
   SQLExec("SELECT NVL(SQLTABLENAME, '') FROM PSRECDEFN WHERE RECNAME = :1", &RecName, &SqlTableName);
   If &SqlTableName = "" Then
      &SqlTableName = "PS_" | &RecName;
   End-If;

   &TempTableName = "PS_TMP" | &RecName | "_A";

   REM 删除临时表（如存在）;
   try
      SQLExec("DROP TABLE " | &TempTableName | " PURGE");
   catch Exception &ex0
   end-try;

   REM 第1步：用新结构创建临时表;
   &Sql = "CREATE TABLE " | &TempTableName | " (";
   &IsFirst = True;

   &RsFields = CreateRowset(Record.PSRECFIELD);
   &RsFields.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &RecName);

   For &i = 1 To &RsFields.RowCount
      &FieldName = &RsFields.GetRow(&i).PSRECFIELD.FIELDNAME.Value;
      &SubRecord = &RsFields.GetRow(&i).PSRECFIELD.SUBRECORD.Value;

      If &SubRecord = "Y" Then
         &RsSubFields = CreateRowset(Record.PSRECFIELD);
         &RsSubFields.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &FieldName);
         For &j = 1 To &RsSubFields.RowCount
            &SubFieldName = &RsSubFields.GetRow(&j).PSRECFIELD.FIELDNAME.Value;
            &OracleType = %This.GetFieldOracleType(&SubFieldName);
            If &OracleType = "" Then
               Continue;
            End-If;
            If Not &IsFirst Then
               &Sql = &Sql | ", ";
            End-If;
            &Sql = &Sql | &SubFieldName | " " | &OracleType;
            &IsFirst = False;
         End-For;
      Else
         &OracleType = %This.GetFieldOracleType(&FieldName);
         If &OracleType = "" Then
            Continue;
         End-If;
         If Not &IsFirst Then
            &Sql = &Sql | ", ";
         End-If;
         &Sql = &Sql | &FieldName | " " | &OracleType;
         &IsFirst = False;
      End-If;
   End-For;

   &Sql = &Sql | ")";

   REM 添加表空间和存储参数;
   &SpaceName = "";
   SQLExec("SELECT DDLSPACENAME FROM PSRECTBLSPC WHERE RECNAME = :1 AND ROWNUM = 1", &RecName, &SpaceName);
   If &SpaceName <> "" Then
      &Sql = &Sql | " TABLESPACE " | &SpaceName | " STORAGE (INITIAL 40000 NEXT 100000 MAXEXTENTS UNLIMITED PCTINCREASE 0) PCTFREE 10 PCTUSED 80";
   End-If;

   try
      SQLExec(&Sql);
   catch Exception &ex
      &_ErrText = &_ErrText | " CREATE TEMP TABLE failed: " | &ex.ToString();
      Return;
   end-try;

   REM 第2步：查找公共列并复制数据;
   &CommonCols = "";
   &n = 0;

   &RsDefFields = CreateRowset(Record.PSRECFIELDDB);
   &RsDefFields.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &RecName);

   For &i = 1 To &RsDefFields.RowCount
      &FieldName = &RsDefFields.GetRow(&i).PSRECFIELDDB.FIELDNAME.Value;

      &exists = 0;
      SQLExec("SELECT COUNT(*) FROM ALL_TAB_COLUMNS WHERE OWNER = 'SYSADM' AND TABLE_NAME = :1 AND COLUMN_NAME = :2", &SqlTableName, &FieldName, &exists);

      If &exists > 0 Then
         If &n > 0 Then
            &CommonCols = &CommonCols | ", ";
         End-If;
         &CommonCols = &CommonCols | &FieldName;
         &n = &n + 1;
      End-If;
   End-For;

   If &CommonCols <> "" Then
      try
         SQLExec("INSERT INTO " | &TempTableName | " (" | &CommonCols | ") SELECT " | &CommonCols | " FROM " | &SqlTableName);
      catch Exception &ex2
         &_ErrText = "Copy data failed; original table preserved: " | &ex2.ToString();
         Return;
      end-try;
   End-If;

   SQLExec("SELECT COUNT(*) FROM " | &SqlTableName, &SourceRows);
   SQLExec("SELECT COUNT(*) FROM " | &TempTableName, &CopiedRows);
   If &SourceRows <> &CopiedRows Then
      &_ErrText = "Copy row count mismatch; original table preserved";
      Return;
   End-If;

   REM 第3步：删除旧表;
   try
      SQLExec("DROP TABLE " | &SqlTableName | " PURGE");
   catch Exception &ex3
      &_ErrText = "DROP original table failed: " | &ex3.ToString();
      Return;
   end-try;

   REM 第4步：重命名临时表为目标表;
   try
      SQLExec("ALTER TABLE " | &TempTableName | " RENAME TO " | &SqlTableName);
   catch Exception &ex4
      &_ErrText = &_ErrText | " RENAME failed: " | &ex4.ToString();
      Return;
   end-try;

   REM 第5步：重建索引;
   &RsIndex = CreateRowset(Record.PSINDEXDEFN);
   &RsIndex.Fill("WHERE RECNAME = :1 ORDER BY INDEXID", &RecName);

   For &i = 1 To &RsIndex.RowCount
      &IdxId = &RsIndex.GetRow(&i).PSINDEXDEFN.INDEXID.Value;
      &UniqueFlag = &RsIndex.GetRow(&i).PSINDEXDEFN.UNIQUEFLAG.Value;

      If &IdxId = "_" Then
         &IdxName = "PS_" | &RecName;
      Else
         &IdxName = "PS" | &IdxId | &RecName;
      End-If;

      &RsKey = CreateRowset(Record.PSKEYDEFN);
      &RsKey.Fill("WHERE RECNAME = :1 AND INDEXID = :2 ORDER BY KEYPOSN", &RecName, &IdxId);

      &IdxFieldList = "";
      For &j = 1 To &RsKey.RowCount
         If &j > 1 Then
            &IdxFieldList = &IdxFieldList | ", ";
         End-If;
         &IdxFieldList = &IdxFieldList | &RsKey.GetRow(&j).PSKEYDEFN.FIELDNAME.Value;
         If &RsKey.GetRow(&j).PSKEYDEFN.ASCDESC.Value = 0 Then
            &IdxFieldList = &IdxFieldList | " DESC";
         End-If;
      End-For;

      If &IdxFieldList = "" Then
         Continue;
      End-If;

      If &UniqueFlag = 1 Then
         &SqlIndex = "CREATE UNIQUE INDEX " | &IdxName | " ON " | &SqlTableName | " (" | &IdxFieldList | ") TABLESPACE PSINDEX STORAGE (INITIAL 40000 NEXT 100000 MAXEXTENTS UNLIMITED PCTINCREASE 0) PCTFREE 10 PARALLEL NOLOGGING";
      Else
         &SqlIndex = "CREATE INDEX " | &IdxName | " ON " | &SqlTableName | " (" | &IdxFieldList | ") TABLESPACE PSINDEX STORAGE (INITIAL 40000 NEXT 100000 MAXEXTENTS UNLIMITED PCTINCREASE 0) PCTFREE 10 PARALLEL NOLOGGING";
      End-If;

      try
         SQLExec(&SqlIndex);
      catch Exception &ex5
         &_ErrText = &_ErrText | " INDEX " | &IdxName | ": " | &ex5.ToString() | "; ";
      end-try;
   End-For;
end-method;

method CreateViewCli
   /+ &p_RecName as String +/
   Local string &RecName, &ViewName, &ViewSql, &FieldName, &SubRecord, &SubFieldName;
   Local string &SqlText, &ViewBody;
   Local integer &i, &j;
   Local Rowset &RsFields, &RsSubFields, &RsSqlText;
   Local boolean &IsFirst;

   &_ErrText = "";
   &RecName = &p_RecName;

   REM 第1步：确定视图名;
   &ViewName = "";
   SQLExec("SELECT NVL(SQLTABLENAME, '') FROM PSRECDEFN WHERE RECNAME = :1", &RecName, &ViewName);
   If &ViewName = "" Then
      &ViewName = "PS_" | &RecName;
   End-If;

   REM 第2步：从PSSQLTEXTDEFN获取视图SQL体;
   &SqlText = "";
   SQLExec("SELECT SQLTEXT FROM PSSQLTEXTDEFN WHERE SQLID = :1 AND MARKET = 'GBL' AND DBTYPE = ' ' AND EFFDT = (SELECT MAX(EFFDT) FROM PSSQLTEXTDEFN WHERE SQLID = :1 AND MARKET = 'GBL' AND DBTYPE = ' ')", &RecName, &SqlText);

   If &SqlText = "" Then
      &_ErrText = &_ErrText | " No SQL text found for view " | &RecName | "; ";
      Return;
   End-If;

   REM 第3步：从PSRECFIELD构建列清单;
   &ViewSql = "CREATE VIEW " | &ViewName | " (";
   &IsFirst = True;

   &RsFields = CreateRowset(Record.PSRECFIELD);
   &RsFields.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &RecName);

   For &i = 1 To &RsFields.RowCount
      &FieldName = &RsFields.GetRow(&i).PSRECFIELD.FIELDNAME.Value;
      &SubRecord = &RsFields.GetRow(&i).PSRECFIELD.SUBRECORD.Value;

      If &SubRecord = "Y" Then
         &RsSubFields = CreateRowset(Record.PSRECFIELD);
         &RsSubFields.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &FieldName);
         For &j = 1 To &RsSubFields.RowCount
            &SubFieldName = &RsSubFields.GetRow(&j).PSRECFIELD.FIELDNAME.Value;
            If Not &IsFirst Then
               &ViewSql = &ViewSql | ", ";
            End-If;
            &ViewSql = &ViewSql | &SubFieldName;
            &IsFirst = False;
         End-For;
      Else
         If Not &IsFirst Then
            &ViewSql = &ViewSql | ", ";
         End-If;
         &ViewSql = &ViewSql | &FieldName;
         &IsFirst = False;
      End-If;
   End-For;

   &ViewSql = &ViewSql | ") AS " | &SqlText;

   REM 第4步：执行;
   try
      SQLExec(&ViewSql);
   catch Exception &ex
      &_ErrText = &_ErrText | " CREATE VIEW failed: " | &ex.ToString();
      Return;
   end-try;
end-method;

method ModifyRecordCli
   /+ &p_obj as JsonObject +/
   Local integer &i, &Exists, &MaxFieldNum, &FieldCount, &ci, &RDMVersion, &InsertFieldNum, &AnchorCount;
   Local number &UseEdit, &UseEdit2;
   Local string &SafeRec, &ch;
   Local integer &EffDpc, &XlatCnt, &FldType, &FldCnt;
   Local JsonArray &Fields, &JFieldProperty;
   Local JsonObject &JRecField;
   Local string &FieldName, &RecName, &Descr, &DescrLong, &Oprid, &SqlStmt;
   Local string &Err, &FieldTypeName, &EffEditTable, &EffLblId, &EffLblIdForDb, &DpcVal, &DbSubRec, &EffDefRecName, &EffDefFieldName;
   Local string &CurEditTable, &CurLblId, &CurDefRec, &CurDefFld;
   Local integer &CurDpc, &ImgFmt;
   Local Rowset &FieldsRs, &DbRs;
   Local boolean &HasEditTable, &HasLblId, &HasDpc, &HasDefRec, &HasDefFld, &HasXlat, &IsSubRec;
   Local datetime &Now;
   Local array of any &ArrExists, &ArrUseEdit, &ArrUseEdit2, &ArrDpc;
   Local array of any &ArrEditTable, &ArrLblIdForDb, &ArrDefRec, &ArrDefFld;
   Local array of any &ArrSkip;
   Local array of string &ArrInsertBefore, &SeenFields;
   Local string &BeforeField;

   &_ErrText = "";
   &RecName = &p_obj.GetString("recordName");
   &Fields = &p_obj.GetJsonArray("fields");
   &Oprid = %UserId;
   &Now = %Datetime;
   &ArrExists = CreateArray();
   &ArrUseEdit = CreateArray();
   &ArrUseEdit2 = CreateArray();
   &ArrDpc = CreateArray();
   &ArrEditTable = CreateArray();
   &ArrLblIdForDb = CreateArray();
   &ArrDefRec = CreateArray();
   &ArrDefFld = CreateArray();
   &ArrSkip = CreateArray();
   &ArrInsertBefore = CreateArrayRept("", 0);
   &SeenFields = CreateArrayRept("", 0);

   If &p_obj.IsExist("descr") Then
      &Descr = &p_obj.GetString("descr");
      SQLExec("UPDATE PSRECDEFN SET RECDESCR = :1 WHERE RECNAME = :2", &Descr, &RecName);
   End-If;
   If &p_obj.IsExist("comment") Then
      &DescrLong = &CommUtil.UnEscapeJSON(&p_obj.GetString("comment"));
      SQLExec("UPDATE PSRECDEFN SET DESCRLONG = :1 WHERE RECNAME = :2", &DescrLong, &RecName);
   End-If;

   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &RDM, &RDMVersion);
   SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &RDM);
   &RDMVersion = &RDMVersion + 1;

   &MaxFieldNum = 0;
   SQLExec("SELECT NVL(MAX(FIELDNUM), 0) FROM PSRECFIELD WHERE RECNAME = :1", &RecName, &MaxFieldNum);

   REM ===== 第1步：全量校验。先计算每个字段最终的USEEDIT/USEEDIT2和有效属性值，全部通过后才进入第2步写库 =====;
   For &i = 1 To &Fields.Size
      &JRecField = &Fields.GetJsonObject(&i);
      &FieldName = &JRecField.GetString("fieldName");
      If &SeenFields.Find(&FieldName) > 0 Then
         &_ErrText = &_ErrText | &FieldName | ": duplicate field in request, ";
      End-If;
      &SeenFields.Push(&FieldName);
      &JFieldProperty = CreateJsonArray();
      If &JRecField.IsExist("fieldProperty") Then
         &JFieldProperty = &JRecField.GetJsonArray("fieldProperty");
      End-If;

      &Exists = 0;
      SQLExec("SELECT COUNT(*) FROM PSRECFIELD WHERE RECNAME = :1 AND FIELDNAME = :2", &RecName, &FieldName, &Exists);

      &BeforeField = "";
      If &JRecField.IsExist("insertBefore") Then
         &BeforeField = LTrim(RTrim(&JRecField.GetString("insertBefore")));
         If &Exists > 0 Then
            &_ErrText = &_ErrText | &FieldName | ": insertBefore is only allowed for a new field, ";
         End-If;
         If &BeforeField = "" Then
            &_ErrText = &_ErrText | &FieldName | ": insertBefore must name an existing field, ";
         Else
            &AnchorCount = 0;
            SQLExec("SELECT COUNT(*) FROM PSRECFIELD WHERE RECNAME = :1 AND FIELDNAME = :2", &RecName, &BeforeField, &AnchorCount);
            If &AnchorCount <> 1 Then
               &_ErrText = &_ErrText | &FieldName | ": insertBefore field not found in record: " | &BeforeField | ", ";
            End-If;
         End-If;
      End-If;
      &ArrInsertBefore.Push(&BeforeField);

      &HasEditTable = &JRecField.IsExist("editTable");
      &HasLblId = &JRecField.IsExist("labelId");
      &HasDpc = &JRecField.IsExist("defaultPageControl");
      &HasDefRec = &JRecField.IsExist("defaultRecName");
      &HasDefFld = &JRecField.IsExist("defaultFieldName");

      REM 有效值 = 请求提供的值，否则取DB现值（保持GUI语义：未改动的属性保持原样）;
      &EffEditTable = "";
      &EffLblId = "";
      &EffLblIdForDb = " ";
      &EffDpc = 99;
      &EffDefRecName = "";
      &EffDefFieldName = "";
      &DbSubRec = "N";
      &IsSubRec = False;

      If &Exists > 0 Then
         SQLExec("SELECT EDITTABLE, DEFGUICONTROL, LABEL_ID, DEFRECNAME, DEFFIELDNAME, SUBRECORD FROM PSRECFIELD WHERE RECNAME = :1 AND FIELDNAME = :2", &RecName, &FieldName, &CurEditTable, &CurDpc, &CurLblId, &CurDefRec, &CurDefFld, &DbSubRec);
         If Not &HasEditTable Then
            &EffEditTable = RTrim(&CurEditTable);
         End-If;
         If Not &HasDpc Then
            &EffDpc = &CurDpc;
         End-If;
         If Not &HasLblId Then
            &EffLblId = RTrim(&CurLblId);
         End-If;
         If Not &HasDefRec Then
            &EffDefRecName = RTrim(&CurDefRec);
         End-If;
         If Not &HasDefFld Then
            &EffDefFieldName = RTrim(&CurDefFld);
         End-If;
         &IsSubRec = (&DbSubRec = "Y");
      End-If;
      If Not &IsSubRec Then
         If &JRecField.IsExist("subRecord") Then
            &IsSubRec = (&JRecField.GetString("subRecord") = "Y");
         End-If;
      End-If;
      If &IsSubRec And
            &JFieldProperty.Size > 0 Then
         &_ErrText = &_ErrText | &FieldName | ": subrecord reference fields cannot have field properties (AD does not allow editing them), ";
      End-If;
      If &HasEditTable Then
         &EffEditTable = &JRecField.GetString("editTable");
      End-If;
      If &HasLblId Then
         &EffLblId = &JRecField.GetString("labelId");
      End-If;
      If &HasDpc Then
         &DpcVal = &JRecField.GetString("defaultPageControl");
         &EffDpc = %This.MapDefGuiControl(&DpcVal);
         If &EffDpc = - 1 Then
            &_ErrText = &_ErrText | &FieldName | ": unknown defaultPageControl value '" | &DpcVal | "' (use System Default, Edit Box or a numeric code), ";
         End-If;
      End-If;
      If &HasDefRec Then
         &EffDefRecName = &JRecField.GetString("defaultRecName");
      End-If;
      If &HasDefFld Then
         &EffDefFieldName = &JRecField.GetString("defaultFieldName");
      End-If;
      If &EffLblId <> "" Then
         &EffLblIdForDb = &EffLblId;
      End-If;

      &UseEdit = 0;
      &UseEdit2 = 0;
      If Not &IsSubRec Then
         REM 有效labelId注入，保证默认Label位（8388608）的判断与DB现状一致;
         If &EffLblId <> "" Then
            &JRecField.AddProperty("labelId", &EffLblId);
         End-If;
         &UseEdit = &RecordUseEdit.GetUseEditByFieldProperty(&JRecField);
         &UseEdit2 = &RecordUseEdit.GetUseEdit2ByFieldProperty(&JFieldProperty);

         &FldCnt = 0;
         SQLExec("SELECT COUNT(*) FROM PSDBFIELD WHERE FIELDNAME = :1", &FieldName, &FldCnt);
         If &FldCnt = 0 Then
            &_ErrText = &_ErrText | &FieldName | ": field does not exist in PSDBFIELD, ";
         Else
            &FldType = 0;
            &ImgFmt = 0;
            SQLExec("SELECT FIELDTYPE, IMAGE_FMT FROM PSDBFIELD WHERE FIELDNAME = :1", &FieldName, &FldType, &ImgFmt);
            &FieldTypeName = &MappingUtil.GetFieldTypeName(&FldType, &ImgFmt);
            &XlatCnt = 0;
            SQLExec("SELECT COUNT(*) FROM PSXLATDEFN WHERE FIELDNAME = :1", &FieldName, &XlatCnt);
            &HasXlat = (&XlatCnt > 0);
            &Err = &RecordUseEdit.ValidateFieldProperty(&JFieldProperty, &FieldTypeName, &EffEditTable, &EffDpc, &HasXlat, &IsSubRec);
            If &Err <> "" Then
               &_ErrText = &_ErrText | &FieldName | ": " | &Err;
            End-If;
         End-If;
      End-If;

      &ArrExists.Push(&Exists);
      &ArrUseEdit.Push(&UseEdit);
      &ArrUseEdit2.Push(&UseEdit2);
      &ArrDpc.Push(&EffDpc);
      &ArrEditTable.Push(&EffEditTable);
      &ArrLblIdForDb.Push(&EffLblIdForDb);
      &ArrDefRec.Push(&EffDefRecName);
      &ArrDefFld.Push(&EffDefFieldName);
      If &IsSubRec And
            &BeforeField <> "" Then
         &_ErrText = &_ErrText | &FieldName | ": insertBefore does not support a subrecord reference, ";
      End-If;
      &ArrSkip.Push(&IsSubRec);
   End-For;

   If &_ErrText <> "" Then
      REM 校验失败：不写任何字段（OnRequest统一rollback并返回400）;
      Return;
   End-If;

   REM ===== 第2步：写库 =====;
   For &i = 1 To &Fields.Size
      If &ArrSkip [&i] Then
         Continue;
      End-If;
      &JRecField = &Fields.GetJsonObject(&i);
      &FieldName = &JRecField.GetString("fieldName");
      &UseEdit = &ArrUseEdit [&i];
      &UseEdit2 = &ArrUseEdit2 [&i];
      &Exists = &ArrExists [&i];

      If &Exists > 0 Then
         SQLExec("UPDATE PSRECFIELD SET USEEDIT = :1, USEEDIT2 = :2, EDITTABLE = :3, DEFGUICONTROL = :4, LABEL_ID = :5, DEFRECNAME = :6, DEFFIELDNAME = :7, LASTUPDOPRID = :8, LASTUPDDTTM = :9 WHERE RECNAME = :10 AND FIELDNAME = :11", &UseEdit, &UseEdit2, &ArrEditTable [&i], &ArrDpc [&i], &ArrLblIdForDb [&i], &ArrDefRec [&i], &ArrDefFld [&i], &Oprid, &Now, &RecName, &FieldName);
      Else
         &MaxFieldNum = &MaxFieldNum + 1;
         &InsertFieldNum = &MaxFieldNum;
         &BeforeField = &ArrInsertBefore [&i];
         If &BeforeField <> "" Then
            &InsertFieldNum = 0;
            SQLExec("SELECT FIELDNUM FROM PSRECFIELD WHERE RECNAME = :1 AND FIELDNAME = :2", &RecName, &BeforeField, &InsertFieldNum);
            If &InsertFieldNum <= 0 Then
               &_ErrText = "Insertion anchor disappeared: " | &BeforeField;
               Return;
            End-If;
            SQLExec("UPDATE PSRECFIELD SET FIELDNUM = FIELDNUM + 1 WHERE RECNAME = :1 AND FIELDNUM >= :2", &RecName, &InsertFieldNum);
         End-If;
         &SqlStmt = "INSERT INTO PSRECFIELD (RECNAME, FIELDNAME, FIELDNUM, USEEDIT, USEEDIT2, DEFRECNAME, DEFFIELDNAME, CURCTLFIELDNAME, EDITTABLE, SUBRECORD, SUBRECVER, SETCNTRLFLD, DEFGUICONTROL, LABEL_ID, LASTUPDOPRID, TIMEZONEUSE, TIMEZONEFIELDNAME, RELTMDTFIELDNAME, CURRCTLUSE) VALUES (:1, :2, :3, :4, :5, :6, :7, ' ', :8, 'N', 0, ' ', :9, :10, :11, 0, ' ', ' ', 0)";
         SQLExec(&SqlStmt, &RecName, &FieldName, &InsertFieldNum, &UseEdit, &UseEdit2, &ArrDefRec [&i], &ArrDefFld [&i], &ArrEditTable [&i], &ArrDpc [&i], &ArrLblIdForDb [&i], &Oprid);
      End-If;
   End-For;

   SQLExec("DELETE FROM PSRECFIELDDB WHERE RECNAME = :1", &RecName);
   &FieldsRs = CreateRowset(Record.PSRECFIELD);
   &FieldsRs.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &RecName);
   &DbRs = %This.BuildPSRECFIELDDBs(&FieldsRs);
   For &i = 1 To &DbRs.ActiveRowCount
      If Not &DbRs(&i).GetRecord(1).Insert() Then
         &_ErrText = "Failed to rebuild PSRECFIELDDB";
         Return;
      End-If;
   End-For;
   %This.SyncPrimaryIndex(&RecName);
   If &_ErrText <> "" Then
      Return;
   End-If;

   /* Keep the Record header field count synchronized after updates/additions. */
   &FieldCount = 0;
   SQLExec("SELECT COUNT(*) FROM PSRECFIELD WHERE RECNAME = :1", &RecName, &FieldCount);
   SQLExec("UPDATE PSRECDEFN SET VERSION = VERSION + 1, FIELDCOUNT = :1, LASTUPDOPRID = :2, LASTUPDDTTM = :3 WHERE RECNAME = :4", &FieldCount, &Oprid, &Now, &RecName);
   SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS);
   SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &RDM, &RDMVersion);
end-method;


method ViewPeopleCodeCli
   /+ &p_obj as JsonObject +/
   /+ Returns JsonObject +/
   Local string &RecName, &FieldName, &Event;
   Local JsonObject &RespObj;
   Local %metadata:Key &Key;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;

   &RecName = &p_obj.GetString("recordName");
   &FieldName = &p_obj.GetString("fieldName");
   &Event = &p_obj.GetString("event");

   &RespObj = CreateJsonObject();
   &RespObj.AddProperty("recordName", &RecName);
   &RespObj.AddProperty("fieldName", &FieldName);
   &RespObj.AddProperty("event", &Event);

   &mgrPeopleCodeProgram = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   &Key = create %metadata:Key(Key:Class_Record, &RecName);
   &Key.AddItem(Key:Class_Field, &FieldName);
   &Key.AddItem(Key:Class_Method, &Event);

   &RespObj.AddProperty("programExists", &mgrPeopleCodeProgram.DefnExists(&Key));
   If &mgrPeopleCodeProgram.DefnExists(&Key) Then
      Local %metadata:PeopleCodeProgram:PeopleCodeProgram &oPeopleCodeProgram;
      &oPeopleCodeProgram = &mgrPeopleCodeProgram.GetDefn(&Key);
      &RespObj.AddProperty("peoplecode", &CommUtil.EscapeJSON(&oPeopleCodeProgram.GetProgram()));
      &RespObj.AddProperty("lastUpdate", "Last updated by: " | &oPeopleCodeProgram.LastUpdOprId | ", " | DateTimeToLocalizedString(&oPeopleCodeProgram.LastUpdDttm, &DateTimeFormat));
   Else
      &RespObj.AddProperty("peoplecode", "");
      &RespObj.AddProperty("lastUpdate", "");


   End-If;

   Return &RespObj;
end-method;

method ModifyPeopleCodeCli
   /+ &p_obj as JsonObject +/
   Local string &RecName, &FieldName, &Event, &PeopleCode, &ErrorMsg;
   Local boolean &CompileResult;
   Local integer &Position1, &Position2;
   Local %metadata:Key &Key;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &Prog = Null;

   &RecName = &p_obj.GetString("recordName");
   &FieldName = &p_obj.GetString("fieldName");
   &Event = &p_obj.GetString("event");
   &PeopleCode = &CommUtil.UnEscapeJSON(&p_obj.GetString("peoplecode"));
   Local string &NonBlankCode = &PeopleCode;
   &NonBlankCode = Substitute(&NonBlankCode, Char(9), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(10), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(11), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(12), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(13), "");
   If Len(LTrim(RTrim(&NonBlankCode))) = 0 Then
      throw CreateException(0, 0, "Empty PeopleCode is not deletion; use deletePeopleCode");
   End-If;

   &mgrPeopleCodeProgram = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   &Key = create %metadata:Key(Key:Class_Record, &RecName);
   &Key.AddItem(Key:Class_Field, &FieldName);
   &Key.AddItem(Key:Class_Method, &Event);

   If &mgrPeopleCodeProgram.DefnExists(&Key) Then
      &Prog = &mgrPeopleCodeProgram.GetDefnToUpdate(&Key);
      &CompileResult = &Prog.UpdateProgram(&PeopleCode, &ErrorMsg, &Position1, &Position2);
      If &CompileResult Then
         If Not &Prog.UpdateDefn() Then
            &_ErrText = &_ErrText | "Error saving PeopleCode.";
         End-If;
      Else
         &_ErrText = &_ErrText | MsgGetText(158, 20153, "PeopleCode Error") | " - " | &ErrorMsg | " " | &Position1 | " " | &Position2;
      End-If;
   Else
      &Prog = &mgrPeopleCodeProgram.CreateDefn();
      &Prog.ObjectID#0# = Key:Class_Record;
      &Prog.ObjectValue#0# = &RecName;
      &Prog.ObjectID#1# = Key:Class_Field;
      &Prog.ObjectValue#1# = &FieldName;
      &Prog.ObjectID#2# = Key:Class_Method;
      &Prog.ObjectValue#2# = &Event;
      &CompileResult = &Prog.UpdateProgram(&PeopleCode, &ErrorMsg, &Position1, &Position2);
      If &CompileResult Then
         If Not &Prog.SaveNewDefn() Then
            &_ErrText = &_ErrText | "Error saving new PeopleCode.";
         End-If;
      Else
         &_ErrText = &_ErrText | MsgGetText(158, 20153, "PeopleCode Error") | " - " | &ErrorMsg | " " | &Position1 | " " | &Position2;
      End-If;
   End-If;
end-method;


method ViewSqlCli
   /+ &p_obj as JsonObject +/
   /+ Returns JsonObject +/
   Local JsonObject &RespObject, &SQLStatement;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgr;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &defn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &stmtdefn;
   Local %metadata:Key &Key;
   Local integer &i;
   Local JsonArray &Statements;

   &RespObject = CreateJsonObject();
   &RespObject.AddProperty("recordName", &_RecName);
   &Statements = CreateJsonArray();

   &mgr = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &Key = create %metadata:Key(Key:Class_Sql, &_RecName, Key:Class_SqlType, &ViewSqlType);

   If Not &mgr.DefnExists(&Key) Then
      &RespObject.AddProperty("exists", "false");
      &RespObject.AddJsonArray("statements", &Statements);
      Return &RespObject;
   End-If;

   &defn = &mgr.GetDefn(&Key);
   &RespObject.AddProperty("exists", "true");
   &RespObject.AddProperty("sqlType", &defn.SqlType);
   &RespObject.AddProperty("lastUpdate", "Last updated by: " | &defn.LastUpdOprId | ", " | DateTimeToLocalizedString(&defn.LastUpdDttm, &DateTimeFormat));

   For &i = 1 To &defn.Count_StmtT
      &stmtdefn = &defn.Get_StmtT(&i);
      &SQLStatement = CreateJsonObject();
      &SQLStatement.AddProperty("market", &stmtdefn.Market);
      &SQLStatement.AddProperty("dbType", &stmtdefn.DbType);
      &SQLStatement.AddProperty("effdt", &stmtdefn.EffDt);
      &SQLStatement.AddProperty("sqlText", &CommUtil.EscapeJSON(&stmtdefn.SqlText));
      &SQLStatement.AddProperty("descr", &stmtdefn.Descr);
      &SQLStatement.AddProperty("comment", &CommUtil.EscapeJSON(&stmtdefn.DescrLong));
      &Statements.AddJsonObjectElement("", &SQLStatement);
   End-For;
   &RespObject.AddJsonArray("statements", &Statements);

   Return &RespObject;
end-method;

method ModifySqlCli
   /+ &p_obj as JsonObject +/
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgr;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &defn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &stmtdefn;
   Local %metadata:Key &Key;
   Local string &Market, &DbType, &SqlText, &Descr, &DescrLong;
   Local date &Effdt;
   Local integer &i, &DbTypeCode, &MatchCount;

   If &p_obj.IsExist("market") Then
      &Market = &p_obj.GetString("market");
   Else
      &Market = "GBL";
   End-If;
   If &p_obj.IsExist("dbType") Then
      &DbType = &p_obj.GetString("dbType");
   Else
      &DbType = "";
   End-If;
   If &p_obj.IsExist("effdt") Then
      &Effdt = Date(&p_obj.GetString("effdt"));
   Else
      &Effdt = Date3(1900, 1, 1);
   End-If;
   If &p_obj.IsExist("sqlText") Then
      &SqlText = &CommUtil.UnEscapeJSON(&p_obj.GetString("sqlText"));
      &SqlText = &CommUtil.ReplaceWithRegex(&SqlText, "s+", " ");
   Else
      &_ErrText = &_ErrText | "sqlText is required, ";
      Return;
   End-If;
   If &p_obj.IsExist("descr") Then
      &Descr = &p_obj.GetString("descr");
   End-If;
   If &p_obj.IsExist("comment") Then
      &DescrLong = &CommUtil.UnEscapeJSON(&p_obj.GetString("comment"));
   End-If;

   &DbTypeCode = &MappingUtil.GetDbTypeCode(&DbType);

   &mgr = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &Key = create %metadata:Key(Key:Class_Sql, &_RecName, Key:Class_SqlType, &ViewSqlType);

   If &mgr.DefnExists(&Key) Then
      &defn = &mgr.GetDefnToUpdate(&Key);
      &MatchCount = 0;
      For &i = 1 To &defn.Count_StmtT
         &stmtdefn = &defn.Get_StmtT(&i);
         If &stmtdefn.Market = &Market And
               &stmtdefn.DbType = &DbTypeCode And
               &stmtdefn.EffDt = &Effdt Then
            &stmtdefn.SqlText = &SqlText;
            If All(&Descr) Then
               &stmtdefn.Descr = &Descr;
            End-If;
            If All(&DescrLong) Then
               &stmtdefn.DescrLong = &DescrLong;
            End-If;
            &MatchCount = &MatchCount + 1;
         End-If;
      End-For;
      If &MatchCount = 0 Then
         &stmtdefn = &defn.Append_StmtT(&defn.Count_StmtT);
         &stmtdefn.Market = &Market;
         &stmtdefn.DbType = &DbTypeCode;
         &stmtdefn.EffDt = &Effdt;
         &stmtdefn.SqlText = &SqlText;
         If All(&Descr) Then
            &stmtdefn.Descr = &Descr;
         End-If;
         If All(&DescrLong) Then
            &stmtdefn.DescrLong = &DescrLong;
         End-If;
      End-If;
      If Not &defn.UpdateDefn() Then
         &_ErrText = &_ErrText | "modify view sql failed";
      End-If;
   Else
      &defn = &mgr.CreateDefn();
      &defn.SqlId = &_RecName;
      &defn.SqlType = &ViewSqlType;
      &stmtdefn = &defn.Append_StmtT(0);
      &stmtdefn.Market = &Market;
      &stmtdefn.DbType = &DbTypeCode;
      &stmtdefn.EffDt = &Effdt;
      &stmtdefn.SqlText = &SqlText;
      If All(&Descr) Then
         &stmtdefn.Descr = &Descr;
      End-If;
      If All(&DescrLong) Then
         &stmtdefn.DescrLong = &DescrLong;
      End-If;
      If Not &defn.SaveNewDefn() Then
         &_ErrText = &_ErrText | "create view sql failed";
      End-If;
   End-If;
end-method;


method GetRecFieldInfo
   /+ &p_rec as String +/
   /+ Returns Rowset +/
   Local Rowset &RsRecFldVw;
   &RsRecFldVw = CreateRowset(Record.C_RECFLDLAB_VW);
   &RsRecFldVw.Flush();
   &RsRecFldVw.Fill(" WHERE RECNAME = :1", &p_rec);
   &RsRecFldVw.Sort(C_RECFLDLAB_VW.FIELDNUM, "A");

   Return &RsRecFldVw;
end-method;

method GetSubRecFields
   /+ &p_subRec as String +/
   /+ Returns JsonArray +/
   Local JsonObject &SubRecFieldObj;
   Local JsonArray &SubRecFieldArr, &SubRecFieldArr2, &RecordPeople;
   Local Rowset &RsSubRecField;
   Local Record &PSRECFIELD, &PSDBFIELD;
   Local integer &i;

   &SubRecFieldArr = CreateJsonArray();
   &RsSubRecField = CreateRowset(Record.PSRECFIELD);
   &RsSubRecField.Flush();
   &RsSubRecField.Fill(" WHERE RECNAME = :1", &p_subRec);
   &RsSubRecField.Sort(PSRECFIELD.FIELDNUM, "A");
   &RecordPeople = %This.GetPeopleCodeEventByRecord(&p_subRec);
   For &i = 1 To &RsSubRecField.ActiveRowCount
      &SubRecFieldObj = CreateJsonObject();
      &PSRECFIELD = &RsSubRecField(&i).GetRecord(1);
      &SubRecFieldObj.AddProperty("fieldName", &PSRECFIELD.FIELDNAME.Value);
      If &PSRECFIELD.SUBRECORD.Value = "N" Then
         &PSDBFIELD = CreateRecord(Record.PSDBFIELD);
         &PSDBFIELD.FIELDNAME.Value = &PSRECFIELD.FIELDNAME.Value;
         If &PSDBFIELD.SelectByKey() Then
            &SubRecFieldObj.AddProperty("fieldType", &MappingUtil.GetFieldTypeName(&PSDBFIELD.FIELDTYPE.Value, &PSDBFIELD.IMAGE_FMT.Value));
            &SubRecFieldObj.AddProperty("length", &PSDBFIELD.LENGTH.Value);
         Else
            &_ErrText = &_ErrText | "Field not exist, " | &PSRECFIELD.FIELDNAME.Value | ", ";
         End-If;
      End-If;
      &SubRecFieldObj.AddProperty("defaultRecName", &PSRECFIELD.DEFRECNAME.Value);
      &SubRecFieldObj.AddProperty("defaultFieldName", &PSRECFIELD.DEFFIELDNAME.Value);
      &SubRecFieldObj.AddProperty("editTable", &PSRECFIELD.EDITTABLE.Value);
      &SubRecFieldObj.AddProperty("subRecord", &PSRECFIELD.SUBRECORD.Value);
      &SubRecFieldObj.AddProperty("setControlField", &PSRECFIELD.SETCNTRLFLD.Value);
      &SubRecFieldObj.AddProperty("labelId", &PSRECFIELD.LABEL_ID.Value);
      &SubRecFieldObj.AddJsonArray("events", %This.GetPeopleCodeEventByField(&PSRECFIELD.FIELDNAME.Value, &RecordPeople));
      &SubRecFieldObj.AddProperty("lastUpdate", "Last updated by: " | &PSRECFIELD.LASTUPDOPRID.Value | ", " | DateTimeToLocalizedString(&PSRECFIELD.LASTUPDDTTM.Value, &DateTimeFormat));
      If &PSRECFIELD.SUBRECORD.Value = "Y" Then
         &SubRecFieldArr2 = %This.GetSubRecFields(&PSRECFIELD.FIELDNAME.Value);
         &SubRecFieldObj.AddJsonArray("subRecFields", &SubRecFieldArr2);
      End-If;
      &SubRecFieldArr.AddJsonObjectElement("", &SubRecFieldObj);
   End-For;

   Return &SubRecFieldArr;
end-method;

method GetSubRecFields2
   /+ &p_subRec as String, +/
   /+ &p_parentRec as String, +/
   /+ &RsFieldDB as Rowset +/
   Local Rowset &RsSubRecField;
   Local Record &PSRECFIELD, &PSRECFIELDDB;
   Local integer &i, &RowIdx;

   &RsSubRecField = CreateRowset(Record.PSRECFIELD);
   &RsSubRecField.Flush();
   &RsSubRecField.Fill(" WHERE RECNAME = :1", &p_subRec);
   &RsSubRecField.Sort(PSRECFIELD.FIELDNUM, "A");
   For &i = 1 To &RsSubRecField.ActiveRowCount
      &PSRECFIELD = &RsSubRecField(&i).GetRecord(1);
      If &RsFieldDB.ActiveRowCount = 1 And
            &RsFieldDB(1).GetRecord(1).FIELDNAME.Value = "" Then
         &PSRECFIELDDB = &RsFieldDB(1).GetRecord(1);
      Else
         &RowIdx = &RsFieldDB.ActiveRowCount + 1;
         &RsFieldDB.InsertRow(&RowIdx - 1);
         &PSRECFIELDDB = &RsFieldDB(&RowIdx).GetRecord(1);
      End-If;
      &PSRECFIELD.CopyFieldsTo(&PSRECFIELDDB);
      &PSRECFIELDDB.RECNAME.Value = &p_parentRec;
      &PSRECFIELDDB.RECNAME_PARENT.Value = &p_subRec;
   End-For;
end-method;

method GetTableSpace
   /+ &p_rec as String +/
   /+ Returns JsonArray +/
   Local string &SpaceName, &DbName;
   Local JsonArray &TableSpaceArr;
   Local JsonObject &SpaceObj;
   Local SQL &Sql;

   &TableSpaceArr = CreateJsonArray();
   &Sql = CreateSQL("SELECT DDLSPACENAME,DBNAME FROM PSRECTBLSPC WHERE RECNAME = :1", &p_rec);
   While &Sql.Fetch(&SpaceName, &DbName)
      &SpaceObj = CreateJsonObject();
      &SpaceObj.AddProperty("spaceName", &SpaceName);
      &SpaceObj.AddProperty("dbName", &DbName);
      &TableSpaceArr.AddJsonObjectElement("", &SpaceObj);
   End-While;

   Return &TableSpaceArr;
end-method;

method GetPeopleCodeEventByRecord
   /+ &p_rec as String +/
   /+ Returns JsonArray +/
   Local string &FieldName, &LastFieldName;
   Local Record &PSPCMPROG;
   Local Rowset &RsPSPCMPROG;
   Local integer &i, &j;
   Local JsonObject &FieldObj;
   Local JsonArray &PCodeArr, &PCodeEvent;
   Local boolean &EventExist;

   &PCodeArr = CreateJsonArray();
   &RsPSPCMPROG = CreateRowset(Record.PSPCMPROG);
   &RsPSPCMPROG.Flush();
   &RsPSPCMPROG.Fill(" WHERE OBJECTID1 = :1 AND OBJECTVALUE1 = :2 AND OBJECTTYPENAME = 'R'", Key:Class_Record, &p_rec);
   For &i = 1 To &RsPSPCMPROG.ActiveRowCount
      &PSPCMPROG = &RsPSPCMPROG(&i).GetRecord(1);
      If All(&PSPCMPROG.OBJECTVALUE1.Value) Then
         &FieldName = &PSPCMPROG.OBJECTVALUE2.Value;
         If &FieldName <> &LastFieldName Then
            &FieldObj = CreateJsonObject();
            &FieldObj.AddProperty("fieldName", &FieldName);
            &PCodeEvent = CreateJsonArray();
            &FieldObj.AddJsonArray("Events", &PCodeEvent);
            &PCodeEvent.AddElement(&PSPCMPROG.OBJECTVALUE3.Value);
            &PCodeArr.AddJsonObjectElement("", &FieldObj);
         Else
            &EventExist = False;
            For &j = 1 To &PCodeEvent.Size
               If &PCodeEvent.GetString(&j) = &PSPCMPROG.OBJECTVALUE3.Value Then
                  &EventExist = True;
                  Break;
               End-If;
            End-For;
            If Not &EventExist Then
               &PCodeEvent.AddElement(&PSPCMPROG.OBJECTVALUE3.Value);
            End-If;
         End-If;
         &LastFieldName = &FieldName;
      End-If;
   End-For;

   Return &PCodeArr;
end-method;

method GetPeopleCodeEventByField
   /+ &p_fld as String, +/
   /+ &p_arr as JsonArray +/
   /+ Returns JsonArray +/
   Local JsonArray &Events;
   Local JsonObject &FldObj;
   Local integer &i;

   For &i = 1 To &p_arr.Size
      &FldObj = &p_arr.GetJsonObject(&i);
      If &FldObj.GetString("fieldName") = &p_fld Then
         &Events = &FldObj.GetJsonArray("Events");
         Return &Events;
      End-If;
   End-For;
   Return CreateJsonArray();
end-method;

method BuildPSRECFIELDDBs
   /+ &RsPSRECFIELDs as Rowset +/
   /+ Returns Rowset +/
   Local integer &i, &RowIdx;
   Local string &SubRecordName, &ParentRecName;
   Local Record &PSRECFIELD, &PSRECFIELDDB;
   Local Rowset &RsFieldDB;

   &RsFieldDB = CreateRowset(Record.PSRECFIELDDB);

   For &i = 1 To &RsPSRECFIELDs.ActiveRowCount
      &PSRECFIELD = &RsPSRECFIELDs(&i).GetRecord(1);
      If &PSRECFIELD.SUBRECORD.Value = "Y" Then
         &SubRecordName = &PSRECFIELD.GetField(Field.FIELDNAME).Value;
         &ParentRecName = &PSRECFIELD.GetField(Field.RECNAME).Value;
         %This.GetSubRecFields2(&SubRecordName, &ParentRecName, &RsFieldDB);
      Else
         If &RsFieldDB.ActiveRowCount = 1 And
               &RsFieldDB(1).GetRecord(1).FIELDNAME.Value = "" Then
            &PSRECFIELDDB = &RsFieldDB(1).GetRecord(1);
         Else
            &RowIdx = &RsFieldDB.ActiveRowCount + 1;
            &RsFieldDB.InsertRow(&RowIdx - 1);
            &PSRECFIELDDB = &RsFieldDB(&RowIdx).GetRecord(1);
         End-If;
         &PSRECFIELD.CopyFieldsTo(&PSRECFIELDDB);
         &PSRECFIELDDB.RECNAME_PARENT.Value = &PSRECFIELD.GetField(Field.RECNAME).Value;
      End-If;
   End-For;

   Return &RsFieldDB;
end-method;

method GetIndexRecord
   /+ &p_index as JsonArray +/
   /+ Returns Rowset +/
   Local integer &i, &j;
   Local string &IndexId;
   Local Record &PSINDEXDEFN, &PSKEYDEFN;
   Local JsonObject &IndexObj, &FieldObj;
   Local JsonArray &IndexFields;
   Local Rowset &IndexRs, &KeyRs;

   &KeyRs = CreateRowset(Record.PSKEYDEFN);
   &IndexRs = CreateRowset(Record.PSINDEXDEFN, &KeyRs);
   For &i = 1 To &p_index.Size
      If &i <> 1 Then
         &IndexRs.InsertRow(&i - 1);
      End-If;

      &IndexObj = &p_index.GetJsonObject(&i);
      &IndexFields = &IndexObj.GetJsonArray("indexFields");
      &PSINDEXDEFN = &IndexRs(&i).GetRecord(1);
      &PSINDEXDEFN.GetField(Field.RECNAME).Value = &_RecName;
      &PSINDEXDEFN.INDEXID.Value = &IndexObj.GetString("indexId");
      &PSINDEXDEFN.INDEXTYPE.Value = Value(&IndexObj.GetString("indexType"));
      &PSINDEXDEFN.UNIQUEFLAG.Value = Value(&IndexObj.GetString("uniqueFlag"));
      &PSINDEXDEFN.CLUSTERFLAG.Value = Value(&IndexObj.GetString("clusterFlag"));
      &PSINDEXDEFN.ACTIVEFLAG.Value = Value(&IndexObj.GetString("activeFlag"));
      &PSINDEXDEFN.CUSTKEYORDER.Value = Value(&IndexObj.GetString("custKeyOrder"));
      &PSINDEXDEFN.KEYCOUNT.Value = &IndexFields.Size;
      &PSINDEXDEFN.DDLCOUNT.Value = 0;
      &PSINDEXDEFN.PLATFORM_SBS.Value = Value(&IndexObj.GetString("SQLBasePlatform"));
      &PSINDEXDEFN.PLATFORM_DB2.Value = Value(&IndexObj.GetString("DB2Platform"));
      &PSINDEXDEFN.PLATFORM_ORA.Value = Value(&IndexObj.GetString("OraclePlatform"));
      &PSINDEXDEFN.PLATFORM_INF.Value = Value(&IndexObj.GetString("InformixPlatform"));
      &PSINDEXDEFN.PLATFORM_DBX.Value = Value(&IndexObj.GetString("DB2UnixPlatform"));
      &PSINDEXDEFN.PLATFORM_ALB.Value = Value(&IndexObj.GetString("AllBasePlatform"));
      &PSINDEXDEFN.PLATFORM_SYB.Value = Value(&IndexObj.GetString("SybasePlatform"));
      &PSINDEXDEFN.PLATFORM_MSS.Value = Value(&IndexObj.GetString("SqlServerPlatform"));
      &PSINDEXDEFN.PLATFORM_DB4.Value = Value(&IndexObj.GetString("DB2/400Platform"));
      If &IndexObj.IsExist("comment") Then
         &PSINDEXDEFN.IDXCOMMENTS.Value = &CommUtil.UnEscapeJSON(&IndexObj.GetString("comment"));
      End-If;

      &KeyRs = &IndexRs(&i).GetRowset(Scroll.PSKEYDEFN);
      For &j = 1 To &IndexFields.Size
         If &j <> 1 Then
            &KeyRs.InsertRow(&j - 1);
         End-If;
         &FieldObj = &IndexFields.GetJsonObject(&j);
         &PSKEYDEFN = &KeyRs(&j).GetRecord(1);
         &PSKEYDEFN.GetField(Field.RECNAME).Value = &_RecName;
         &PSKEYDEFN.INDEXID.Value = &IndexObj.GetString("indexId");
         &PSKEYDEFN.KEYPOSN.Value = &j;
         &PSKEYDEFN.GetField(Field.FIELDNAME).Value = &FieldObj.GetString("fieldName");
         &PSKEYDEFN.ASCDESC.Value = Value(&FieldObj.GetString("ascDesc"));
      End-For;
   End-For;

   Return &IndexRs;
end-method;

method CreatePrimaryKeyIndexJson
   /+ &p_keyFields as JsonArray +/
   /+ Returns JsonObject +/
   Local integer &i;
   Local JsonObject &PrimaryIndex, &KeyObj, &KeyFieldObj;
   Local JsonArray &KeyArr;

   &PrimaryIndex = CreateJsonObject();
   /* 索引ID 默认下划线 */
   &PrimaryIndex.AddProperty("indexId", "_");
   /* 索引类型 1 */
   &PrimaryIndex.AddProperty("indexType", "1");
   /* 唯一标志 1 */
   &PrimaryIndex.AddProperty("uniqueFlag", "1");
   /* 聚集标志 1 */
   &PrimaryIndex.AddProperty("clusterFlag", "1");
   /* 有效 1 */
   &PrimaryIndex.AddProperty("activeFlag", "1");
   /* 自定义排序 0 */
   &PrimaryIndex.AddProperty("custKeyOrder", "0");
   /* 支持的数据库平台 */
   &PrimaryIndex.AddProperty("SQLBasePlatform", "1");
   &PrimaryIndex.AddProperty("DB2Platform", "1");
   &PrimaryIndex.AddProperty("OraclePlatform", "1");
   &PrimaryIndex.AddProperty("InformixPlatform", "1");
   &PrimaryIndex.AddProperty("DB2UnixPlatform", "1");
   &PrimaryIndex.AddProperty("AllBasePlatform", "1");
   &PrimaryIndex.AddProperty("SybasePlatform", "1");
   &PrimaryIndex.AddProperty("SqlServerPlatform", "1");
   &PrimaryIndex.AddProperty("DB2/400Platform", "0");
   &PrimaryIndex.AddProperty("comment", "");

   &KeyArr = CreateJsonArray();
   For &i = 1 To &p_keyFields.Size
      &KeyFieldObj = &p_keyFields.GetJsonObject(&i);
      &KeyObj = CreateJsonObject();
      &KeyObj.AddProperty("fieldName", &KeyFieldObj.GetString("fieldName"));
      &KeyObj.AddProperty("ascDesc", &KeyFieldObj.GetString("ascDesc"));
      &KeyArr.AddJsonObjectElement("", &KeyObj);
   End-For;
   &PrimaryIndex.AddProperty("indexFields", &KeyArr);
   Return &PrimaryIndex;
end-method;


method MapDefGuiControl
   /+ &p_val as String +/
   /+ Returns Integer +/
   REM 将Default Page Control的请求值映射为PSRECFIELD.DEFGUICONTROL代码;
   REM 已确认代码（GUI实测 2026-09-05）：99=System Default、4=Edit Box、5=Dropdown List、7=Check Box、8=Radio Button;
   If &p_val = "System Default" Then
      Return 99;
   End-If;
   If &p_val = "Edit Box" Then
      Return 4;
   End-If;
   If &p_val = "Dropdown List" Then
      Return 5;
   End-If;
   If &p_val = "Check Box" Then
      Return 7;
   End-If;
   If &p_val = "Radio Button" Then
      Return 8;
   End-If;
   If IsNumber(&p_val) Then
      Return Value(&p_val);
   End-If;
   Return - 1;
end-method;


method SyncPrimaryIndex
   /+ &p_rec as String +/
   Local integer &RecType, &i, &j, &Count, &AscDesc, &UniqueFlag;
   Local number &UseEdit;
   Local string &Name;
   Local Record &IndexRec, &KeyRec;
   Local Rowset &FieldsRs, &OldKeys;
   Local array of string &Names, &Ordered;
   &RecType = - 1;
   SQLExec("SELECT RECTYPE FROM PSRECDEFN WHERE RECNAME = :1", &p_rec, &RecType);
   If &RecType <> 0 And
         &RecType <> 7 Then
      Return;
   End-If;
   &Names = CreateArrayRept("", 0);
   &Ordered = CreateArrayRept("", 0);
   &UniqueFlag = 1;
   &FieldsRs = CreateRowset(Record.PSRECFIELDDB);
   &Count = &FieldsRs.Fill("WHERE RECNAME = :1 ORDER BY FIELDNUM", &p_rec);
   For &i = 1 To &Count
      &UseEdit = &FieldsRs(&i).GetRecord(1).GetField(Field.USEEDIT).Value;
      If Mod(&UseEdit, 4) >= 1 Then
         &Name = &FieldsRs(&i).GetRecord(1).GetField(Field.FIELDNAME).Value;
         If &Names.Find(&Name) = 0 Then
            &Names.Push(&Name);
         End-If;
         If Mod(Int(&UseEdit / 2), 2) = 1 Then
            &UniqueFlag = 0;
         End-If;
      End-If;
   End-For;
   &IndexRec = CreateRecord(Record.PSINDEXDEFN);
   &IndexRec.GetField(Field.RECNAME).Value = &p_rec;
   &IndexRec.GetField(Field.INDEXID).Value = "_";
   If &IndexRec.SelectByKey() Then
      If &IndexRec.GetField(Field.CUSTKEYORDER).Value = 1 Then
         &OldKeys = CreateRowset(Record.PSKEYDEFN);
         &Count = &OldKeys.Fill("WHERE RECNAME = :1 AND INDEXID = '_' ORDER BY KEYPOSN", &p_rec);
         For &i = 1 To &Count
            &Name = &OldKeys(&i).GetRecord(1).GetField(Field.FIELDNAME).Value;
            If &Names.Find(&Name) > 0 Then
               &Ordered.Push(&Name);
            End-If;
         End-For;
      End-If;
   Else
      If &Names.Len = 0 Then
         Return;
      End-If;
      &IndexRec.GetField(Field.INDEXTYPE).Value = 1;
      &IndexRec.GetField(Field.CLUSTERFLAG).Value = 1;
      &IndexRec.GetField(Field.ACTIVEFLAG).Value = 1;
      &IndexRec.GetField(Field.PLATFORM_ORA).Value = 1;
      &IndexRec.GetField(Field.PLATFORM_DB2).Value = 1;
      &IndexRec.GetField(Field.PLATFORM_DBX).Value = 1;
      &IndexRec.GetField(Field.PLATFORM_INF).Value = 1;
      &IndexRec.GetField(Field.PLATFORM_SYB).Value = 1;
      &IndexRec.GetField(Field.PLATFORM_MSS).Value = 1;
      &IndexRec.GetField(Field.PLATFORM_ALB).Value = 1;
      &IndexRec.GetField(Field.PLATFORM_SBS).Value = 1;
      &IndexRec.GetField(Field.UNIQUEFLAG).Value = &UniqueFlag;
      &IndexRec.GetField(Field.KEYCOUNT).Value = &Names.Len;
      If Not &IndexRec.Insert() Then
         &_ErrText = "Failed to create primary index metadata";
         Return;
      End-If;
   End-If;
   For &i = 1 To &Names.Len
      If &Ordered.Find(&Names [&i]) = 0 Then
         &Ordered.Push(&Names [&i]);
      End-If;
   End-For;
   SQLExec("DELETE FROM PSKEYDEFN WHERE RECNAME = :1 AND INDEXID = '_'", &p_rec);
   If &Ordered.Len = 0 Then
      If Not &IndexRec.Delete() Then
         &_ErrText = "Failed to remove empty primary index metadata";
      End-If;
   Else
      For &i = 1 To &Ordered.Len
         &Name = &Ordered [&i];
         &UseEdit = 0;
         SQLExec("SELECT USEEDIT FROM PSRECFIELDDB WHERE RECNAME = :1 AND FIELDNAME = :2", &p_rec, &Name, &UseEdit);
         &AscDesc = 1;
         If Mod(Int(&UseEdit / 64), 2) = 1 Then
            &AscDesc = 0;
         End-If;
         &KeyRec = CreateRecord(Record.PSKEYDEFN);
         &KeyRec.GetField(Field.RECNAME).Value = &p_rec;
         &KeyRec.GetField(Field.INDEXID).Value = "_";
         &KeyRec.GetField(Field.KEYPOSN).Value = &i;
         &KeyRec.GetField(Field.FIELDNAME).Value = &Name;
         &KeyRec.GetField(Field.ASCDESC).Value = &AscDesc;
         If Not &KeyRec.Insert() Then
            &_ErrText = "Failed to synchronize primary index keys";
            Return;
         End-If;
      End-For;
      &IndexRec.GetField(Field.KEYCOUNT).Value = &Ordered.Len;
      &IndexRec.GetField(Field.UNIQUEFLAG).Value = &UniqueFlag;
      If Not &IndexRec.Update() Then
         &_ErrText = "Failed to synchronize primary index header";
         Return;
      End-If;
   End-If;
   SQLExec("UPDATE PSRECDEFN SET INDEXCOUNT = (SELECT COUNT(*) FROM PSINDEXDEFN WHERE RECNAME = :1) WHERE RECNAME = :1", &p_rec);
end-method;


method DeletePeopleCodeCli
   /+ &p_obj as JsonObject +/
   /+ Returns JsonObject +/
   Local string &RecName, &FieldName, &Event;
   Local JsonObject &RespObj;
   Local %metadata:Key &Key;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;

   &RecName = &p_obj.GetString("recordName");
   &FieldName = &p_obj.GetString("fieldName");
