class OperServiceDefn implements PS_PT:Integration:IRequestHandler
   method OperServiceDefn();
   method OnRequest(&message As Message) Returns Message;
end-class;

method OperServiceDefn
end-method;

method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local C_PORTAL_PKG:Util:JsonUtil &json = create C_PORTAL_PKG:Util:JsonUtil();
   Local C_PORTAL_PKG:Util:CommonUtil &util = create C_PORTAL_PKG:Util:CommonUtil();
   Local C_META_DATA_PKG:Utility:NativeAdapter &engine = create C_META_DATA_PKG:Utility:NativeAdapter();
   Local JsonObject &req, &result;
   try
      &req = &json.GetRootObject(&message.GetContentString());
      If Not &req.IsExist("operationType") Or
            Not &req.IsExist("kind") Then
         throw CreateException(0, 0, "operationType and kind are required");
      End-If;
      If &req.GetString("kind") <> "service" Then
         throw CreateException(0, 0, "Kind is not supported by this endpoint");
      End-If;
      &result = &engine.Run(&req);
      Return &json.CreateSuccessMessage("AI_OPER_SERVICE_DEFN_POST", &result);
   catch Exception &ex
      Return &json.CreateFailedMessage("AI_OPER_SERVICE_DEFN_POST", 400, &util.EscapeJSON(&ex.ToString()));
   end-try;
end-method;

