import %metadata:Key;
import %metadata:SqlRepositoryDefn:*;
import PS_PT:Integration:IRequestHandler;
import C_PORTAL_PKG:Util:JsonUtil;
import C_PORTAL_PKG:Util:CommonUtil;
import C_META_DATA_PKG:Utility:MappingUtil;

class OperSqlDefn implements PS_PT:Integration:IRequestHandler
   method OperSqlDefn();

   method OnRequest(&message As Message) Returns Message;
private
   method ViewSqlDefn() Returns JsonObject;
   method CreateSqlDefn(&p_statements As JsonArray);
   method ModifySqlDefn(&p_market As string, &p_dbType As string, &p_effdt As date, &p_descr As string, &p_descrLong As string, &sqlText As string);

   Constant &OperationName = "AI_OPER_SQL_DEFN_POST";
   Constant &DateTimeFormat = "yyyy/MM/dd HH:mm:ss";
   Constant &SQLType = "0";

   instance string &_errText;
   instance string &_sqlId;
   instance C_PORTAL_PKG:Util:JsonUtil &JsonUtil;
   instance C_PORTAL_PKG:Util:CommonUtil &CommUtil;
   instance C_META_DATA_PKG:Utility:MappingUtil &MappingUtil;
end-class;

method OperSqlDefn
   &_errText = "";
   &JsonUtil = create C_PORTAL_PKG:Util:JsonUtil();
   &CommUtil = create C_PORTAL_PKG:Util:CommonUtil();
   &MappingUtil = create C_META_DATA_PKG:Utility:MappingUtil();
end-method;

method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;
   Local JsonObject &ReqObject, &RespObject;
   Local JsonArray &Statements;
   Local string &OperationType, &SqlId, &SqlText, &Market, &DbType, &Descr, &DescrLong;
   Local date &Effdt;

   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());

      If Not &ReqObject.IsExist("sqlId") Then
         &_errText = &_errText | "sqlId is required,";
      End-If;

      /* 参数有误 */
      If &_errText <> "" Then
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_errText);
         Return &RespMsg;
      End-If;

      If &ReqObject.IsExist("operationType") Then
         &OperationType = &ReqObject.GetString("operationType");
      Else
         &OperationType = "view";
      End-If;

      &_sqlId = &ReqObject.GetString("sqlId");

      Evaluate &OperationType
      When "view"
         /*** View SQL ***/
         &RespObject = %This.ViewSqlDefn();
         Break;
      When "create"
         /*** Create SQL ***/
         If &ReqObject.IsExist("statements") Then
            &Statements = &ReqObject.GetJsonArray("statements");
            If &Statements.Size < 1 Then
               &_errText = &_errText | "statements is invalid";
            End-If;
         Else
            &_errText = &_errText | "statements is required for create operation";
         End-If;
         If &_errText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_errText);
            Return &RespMsg;
         End-If;
         %This.CreateSqlDefn(&Statements);
         Break;
      When "modify"
         /*** Modify SQL ***/
         If Not &ReqObject.IsExist("market") Then
            &_errText = &_errText | "market is required for modify operation,";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_errText = &_errText | "dbType is required for modify operation,";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_errText = &_errText | "effdt is required for modify operation,";
         End-If;
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         If &ReqObject.IsExist("descr") Then
            &Descr = &ReqObject.GetString("descr");
         End-If;
         If &ReqObject.IsExist("comment") Then
            &DescrLong = &ReqObject.GetString("comment");
            &DescrLong = &CommUtil.UnEscapeJSON(&DescrLong);
         End-If;
         If &ReqObject.IsExist("sqlText") Then
            &SqlText = &ReqObject.GetString("sqlText");
            &SqlText = &CommUtil.UnEscapeJSON(&SqlText);
         End-If;

         If &_errText <> "" Then
            &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_errText);
            Return &RespMsg;
         End-If;
         %This.ModifySqlDefn(&Market, &DbType, &Effdt, &Descr, &DescrLong, &SqlText);
         Break;
      When-Other
         &_errText = &_errText | "Unknown operationType: " | &OperationType | ". Supported: view, modify";
      End-Evaluate;

      If &_errText <> "" Then
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 400, &_errText);
      Else
         &RespMsg = &JsonUtil.CreateSuccessMessage(&OperationName, &RespObject);
      End-If;
   catch Exception &ex
      &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 500, &CommUtil.EscapeJSON("Error: " | &ex.ToString()));
   end-try;

   Return &RespMsg;
end-method;

method ViewSqlDefn
   /+ Returns JsonObject +/
   Local JsonObject &RespObject, &SQLStatement;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgr;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &defn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &stmtdefn;
   Local %metadata:Key &key;
   Local string &SqlText = "";
   Local integer &i;
   Local JsonArray &Statements;

   &RespObject = CreateJsonObject();
   &mgr = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &key = create %metadata:Key(Key:Class_Sql, &_sqlId, Key:Class_SqlType, &SQLType);

   If Not &mgr.DefnExists(&key) Then
      &_errText = &_errText | "sql not exist";
      Return &RespObject;
   End-If;

   &defn = &mgr.GetDefn(&key);
   &Statements = CreateJsonArray();

   &RespObject.AddProperty("sqlId", &defn.SqlId);
   &RespObject.AddProperty("sqlType", &defn.SqlType);
   &RespObject.AddProperty("lastUpdate", "Last updated by: " | &defn.LastUpdOprId | ", " | DateTimeToLocalizedString(&defn.LastUpdDttm, &DateTimeFormat));
   &RespObject.AddJsonArray("statements", &Statements);

   /*** Concatenate all statement rows ***/
   For &i = 1 To &defn.Count_StmtT
      &stmtdefn = &defn.Get_StmtT(&i);
      &SQLStatement = CreateJsonObject();
      &SQLStatement.AddProperty("market", &stmtdefn.Market);
      &SQLStatement.AddProperty("dbType", &stmtdefn.DbType);
      &SQLStatement.AddProperty("effdt", &stmtdefn.EffDt);
      &SQLStatement.AddProperty("sqlText", &CommUtil.EscapeJSON(&stmtdefn.SqlText));
      &SQLStatement.AddProperty("descr", &stmtdefn.Descr);
      &SQLStatement.AddProperty("comment", &CommUtil.EscapeJSON(&stmtdefn.DescrLong));
      &Statements.AddJsonObjectElement("", &SQLStatement);
   End-For;

   Return &RespObject;
end-method;

method CreateSqlDefn
   /+ &p_statements as JsonArray +/
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgr;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &defn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &stmtdefn;
   Local %metadata:Key &key;
   Local integer &i, &DbTypeCode;
   Local JsonObject &StatementObj;
   Local string &Market, &DbType, &SqlText, &Descr, &DescrLong;
   Local date &Effdt;

   &mgr = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &key = create %metadata:Key(Key:Class_Sql, &_sqlId);
   &key.AddItem(Key:Class_SqlType, &SQLType);

   If &mgr.DefnExists(&key) Then
      &_errText = &_errText | "sql already exist";
      Return;
   End-If;

   &defn = &mgr.CreateDefn();
   &defn.SqlId = &_sqlId;
   &defn.SqlType = &SQLType;
   For &i = 1 To &p_statements.Size
      &StatementObj = &p_statements.GetJsonObject(&i);
      If &StatementObj.IsExist("market") Then
         &Market = &StatementObj.GetString("market");
      Else
         &Market = "GBL";
      End-If;
      If &StatementObj.IsExist("dbType") Then
         &DbType = &StatementObj.GetString("dbType");
         &DbTypeCode = &MappingUtil.GetDbTypeCode(&DbType);
      Else
         &DbType = "";
         &DbTypeCode = &MappingUtil.GetDbTypeCode(&DbType);
      End-If;
      If &StatementObj.IsExist("effdt") Then
         &Effdt = Date(&StatementObj.GetString("effdt"));
      Else
         &Effdt = Date3(1900, 1, 1);
      End-If;
      If &StatementObj.IsExist("sqlText") Then
         &SqlText = &CommUtil.UnEscapeJSON(&StatementObj.GetString("sqlText"));
         &SqlText = &CommUtil.ReplaceWithRegex(&SqlText, "\s+", " ");
      Else
         &_errText = &_errText | "sqlText is required";
         Return;
      End-If;
      If &StatementObj.IsExist("descr") Then
         &Descr = &StatementObj.GetString("descr");
      End-If;
      If &StatementObj.IsExist("comment") Then
         &DescrLong = &CommUtil.UnEscapeJSON(&StatementObj.GetString("comment"));
      End-If;
      &stmtdefn = &defn.Append_StmtT(&i - 1);
      &stmtdefn.Market = &Market;
      &stmtdefn.DbType = &DbTypeCode;
      &stmtdefn.EffDt = &Effdt;
      &stmtdefn.SqlText = &SqlText;
      If All(&Descr) Then
         &stmtdefn.Descr = &Descr;
      End-If;
      If All(&DescrLong) Then
         &stmtdefn.DescrLong = &DescrLong;
      End-If;
   End-For;

   If Not &defn.SaveNewDefn() Then
      &_errText = &_errText | "create sql failed";
   End-If;
end-method;

method ModifySqlDefn
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_descr as String, +/
   /+ &p_descrLong as String, +/
   /+ &sqlText as String +/
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgr;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &defn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &stmtdefn;
   Local %metadata:Key &key;
   Local integer &i, &DbTypeCode;
   Local boolean &Matched = False;

   /* 初始化变量 */
   If None(&p_market) Then
      &p_market = "GBL";
   End-If;

   If None(&p_effdt) Then
      &p_effdt = Date3(1900, 1, 1);
   End-If;

   &DbTypeCode = &MappingUtil.GetDbTypeCode(&p_dbType);
   &mgr = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &key = create %metadata:Key(Key:Class_Sql, &_sqlId, Key:Class_SqlType, &SQLType);

   If Not &mgr.DefnExists(&key) Then
      throw CreateException(0, 0, "SQL definition not found: " | &_sqlId | " (type=" | &SQLType | ")");
   End-If;

   &defn = &mgr.GetDefnToUpdate(&key);

   For &i = 1 To &defn.Count_StmtT
      &stmtdefn = &defn.Get_StmtT(&i);
      If &stmtdefn.Market = &p_market And
            &stmtdefn.DbType = &DbTypeCode And
            &stmtdefn.EffDt = &p_effdt Then
         &Matched = True;
         If All(&p_descr) Then
            &stmtdefn.Descr = &p_descr;
         End-If;
         If All(&p_descrLong) Then
            &stmtdefn.DescrLong = &p_descrLong;
         End-If;
         If All(&sqlText) Then
            &sqlText = &CommUtil.ReplaceWithRegex(&sqlText, "\s+", " ");
            &stmtdefn.SqlText = &sqlText;
         End-If;
      End-If;
   End-For;

   If Not &Matched Then
      &_errText = "SQL Statement not found for market/dbType/effdt";
      Return;
   End-If;

   If Not &defn.UpdateDefn() Then
      &_errText = &_errText | "modify sql failed";
   End-If;
end-method;

import PS_PT:Integration:IRequestHandler;
import C_PORTAL_PKG:Util:JsonUtil;

class SearchDefinition implements PS_PT:Integration:IRequestHandler
   method SearchDefinition();

   method OnRequest(&message As Message) Returns Message;
private
   method GetRecordDefinition(&p_name As string, &p_type As integer, &p_descr As string) Returns JsonArray;
   method GetFieldDefinition(&p_name As string, &p_type As integer) Returns JsonArray;
   method GetAppPackageDefinition(&p_name As string, &p_descr As string) Returns JsonArray;
   method GetSqlDefinition(&p_name As string, &p_type As integer, &p_descr As string) Returns JsonArray;
   method GetProjectDefinition(&p_name As string, &p_descr As string) Returns JsonArray;

   Constant &OperationName = "AI_SEARCH_DEFN_POST";
   Constant &DateTimeFormat = "yyyy/MM/dd HH:mm:ss";
   instance C_PORTAL_PKG:Util:JsonUtil &JsonUtil;
end-class;


method SearchDefinition
   &JsonUtil = create C_PORTAL_PKG:Util:JsonUtil();
end-method;


method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;
   Local JsonObject &ReqObject, &RespObject;
   Local JsonArray &DefnArr;
   Local integer &i, &j, &DefnType;
   Local string &DefnName, &RecordDescr, &AppPackageDescr, &SqlDescr, &ProjectDescr;

   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());
      &RespObject = CreateJsonObject();

      /* 获取参数 */
      If Not &ReqObject.IsExist("definitionType") Then
         throw CreateException(0, 0, "definitionType is required");
      End-If;
      &DefnType = &ReqObject.GetNumber("definitionType");
      If &ReqObject.IsExist("definitionName") Then
         &DefnName = &ReqObject.GetString("definitionName");
      End-If;

      Evaluate &DefnType
      When 1
         /** 查Record **/
         Local integer &RecType = - 1;
         If &ReqObject.IsExist("recordType") Then
            &RecType = &ReqObject.GetNumber("recordType");
         End-If;
         If &ReqObject.IsExist("recordDescr") Then
            &RecordDescr = &ReqObject.GetString("recordDescr");
         End-If;
         &DefnArr = %This.GetRecordDefinition(&DefnName, &RecType, &RecordDescr);
         Break;
      When 2
         /** 查Field **/
         Local integer &FldType = - 1;
         If &ReqObject.IsExist("fieldType") Then
            &FldType = &ReqObject.GetNumber("fieldType");
         End-If;
         &DefnArr = %This.GetFieldDefinition(&DefnName, &FldType);
         Break;
      When 104
         /** 查Application Package **/
         If &ReqObject.IsExist("appPackageDescr") Then
            &AppPackageDescr = &ReqObject.GetString("appPackageDescr");
         End-If;
         &DefnArr = %This.GetAppPackageDefinition(&DefnName, &AppPackageDescr);
         Break;
      When 65
         /** 查SQL定义 **/
         Local integer &SqlType = - 1;
         If &ReqObject.IsExist("sqlType") Then
            &SqlType = &ReqObject.GetNumber("sqlType");
         End-If;
         If &ReqObject.IsExist("sqlDescr") Then
            &SqlDescr = &ReqObject.GetString("sqlDescr");
         End-If;
         &DefnArr = %This.GetSqlDefinition(&DefnName, &SqlType, &SqlDescr);
         Break;
      When 105
         /*** 查Project ***/
         If &ReqObject.IsExist("projectDescr") Then
            &ProjectDescr = &ReqObject.GetString("projectDescr");
         End-If;
         &DefnArr = %This.GetProjectDefinition(&DefnName, &ProjectDescr);
         Break;
      When-Other
         throw CreateException(0, 0, "definitionType is not exists");
      End-Evaluate;

      &RespObject.AddJsonArray("list", &DefnArr);
      &RespMsg = &JsonUtil.CreateSuccessMessage(&OperationName, &RespObject);
   catch Exception &ex
      &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 999, "遇到异常：" | &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

method GetRecordDefinition
   /+ &p_name as String, +/
   /+ &p_type as Integer, +/
   /+ &p_descr as String +/
   /+ Returns JsonArray +/
   Local JsonArray &Records;
   Local string &SelectStr, &WhereStr;
   Local string &RecName, &RecDescr;
   Local SQL &Sql;
   Local integer &i;

   &Records = CreateJsonArray();
   &SelectStr = "SELECT RECNAME,RECDESCR FROM PSRECDEFN";
   &WhereStr = " WHERE 1 = 1";

   /* 拼接查询参数 */
   If All(&p_name) Then
      If Right(&p_name, 1) <> "%" Then
         &p_name = &p_name | "%";
      End-If;
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND RECNAME LIKE :1", &p_name);
   End-If;
   If &p_type <> - 1 Then
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND RECTYPE = :1", &p_type);
   End-If;
   If All(&p_descr) Then
      If Right(&p_descr, 1) <> "%" Then
         &p_descr = &p_descr | "%";
      End-If;
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND RECDESCR LIKE :1", &p_descr);
   End-If;

   &Sql = CreateSQL(&SelectStr | &WhereStr);
   While &Sql.Fetch(&RecName, &RecDescr)
      Local JsonObject &RecObj = CreateJsonObject();
      &RecObj.AddProperty("recordName", &RecName);
      &RecObj.AddProperty("recordDescr", &RecDescr);
      &Records.AddJsonObjectElement("", &RecObj);
   End-While;

   Return &Records;
end-method;

method GetFieldDefinition
   /+ &p_name as String, +/
   /+ &p_type as Integer +/
   /+ Returns JsonArray +/
   Local JsonArray &Fields;
   Local string &SelectStr, &WhereStr;
   Local string &FieldName;
   Local integer &FieldType, &Length;
   Local SQL &Sql;

   &Fields = CreateJsonArray();
   &SelectStr = "SELECT FIELDNAME,FIELDTYPE,LENGTH FROM PSDBFIELD";
   &WhereStr = " WHERE 1 = 1";

   /* 拼接查询参数 */
   If All(&p_name) Then
      If Right(&p_name, 1) <> "%" Then
         &p_name = &p_name | "%";
      End-If;
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND FIELDNAME LIKE :1", &p_name);
   End-If;
   If &p_type <> - 1 Then
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND FIELDTYPE = :1", &p_type);
   End-If;

   &Sql = CreateSQL(&SelectStr | &WhereStr);
   While &Sql.Fetch(&FieldName, &FieldType, &Length)
      Local JsonObject &FieldObj = CreateJsonObject();
      &FieldObj.AddProperty("fieldName", &FieldName);
      &FieldObj.AddProperty("fieldType", &FieldType);
      &FieldObj.AddProperty("length", &Length);
      &Fields.AddJsonObjectElement("", &FieldObj);
   End-While;

   Return &Fields;
end-method;

method GetAppPackageDefinition
   /+ &p_name as String, +/
   /+ &p_descr as String +/
   /+ Returns JsonArray +/
   Local JsonArray &AppPackages;
   Local string &SelectStr, &WhereStr;
   Local string &AppPackageId, &Descr;
   Local SQL &Sql;

   &AppPackages = CreateJsonArray();
   &SelectStr = "SELECT PACKAGEID,DESCR FROM PSPACKAGEDEFN";
   &WhereStr = " WHERE 1 = 1";

   /* 拼接查询参数 */
   If All(&p_name) Then
      If Right(&p_name, 1) <> "%" Then
         &p_name = &p_name | "%";
      End-If;
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND PACKAGEID LIKE :1", &p_name);
   End-If;
   If All(&p_descr) Then
      If Right(&p_descr, 1) <> "%" Then
         &p_descr = &p_descr | "%";
      End-If;
