   Return &Projects;
end-method;

/* 查询输入验证与绑定参数；已在 PANWX25 编译和直接 REST 验收。
   目标：PANWX25 / Oracle / PeopleTools 8.60.10。
   Record/Field 由元数据验证；过滤值及行数全部使用绑定参数。 */
import PS_PT:Integration:IRequestHandler;
import C_PORTAL_PKG:Util:JsonUtil;
import C_META_DATA_PKG:Utility:MappingUtil;

class OperQueryRecord implements PS_PT:Integration:IRequestHandler
   method OperQueryRecord();
   method OnRequest(&message As Message) Returns Message;
private
   method StringNode(&node As JsonNode, &label As string) Returns string;
   method Identifier(&name As string, &label As string) Returns string;
   method ResolveRecord(&requested As string);
   method FieldType(&name As string) Returns integer;
   method ValidateRequest(&req As JsonObject);
   method Query() Returns JsonObject;
   Constant &OperationName = "AI_QUERY_RECORD_POST";
   instance C_PORTAL_PKG:Util:JsonUtil &JsonUtil;
   instance C_META_DATA_PKG:Utility:MappingUtil &MappingUtil;
   instance Record &MetadataRecord;
   instance string &RequestedRecord, &LogicalRecord, &TableName, &SelectSql;
   instance array of string &Fields;
   instance array of number &Types;
   instance array of any &Binds;
end-class;

method OperQueryRecord
   &JsonUtil = create C_PORTAL_PKG:Util:JsonUtil();
   &MappingUtil = create C_META_DATA_PKG:Utility:MappingUtil();
end-method;

method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local JsonObject &req, &data;
   Local string &body = &message.GetContentString();
   try
      If Len(&body) > 262144 Then
         throw CreateException(0, 0, "Query request exceeds 262144 characters");
      End-If;
      &req = &JsonUtil.GetRootObject(&body);
      %This.ValidateRequest(&req);
   catch Exception &validationError
      Return &JsonUtil.CreateFailedMessage(&OperationName, 400, &validationError.ToString());
   end-try;
   try
      &data = %This.Query();
      Return &JsonUtil.CreateSuccessMessage(&OperationName, &data);
   catch Exception &queryError
      Return &JsonUtil.CreateFailedMessage(&OperationName, 999, &queryError.ToString());
   end-try;
end-method;

method StringNode
   /+ &node as JsonNode, +/
   /+ &label as String +/
   /+ Returns String +/
   If &node.GetNodeType() <> 3 Or
         &node.GetValueType() <> 6 Then
      throw CreateException(0, 0, &label | " must be a JSON string; quote numeric values");
   End-If;
   Return &node.GetString();
end-method;

method Identifier
   /+ &name as String, +/
   /+ &label as String +/
   /+ Returns String +/
   Local string &nameUpper = Upper(&name);
   Local string &ch;
   Local integer &i;
   If Len(&nameUpper) = 0 Or
         Len(&nameUpper) > 128 Then
      throw CreateException(0, 0, &label | " must be a single identifier (1..128 characters)");
   End-If;
   For &i = 1 To Len(&nameUpper)
      &ch = Substring(&name, &i, 1);
      If Not ((&ch >= "A" And
            &ch <= "Z") Or
            (&ch >= "a" And
               &ch <= "z") Or
            (&i > 1 And
               ((&ch >= "0" And
                  &ch <= "9") Or
                  &ch = "_"))) Then
         throw CreateException(0, 0, &label | " must contain only ASCII letters, digits and underscore");
      End-If;
   End-For;
   Return &nameUpper;
end-method;

method ResolveRecord
   /+ &requested as String +/
   Local integer &recordType = - 1;
   Local string &candidateRecord, &candidateTable, &logicalName, &sqlTable;
   Local integer &candidateType;
   Local SQL &lookup;
   &logicalName = "";
   &sqlTable = "";
   &LogicalRecord = "";
   &TableName = "";
   SQLExec("SELECT RECNAME, RECTYPE, SQLTABLENAME FROM PSRECDEFN WHERE RECNAME = :1", &requested, &logicalName, &recordType, &sqlTable);
   &LogicalRecord = &logicalName;
   &TableName = &sqlTable;
   If &LogicalRecord = "" Then
      &lookup = CreateSQL("SELECT RECNAME, RECTYPE, SQLTABLENAME FROM PSRECDEFN " | "WHERE SQLTABLENAME = :1 OR (TRIM(SQLTABLENAME) IS NULL AND 'PS_' || RECNAME = :1)", &requested);
      While &lookup.Fetch(&candidateRecord, &candidateType, &candidateTable)
         If &LogicalRecord <> "" Then
            &lookup.Close();
            throw CreateException(0, 0, "Physical table maps to more than one Record; specify the logical Record");
         End-If;
         &LogicalRecord = &candidateRecord;
         &recordType = &candidateType;
         &TableName = &candidateTable;
      End-While;
      &lookup.Close();
   End-If;
   If &LogicalRecord = "" Then
      throw CreateException(0, 0, "Record is not registered in PSRECDEFN");
   End-If;
   If &recordType <> 0 And
         &recordType <> 1 And
         &recordType <> 6 And
         &recordType <> 7 Then
      throw CreateException(0, 0, "Record has no queryable physical table/view");
   End-If;
   If &TableName = "" Then
      &TableName = "PS_" | &LogicalRecord;
   End-If;
   &TableName = %This.Identifier(RTrim(LTrim(&TableName)), "metadata SQL table name");
   &MetadataRecord = CreateRecord(@("Record." | &LogicalRecord));
end-method;

method FieldType
   /+ &name as String +/
   /+ Returns Integer +/
   Local Field &field;
   Local integer &type = - 1;
   try
      &field = &MetadataRecord.GetField(@("Field." | &name));
   catch Exception &fieldError
      throw CreateException(0, 0, "Field is not a member of the requested Record: " | &name);
   end-try;
   SQLExec("SELECT FIELDTYPE FROM PSDBFIELD WHERE FIELDNAME = :1", &name, &type);
   If &type <> 0 And
         &type <> 1 And
         &type <> 2 And
         &type <> 3 And
         &type <> 4 And
         &type <> 5 And
         &type <> 6 And
         &type <> 9 Then
      throw CreateException(0, 0, "Unsupported query field type: " | &name);
   End-If;
   Return &type;
end-method;

method ValidateRequest
   /+ &req as JsonObject +/
   Local JsonArray &fieldsArr, &filterArr;
   Local JsonNode &node;
   Local JsonObject &filter;
   Local integer &i, &j, &type;
   Local number &maxRows = 200;
   Local string &name, &op, &value, &projection, &whereClause;
   &whereClause = "";
   &Fields = CreateArrayRept("", 0);
   &Types = CreateArrayRept(0, 0);
   &Binds = CreateArrayAny();
   If Not &req.IsExist("record") Or
         Not &req.IsExist("fields") Then
      throw CreateException(0, 0, "record and fields are required");
   End-If;
   &node = &req.GetJsonNode("record");
   &name = %This.StringNode(&node, "record");
   &RequestedRecord = %This.Identifier(&name, "record");
   &node = &req.GetJsonNode("fields");
   If Not &node.IsJsonArray() Then
      throw CreateException(0, 0, "fields must be an array");
   End-If;
   &fieldsArr = &node.GetJsonArray();
   If &fieldsArr.Size = 0 Or
         &fieldsArr.Size > 64 Then
      throw CreateException(0, 0, "fields must contain 1..64 names");
   End-If;
   &filterArr = CreateJsonArray();
   If &req.IsExist("filter") Then
      &node = &req.GetJsonNode("filter");
      If Not &node.IsJsonArray() Then
         throw CreateException(0, 0, "filter must be an array");
      End-If;
      &filterArr = &node.GetJsonArray();
   End-If;
   If &filterArr.Size > 50 Then
      throw CreateException(0, 0, "filter supports at most 50 conditions");
   End-If;
   If &req.IsExist("maxRows") Then
      &node = &req.GetJsonNode("maxRows");
      &type = &node.GetValueType();
      If &node.GetNodeType() <> 3 Or
            &type < 1 Or
            &type > 4 Then
         throw CreateException(0, 0, "maxRows must be an integer");
      End-If;
      &maxRows = &node.GetNumber();
   End-If;
   If &maxRows <> Int(&maxRows) Then
      throw CreateException(0, 0, "maxRows must be an integer");
   End-If;
   If &maxRows <= 0 Then
      &maxRows = 200;
   End-If;
   If &maxRows > 1000 Then
      throw CreateException(0, 0, "maxRows must not exceed 1000");
   End-If;
   %This.ResolveRecord(&RequestedRecord);
   &SelectSql = "SELECT ";
   For &i = 1 To &fieldsArr.Size
      If &fieldsArr.GetType(&i) <> 6 Then
         throw CreateException(0, 0, "fields entry must be a JSON string");
      End-If;
      &name = &fieldsArr.GetString(&i);
      &name = %This.Identifier(&name, "fields entry");
      For &j = 1 To &Fields.Len
         If &Fields [&j] = &name Then
            throw CreateException(0, 0, "Duplicate selected field: " | &name);
         End-If;
      End-For;
      &type = %This.FieldType(&name);
      &Fields.Push(&name);
      &Types.Push(&type);
      &projection = &name;
      If &type = 2 Or
            &type = 3 Then
         &projection = "TO_CHAR(" | &name | ", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''')";
      End-If;
      If &type = 4 Or
            &type = 5 Or
            &type = 6 Then
         REM 沿用环境的默认 SQL 日期/时间格式，不顺带更改 API 展示契约;
         &projection = "TO_CHAR(" | &name | ")";
      End-If;
      If &i > 1 Then
         &SelectSql = &SelectSql | ", ";
      End-If;
      &SelectSql = &SelectSql | &projection;
   End-For;
   For &i = 1 To &filterArr.Size
      try
         &filter = &filterArr.GetJsonObject(&i);
      catch Exception &filterTypeError
         throw CreateException(0, 0, "Each filter entry must be an object");
      end-try;
      If Not &filter.IsExist("field") Or
            Not &filter.IsExist("op") Or
            Not &filter.IsExist("value") Then
         throw CreateException(0, 0, "Each filter entry requires field, op and value");
      End-If;
      If &filter.GetChildCount() <> 3 Then
         throw CreateException(0, 0, "Filter entry contains unknown properties");
      End-If;
      &node = &filter.GetJsonNode("field");
      &name = %This.StringNode(&node, "filter.field");
      &name = %This.Identifier(&name, "filter.field");
      &type = %This.FieldType(&name);
      &node = &filter.GetJsonNode("op");
      &op = %This.StringNode(&node, "filter.op");
      &op = Upper(&op);
      If &op <> "=" And
            &op <> "<>" And
            &op <> "!=" And
            &op <> ">" And
            &op <> ">=" And
            &op <> "<" And
            &op <> "<=" And
            &op <> "LIKE" And
            &op <> "NOT LIKE" Then
         throw CreateException(0, 0, "Unsupported filter operator");
      End-If;
      &node = &filter.GetJsonNode("value");
      &value = %This.StringNode(&node, "filter.value");
      If Len(&value) > 4000 Or
            Find(Char(0), &value) > 0 Then
         throw CreateException(0, 0, "filter.value exceeds 4000 characters or contains NUL");
      End-If;
      &Binds.Push(&value);
      If &i > 1 Then
         &whereClause = &whereClause | " AND ";
      End-If;
      &whereClause = &whereClause | &name | " " | &op | " :" | String(&Binds.Len);
   End-For;
   &SelectSql = &SelectSql | " FROM " | &TableName;
   If &whereClause <> "" Then
      &SelectSql = &SelectSql | " WHERE " | &whereClause;
   End-If;
   &Binds.Push(&maxRows);
   &SelectSql = "SELECT * FROM (" | &SelectSql | ") WHERE ROWNUM <= :" | String(&Binds.Len);
end-method;

method Query
   /+ Returns JsonObject +/
   Local SQL &cursor;
   Local array of any &values = CreateArrayAny();
   Local JsonArray &rows, &meta, &rowValues;
   Local JsonObject &result, &row, &field;
   Local integer &i, &format;
   Local string &text;
   &rows = CreateJsonArray();
   &meta = CreateJsonArray();
   &result = CreateJsonObject();
   For &i = 1 To &Fields.Len
      &format = 0;
      SQLExec("SELECT FORMAT FROM PSDBFIELD WHERE FIELDNAME = :1", &Fields [&i], &format);
      &field = CreateJsonObject();
      &field.AddProperty("name", &Fields [&i]);
      &field.AddProperty("label", "");
      &field.AddProperty("type", &MappingUtil.GetFieldTypeName(&Types [&i], &format));
      &meta.AddJsonObjectElement("", &field);
   End-For;
   try
      &cursor = CreateSQL(&SelectSql, &Binds);
      While &cursor.Fetch(&values)
         &rowValues = CreateJsonArray();
         For &i = 1 To &Fields.Len
            &text = "";
            If All(&values [&i]) Then
               &text = &values [&i];
            End-If;
            &rowValues.AddElement(&text);
         End-For;
         &row = CreateJsonObject();
         &row.AddJsonArray("v", &rowValues);
         &rows.AddJsonObjectElement("", &row);
      End-While;
      &cursor.Close();
   catch Exception &error
      If All(&cursor) Then
         &cursor.Close();
      End-If;
      throw &error;
   end-try;
   &result.AddProperty("record", &RequestedRecord);
   &result.AddJsonArray("fields", &meta);
   &result.AddJsonArray("rows", &rows);
   &result.AddProperty("rowCount", &rows.Size);
   Return &result;
end-method;

import C_PORTAL_PKG:Util:CommonUtil;

class CatalogAdapter
   method CatalogAdapter();
   method Run(&req As JsonObject) Returns JsonObject;
private
   method Snapshot(&ci As ApiObject) Returns JsonObject;
   method Errors(&session As ApiObject) Returns string;
end-class;

method CatalogAdapter
end-method;

method Errors
   /+ &session as ApiObject +/
   /+ Returns String +/
   Local string &text = "";
   Local integer &i;
   For &i = 1 To &session.PSMessages.Count
      &text = &text | &session.PSMessages.Item(&i).Text | " ";
   End-For;
   Return &text;
end-method;

method Snapshot
   /+ &ci as ApiObject +/
   /+ Returns JsonObject +/
   Local JsonObject &result = CreateJsonObject();
   Local JsonObject &row;
   Local JsonArray &rows = CreateJsonArray();
   Local ApiObject &messages = &ci.PSMSGCATDEFN;
   Local ApiObject &item;
   Local integer &i;
   Local C_PORTAL_PKG:Util:CommonUtil &util = create C_PORTAL_PKG:Util:CommonUtil();
   &result.AddProperty("messageSet", Value(&ci.MESSAGE_SET_NBR));
   &result.AddProperty("descr", &util.EscapeJSON(&ci.DESCR));
   &result.AddProperty("descrShort", &util.EscapeJSON(&ci.DESCRSHORT));
   &result.AddProperty("language", %Language);
   &result.AddProperty("baseLanguage", %Language_Base);
   For &i = 1 To &messages.Count
      &item = &messages.Item(&i);
      &row = CreateJsonObject();
      &row.AddProperty("messageNumber", Value(&item.MESSAGE_NBR));
      &row.AddProperty("text", &util.EscapeJSON(&item.MESSAGE_TEXT));
      &row.AddProperty("explanation", &util.EscapeJSON(&item.DESCRLONG));
      &row.AddProperty("severity", &item.MSG_SEVERITY);
      &rows.AddJsonObjectElement("", &row);
   End-For;
   &result.AddJsonArray("messages", &rows);
   Return &result;
end-method;

method Run
   /+ &req as JsonObject +/
   /+ Returns JsonObject +/
   Local ApiObject &session = %Session;
   Local ApiObject &ci = &session.GetCompIntfc(CompIntfc.MESSAGE_CATALOG_CI);
   Local ApiObject &messages, &item;
   Local string &action = &req.GetString("operationType");
   Local number &set = Value(&req.GetString("name"));
   Local number &messageNumber = 0;
   Local integer &i, &found;
   Local boolean &exists, &ok;
   Local boolean &dryRun = False;
   Local JsonObject &before, &after, &result, &patch;
   Local string &text, &explanation, &severity, &field;
   If &set < 1 Or
         &set > 32767 Or
         &set <> Int(&set) Then
      throw CreateException(0, 0, "messageSet must be an integer from 1 through 32767");
   End-If;
   &ci.InteractiveMode = True;
   &ci.MESSAGE_SET_NBR = &set;
   &exists = &ci.Get();
   If &action = "exists" Then
      &result = CreateJsonObject();
      &result.AddProperty("exists", &exists);
      Return &result;
   End-If;
   If &action = "createSet" Then
      If &exists Then
         throw CreateException(0, 0, "Message set already exists");
      End-If;
      &session.PSMessages.DeleteAll();
      If Not &ci.Create() Then
         throw CreateException(0, 0, "CI Create failed: " | %This.Errors(&session));
      End-If;
   Else
      If Not &exists Then
         throw CreateException(0, 0, "Message set does not exist");
      End-If;
   End-If;
   &before = %This.Snapshot(&ci);
   If &action = "view" Or
         &action = "struct" Then
      Local C_PORTAL_PKG:Util:CommonUtil &stateUtil = create C_PORTAL_PKG:Util:CommonUtil();
      &before.AddProperty("stateToken", &stateUtil.EscapeJSON(&before.ToString()));
      Return &before;
   End-If;
   If &set < 1000 Then
      throw CreateException(0, 0, "PeopleTools message sets 1-999 are read-only");
   End-If;
   If %Language <> %Language_Base Then
      throw CreateException(0, 0, "Message Catalog writes require a base-language session; translation writes are deferred");
   End-If;
   If &req.IsExist("expectedState") And
         &req.GetString("expectedState") <> &before.ToString() Then
      throw CreateException(0, 0, "Message Catalog changed since snapshot");
   End-If;
   If &req.IsExist("dryRun") Then
      &dryRun = &req.GetBoolean("dryRun");
   End-If;
   If &req.IsExist("messageNumber") Then
      &messageNumber = &req.GetNumber("messageNumber");
      If &messageNumber < 1 Or
            &messageNumber > 32767 Or
            &messageNumber <> Int(&messageNumber) Then
         throw CreateException(0, 0, "messageNumber must be an integer from 1 through 32767");
      End-If;
   End-If;
   &messages = &ci.PSMSGCATDEFN;
   &found = 0;
   For &i = 1 To &messages.Count
      &item = &messages.Item(&i);
      If Value(&item.MESSAGE_NBR) = &messageNumber Then
         &found = &i;
         Break;
      End-If;
   End-For;
   If &action = "delete" Then
      If &messageNumber = 0 Or
            &found = 0 Then
         throw CreateException(0, 0, "Exact existing messageNumber is required for deletion");
      End-If;
      If Not &ci.DeleteMessage(&messageNumber) Then
         throw CreateException(0, 0, "CI DeleteMessage failed");
      End-If;
   Else
      If &action <> "create" And
            &action <> "modify" And
            &action <> "createSet" Then
         throw CreateException(0, 0, "Unsupported operationType");
      End-If;
      &patch = &req.GetJsonObject("properties");
      For &i = 1 To &patch.ChildCount
         &field = &patch.GetPropertyNameAt(&i);
         If CreateArray("text", "explanation", "severity", "descr", "descrShort").Find(&field) = 0 Then
            throw CreateException(0, 0, "Unknown Catalog property: " | &field);
         End-If;
      End-For;
      If &action = "modify" Then
         If &messageNumber <> 0 And
               &found = 0 Then
            throw CreateException(0, 0, "Message does not exist");
         End-If;
      Else
         If &found > 0 Then
            throw CreateException(0, 0, "Message already exists");
         End-If;
         If Not &patch.IsExist("text") Then
            throw CreateException(0, 0, "New messages require text");
         End-If;
         &text = &patch.GetString("text");
         &explanation = "";
         &severity = "Message";
         If &patch.IsExist("explanation") Then
            &explanation = &patch.GetString("explanation");
         End-If;
         If &patch.IsExist("severity") Then
            &severity = &patch.GetString("severity");
         End-If;
         If CreateArray("Message", "Warning", "Error", "Cancel").Find(&severity) = 0 Then
            throw CreateException(0, 0, "Invalid message severity");
         End-If;
         If Len(&text) > 100 Then
            throw CreateException(0, 0, "Message text exceeds 100 characters");
         End-If;
         Local number &allocated;
         If &action = "createSet" Then
            &item = &messages.Item(1);
            &found = 1;
            &allocated = Value(&item.MESSAGE_NBR);
         Else
            &allocated = &ci.AddMessage(&text, &explanation, &severity);
            If &allocated = 0 Then
               throw CreateException(0, 0, "CI AddMessage failed");
            End-If;
            &messages = &ci.PSMSGCATDEFN;
            For &i = 1 To &messages.Count
               &item = &messages.Item(&i);
               If Value(&item.MESSAGE_NBR) = &allocated Then
                  &found = &i;
                  Break;
               End-If;
            End-For;
         End-If;
         If &messageNumber = 0 Then
            &messageNumber = &allocated;
         Else
            &item.MESSAGE_NBR = &messageNumber;
         End-If;
      End-If;
      If &patch.IsExist("descr") Then
         &ci.DESCR = &patch.GetString("descr");
      End-If;
      If &patch.IsExist("descrShort") Then
         &ci.DESCRSHORT = &patch.GetString("descrShort");
      End-If;
      If &messageNumber > 0 Then
         &item = &messages.Item(&found);
         If &patch.IsExist("text") Then
            &text = &patch.GetString("text");
            If Len(&text) > 100 Then
               throw CreateException(0, 0, "Message text exceeds 100 characters");
            End-If;
            &item.MESSAGE_TEXT = &text;
         End-If;
         If &patch.IsExist("explanation") Then
            &item.DESCRLONG = &patch.GetString("explanation");
         End-If;
         If &patch.IsExist("severity") Then
            &severity = &patch.GetString("severity");
            Evaluate &severity
            When "Message"
               &item.MSG_SEVERITY = "M";
               Break;
            When "Warning"
               &item.MSG_SEVERITY = "W";
               Break;
            When "Error"
               &item.MSG_SEVERITY = "E";
               Break;
            When "Cancel"
               &item.MSG_SEVERITY = "C";
               Break;
            When-Other
               throw CreateException(0, 0, "Invalid message severity");
            End-Evaluate;
         End-If;
      End-If;
   End-If;
   &after = %This.Snapshot(&ci);
   If Not &dryRun Then
      If Not &ci.Save() Then
         throw CreateException(0, 0, "CI Save failed: " | %This.Errors(&session));
      End-If;
      &ci.Cancel();
      &ci.MESSAGE_SET_NBR = &set;
      If Not &ci.Get() Then
         throw CreateException(0, 0, "Saved Catalog could not be read back");
      End-If;
      &after = %This.Snapshot(&ci);
   Else
      &ci.Cancel();
   End-If;
   &result = CreateJsonObject();
   &result.AddProperty("dryRun", &dryRun);
   &result.AddProperty("messageSet", &set);
   &result.AddProperty("messageNumber", &messageNumber);
   &result.AddJsonObject("before", &before);
   &result.AddJsonObject("after", &after);
   Return &result;
end-method;

class MappingUtil
   method MappingUtil();

   method GetFieldTypeName(&p_code As integer, &p_format As integer) Returns string;
   method GetDbTypeName(&p_value As string) Returns string;
   method GetDbTypeCode(&p_value As string) Returns integer;
   method DecodePnlType(&p_pnlType As number) Returns string;
   method DecodePnlFieldType(&p_fieldType As number, &p_displayType As number) Returns string;
end-class;

method MappingUtil

end-method;

method GetFieldTypeName
   /+ &p_code as Integer, +/
   /+ &p_format as Integer +/
   /+ Returns String +/
   Local string &FieldTypeName;

   Evaluate &p_code
   When 0
      &FieldTypeName = "character";
      Break;
   When 1
      &FieldTypeName = "long character";
      Break;
   When 2
      &FieldTypeName = "number";
      Break;
   When 3
      &FieldTypeName = "signed number";
      Break;
   When 4
      &FieldTypeName = "date";
      Break;
   When 5
      &FieldTypeName = "time";
      Break;
   When 6
      &FieldTypeName = "datetime";
      Break;
   When 8
      If &p_format = 16 Then
         &FieldTypeName = "attachment";
      Else
         &FieldTypeName = "image";
      End-If;
   When 9
      &FieldTypeName = "imageReference";
   End-Evaluate;

   Return &FieldTypeName;
end-method;

method GetDbTypeName
   /+ &p_value as String +/
   /+ Returns String +/
   Local string &DbName;

   Evaluate &p_value
   When ""
      /* Default */
      &DbName = "default";
      Break;
   When "1"
      /* DB2 */
      &DbName = "DB2";
      Break;
   When "2"
      /* Oracle */
      &DbName = "ORACLE";
      Break;
   When "3"
      /* Informix */
      &DbName = "INFORMIX";
      Break;
   When "4"
      /* DB2Unix */
      &DbName = "DB2UNIX";
      Break;
   When "5"
      /* TimesTen */
      &DbName = "TIMESTEN";
      Break;
   When "6"
      /* Sybase */
      &DbName = "SYBASE";
      Break;
   When "7"
      /* Microsoft */
      &DbName = "MICROSOFT";
      Break;
   End-Evaluate;

   Return &DbName;
end-method;

method GetDbTypeCode
   /+ &p_value as String +/
   /+ Returns Integer +/
   Local integer &DbTypeCode;

   Evaluate Upper(LTrim(RTrim(&p_value)))
   When ""
   When "DEFAULT"
   When "32"
      /* Default */
      &DbTypeCode = 32;
      Break;
   When "1"
   When "DB2"
   When "49"
      /* DB2 */
      &DbTypeCode = 49;
      Break;
   When "2"
   When "ORACLE"
   When "50"
      /* Oracle */
      &DbTypeCode = 50;
      Break;
   When "3"
   When "INFORMIX"
   When "51"
      /* Informix */
      &DbTypeCode = 51;
      Break;
   When "4"
   When "DB2UNIX"
   When "52"
      /* DB2Unix */
      &DbTypeCode = 52;
      Break;
   When "5"
   When "TIMESTEN"
   When "53"
      /* TimesTen */
      &DbTypeCode = 53;
      Break;
   When "6"
   When "SYBASE"
   When "54"
      /* Sybase */
      &DbTypeCode = 54;
      Break;
   When "7"
   When "MICROSOFT"
   When "55"
      /* Microsoft */
      &DbTypeCode = 55;
      Break;
   When-Other
      throw CreateException(0, 0, "Unsupported dbType: " | &p_value);
   End-Evaluate;

   Return &DbTypeCode;
end-method;

method DecodePnlType
   /+ &p_pnlType as Number +/
   /+ Returns String +/
   Evaluate &p_pnlType
   When 0
      Return "standard";
   When 1
      Return "subPage";
   When 2
      Return "secondary";
   When-Other
      Return "unknown(" | &p_pnlType | ")";
   End-Evaluate;
end-method;

method DecodePnlFieldType
   /+ &p_fieldType as Number, +/
   /+ &p_displayType as Number +/
   /+ Returns String +/
   Evaluate &p_fieldType
   When 0
      Return "staticText";
   When 1
      Return "frame";
   When 2
      Return "groupBox";
   When 3
      Return "staticImage";
   When 4
      Return "editBox";
   When 5
      Return "dropDownList";
   When 6
      Return "longEditBox";
   When 7
      Return "checkBox";
   When 8
      Return "radioButton";
   When 9
      Return "image";
   When 10
      Return "scrollBar";
   When 11
      Return "subPage";
   When 12
      If &p_displayType = 1 Then
         Return "Hyperlink (peoplecode)";
      Else
         Return "pushButton (peoplecode)";
      End-If;
   When 13
      If &p_displayType = 1 Then
         Return "Hyperlink (scrollAction)";
      Else
         Return "pushButton (scrollAction)";
      End-If;
   When 14
      If &p_displayType = 1 Then
         Return "Hyperlink (toolbarAction)";
      Else
         Return "pushButton (toolbarAction)";
      End-If;
   When 15
      If &p_displayType = 1 Then
         Return "Hyperlink (External Link)";
      Else
         Return "pushButton (External Link)";
      End-If;
   When 16
      If &p_displayType = 1 Then
         Return "Hyperlink (Internal Link)";
      Else
         Return "pushButton (Internal Link)";
      End-If;
   When 17
      If &p_displayType = 1 Then
         Return "Hyperlink (Process)";
      Else
         Return "pushButton (Process)";
      End-If;
   When 18
      Return "secondaryPage";
   When 19
      Return "grid";
   When 20
      Return "tree";
   When 21
      If &p_displayType = 1 Then
         Return "Hyperlink (SecondaryPage)";
      Else
         Return "pushButton (SecondaryPage)";
      End-If;
   When 23
      Return "horizontalRule";
   When 24
      Return "tabSeparator";
   When 25
      Return "HTMLArea";
   When 26
      If &p_displayType = 1 Then
         Return "Hyperlink (PromptAction)";
      Else
         Return "pushButton (PromptAction)";
      End-If;
   When 27
      Return "scrollArea";
   When 29
      If &p_displayType = 1 Then
         Return "Hyperlink (PageAnchor)";
      Else
         Return "pushButton (PageAnchor)";
      End-If;
   When 30
      Return "chart";
   When 31
      If &p_displayType = 1 Then
         Return "Hyperlink (InstantMessaging)";
      Else
         Return "pushButton (InstantMessaging)";
      End-If;
   When 32
      Return "analyticGrid";
   When-Other
      Return "unknown(" | &p_fieldType | ")";
   End-Evaluate;
end-method;

import %metadata:Key;
import %metadata:PeopleCodeProgram:*;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;
import C_PORTAL_PKG:Util:CommonUtil;

class MenuCodeAdapter
   method MenuCodeAdapter();
   method Run(&req As JsonObject) Returns JsonObject;
end-class;

method MenuCodeAdapter
end-method;

method Run
   /+ &req as JsonObject +/
   /+ Returns JsonObject +/
   Local string &name = &req.GetString("name");
   Local string &bar = &req.GetString("BarName");
   Local string &item = &req.GetString("ItemName");
   Local string &action = &req.GetString("operationType");
   Local C_META_DATA_PKG:Utility:ObjectKeyResolver &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
   Local array of integer &menuIDs = &objectKeys.GetObjectIDs(6, CreateArray(&name, " ", " ", " "));
   Local object &menuKey = CreateObject("%metadata:Key", &menuIDs [1], &name);
   Local object &menuMgr = CreateObject("%metadata:MenuDefn:MenuDefn_Manager");
   If Not ObjectDoMethodArray(&menuMgr, "DefnExists", CreateArrayAny(&menuKey)) Then
      throw CreateException(0, 0, "Menu does not exist");
   End-If;
   Local object &menu = ObjectDoMethodArray(&menuMgr, "GetDefnToUpdate", CreateArrayAny(&menuKey));
   If ObjectGetProperty(&menu, "Menutype") <> 1 Then
      throw CreateException(0, 0, "ItemSelected PeopleCode requires a Pop-up menu");
   End-If;
   Local integer &i;
   Local boolean &found = False;
   Local object &mit;
   For &i = 1 To ObjectGetProperty(&menu, "Count_Mit")
      &mit = ObjectDoMethodArray(&menu, "Get_Mit", CreateArrayAny(&i));
      If ObjectGetProperty(&mit, "BarName") = &bar And
            ObjectGetProperty(&mit, "ItemName") = &item Then
         &found = True;
         Break;
      End-If;
   End-For;
   If Not &found Then
      throw CreateException(0, 0, "Exact menu bar/item does not exist");
   End-If;
   Local array of integer &ids = &objectKeys.GetObjectIDs(9, CreateArray(&name, &bar, &item, "ItemSelected"));
   Local %metadata:Key &key = create %metadata:Key(&ids [1], &name);
   &key.AddItem(&ids [2], &bar);
   &key.AddItem(&ids [3], &item);
   &key.AddItem(&ids [4], "ItemSelected");
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgr = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &prog;
   Local C_PORTAL_PKG:Util:CommonUtil &util = create C_PORTAL_PKG:Util:CommonUtil();
   Local boolean &exists = &mgr.DefnExists(&key);
   Local boolean &dry = False;
   Local string &before = "";
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   If &exists Then
      &prog = &mgr.GetDefnToUpdate(&key);
      &before = &prog.GetProgram();
   End-If;
   Local JsonObject &out = CreateJsonObject();
   &out.AddProperty("exists", &exists);
   &out.AddProperty("peoplecode", &util.EscapeJSON(&before));
   If &action = "viewCode" Then
      Return &out;
   End-If;
   If &req.IsExist("expectedCode") And
         &req.GetString("expectedCode") <> &before Then
      throw CreateException(0, 0, "Menu PeopleCode changed since snapshot");
   End-If;
   If &action = "deleteCode" Then
      If Not &exists Then
         throw CreateException(0, 0, "Menu PeopleCode does not exist");
      End-If;
      If Not &dry Then
         If Not &mgr.DeleteDefn(&key) Then
            throw CreateException(0, 0, "DeleteDefn failed for menu PeopleCode");
         End-If;
         If &mgr.DefnExists(&key) Then
            throw CreateException(0, 0, "Menu PeopleCode still exists after deletion");
         End-If;
      End-If;
      &out.AddProperty("deleted", ( Not &dry));
      &out.AddProperty("dryRun", &dry);
      Return &out;
   End-If;
   If &action <> "modifyCode" Then
      throw CreateException(0, 0, "Unknown menu PeopleCode action");
   End-If;
   Local string &code = &req.GetString("peoplecode");
   Local string &NonBlankCode = &code;
   &NonBlankCode = Substitute(&NonBlankCode, Char(9), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(10), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(11), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(12), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(13), "");
   If Len(LTrim(RTrim(&NonBlankCode))) = 0 Then
      throw CreateException(0, 0, "Empty PeopleCode is not deletion; use deleteCode");
   End-If;
   If Not &exists Then
      &prog = &mgr.CreateDefn();
      &prog.ObjectID#0# = &ids [1];
      &prog.ObjectValue#0# = &name;
      &prog.ObjectID#1# = &ids [2];
      &prog.ObjectValue#1# = &bar;
      &prog.ObjectID#2# = &ids [3];
      &prog.ObjectValue#2# = &item;
      &prog.ObjectID#3# = &ids [4];
      &prog.ObjectValue#3# = "ItemSelected";
   End-If;
   Local string &error;
   Local integer &start, &finish;
   If Not &prog.UpdateProgram(&code, &error, &start, &finish) Then
      throw CreateException(0, 0, "PeopleCode compile failed: " | &error | " positions " | &start | "," | &finish);
   End-If;
   If Not &dry Then
      If &exists Then
         If Not &prog.UpdateDefn() Then
            throw CreateException(0, 0, "PeopleCode UpdateDefn failed");
         End-If;
      Else
         If Not &prog.SaveNewDefn() Then
            throw CreateException(0, 0, "PeopleCode SaveNewDefn failed");
         End-If;
      End-If;
      &prog = &mgr.GetDefn(&key);
   End-If;
   &out.AddProperty("afterCode", &util.EscapeJSON(&prog.GetProgram()));
   &out.AddProperty("dryRun", &dry);
   Return &out;
end-method;

import %metadata:Key;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;
import C_PORTAL_PKG:Util:CommonUtil;

class NativeAdapter
   method NativeAdapter();
   method Run(&req As JsonObject) Returns JsonObject;
private
   method ReadFields(&obj As object, &fields As array of string) Returns JsonObject;
   method PatchFields(&obj As object, &patch As JsonObject, &fields As array of string, &keys As array of string);
   method Snapshot(&obj As object, &fields As array of string, &collections As array of string, &childFields As array of string) Returns JsonObject;
   method CheckPortalContent(&obj As object, &mgr As object, &ids As array of integer);
   method SyncServiceMembership(&operationName As string, &oldService As string, &newService As string);
   method ChildKey(&obj As object, &row As JsonObject, &keyNames As string) Returns string;
end-class;

method NativeAdapter
end-method;

method ReadFields
   /+ &obj as Object, +/
   /+ &fields as Array of String +/
   /+ Returns JsonObject +/
   Local JsonObject &out = CreateJsonObject();
   Local integer &i;
   Local string &field, &name;
   Local any &value;
   Local C_PORTAL_PKG:Util:CommonUtil &jsonUtil = create C_PORTAL_PKG:Util:CommonUtil();
   For &i = 1 To &fields.Len
      &field = &fields [&i];
      &name = Substitute(Substitute(Substitute(Substitute(&field, "#", ""), "@", ""), "!", ""), "~", "");
      If &field = "Values~" Then
         Local JsonArray &values = CreateJsonArray();
         Local integer &vi;
         Local object &valueObj;
         For &vi = 1 To ObjectGetProperty(&obj, "Count_AttrValue")
            &valueObj = ObjectDoMethodArray(&obj, "Get_AttrValue", CreateArrayAny(&vi));
            &values.AddElement(&jsonUtil.EscapeJSON(String(ObjectGetProperty(&valueObj, "AttrValue"))));
         End-For;
         &out.AddJsonArray("Values", &values);
         Continue;
      End-If;
      &value = ObjectGetProperty(&obj, &name);
      If Find("@", &field) > 0 Then
         &out.AddProperty(&name, DateTimeToLocalizedString(&value, "yyyy-MM-dd"));
      Else
         If Find("#", &field) > 0 Or
               Find("!", &field) > 0 Then
            &out.AddProperty(&name, &value);
         Else
            &out.AddProperty(&name, &jsonUtil.EscapeJSON(String(&value)));
         End-If;
      End-If;
   End-For;
   Return &out;
end-method;

method PatchFields
   /+ &obj as Object, +/
   /+ &patch as JsonObject, +/
   /+ &fields as Array of String, +/
   /+ &keys as Array of String +/
   Local integer &i, &j, &at;
   Local string &name, &field;
   Local any &value;
   For &i = 1 To &patch.ChildCount
      &name = &patch.GetPropertyNameAt(&i);
      &at = 0;
      For &j = 1 To &fields.Len
         If Substitute(Substitute(Substitute(Substitute(&fields [&j], "#", ""), "@", ""), "!", ""), "~", "") = &name Or
               (&fields [&j] = "Values~" And
                  &name = "Values") Then
            &at = &j;
         End-If;
      End-For;
      If &at = 0 Then
         throw CreateException(0, 0, "Unknown property: " | &name | " allowed " | &fields.Join(","));
      End-If;
      &field = &fields [&at];
      If &field = "Values~" Then
         Local JsonArray &newValues = &patch.GetJsonArray("Values");
         If &newValues.Size > 1 Then
            throw CreateException(0, 0, "Portal attributes require one string value for PIA compatibility; separate logical values with semicolons");
         End-If;
         Local integer &vi, &vc;
         Local object &valueObj;
         &vc = ObjectGetProperty(&obj, "Count_AttrValue");
         For &vi = &vc To 1 Step - 1
            ObjectDoMethodArray(&obj, "Delete_AttrValue", CreateArrayAny(&vi));
         End-For;
         &valueObj = ObjectDoMethodArray(&obj, "Append_AttrValue", CreateArrayAny(0));
         ObjectSetProperty(&valueObj, "AttrSeqNbr", 1);
         If &newValues.Size = 0 Then
            ObjectSetProperty(&valueObj, "AttrValue", "");
         Else
            ObjectSetProperty(&valueObj, "AttrValue", &newValues.GetString(1));
         End-If;
         Continue;
      End-If;
      If Find("#", &field) > 0 Then
         &value = &patch.GetNumber(&name);
         If &value <> Int(&value) Then
            throw CreateException(0, 0, "Integer property required: " | &name);
         End-If;
      Else
         If Find("@", &field) > 0 Then
            &value = Date(&patch.GetString(&name));
         Else
            If Find("!", &field) > 0 Then
               &value = &patch.GetBoolean(&name);
            Else
               &value = &patch.GetString(&name);
            End-If;
         End-If;
      End-If;
      If &keys.Find(&name) > 0 Then
         If String(ObjectGetProperty(&obj, &name)) <> String(&value) Then
            throw CreateException(0, 0, "Key cannot be changed: " | &name);
         End-If;
      Else
         ObjectSetProperty(&obj, &name, &value);
      End-If;
   End-For;
end-method;

method Snapshot
   /+ &obj as Object, +/
   /+ &fields as Array of String, +/
   /+ &collections as Array of String, +/
   /+ &childFields as Array of String +/
   /+ Returns JsonObject +/
   Local JsonObject &out = %This.ReadFields(&obj, &fields);
   Local JsonArray &rows;
   Local object &child;
   Local array of string &names;
   Local integer &i, &j, &count;
   For &i = 1 To &collections.Len
      &rows = CreateJsonArray();
      &count = ObjectGetProperty(&obj, "Count_" | &collections [&i]);
      &names = Split(&childFields [&i], " ");
      For &j = 1 To &count
         &child = ObjectDoMethodArray(&obj, "Get_" | &collections [&i], CreateArrayAny(&j));
         &rows.AddJsonObjectElement("", %This.ReadFields(&child, &names));
      End-For;
      &out.AddJsonArray(&collections [&i], &rows);
   End-For;
   Return &out;
end-method;

method ChildKey
   /+ &obj as Object, +/
   /+ &row as JsonObject, +/
   /+ &keyNames as String +/
   /+ Returns String +/
   Local array of string &parts = Split(&keyNames, "|");
   Local string &out = "";
   Local string &value;
   Local integer &i;
   For &i = 1 To &parts.Len
      If &row = Null Then
         &value = String(ObjectGetProperty(&obj, &parts [&i]));
      Else
         &value = &row.GetAsString(&parts [&i]);
      End-If;
      If None(&value) Then
         throw CreateException(0, 0, "Child key is required: " | &parts [&i]);
      End-If;
      &out = &out | Len(&value) | ":" | &value;
   End-For;
   Return &out;
end-method;

method CheckPortalContent
   /+ &obj as Object, +/
   /+ &mgr as Object, +/
   /+ &ids as Array of Integer +/
   Local integer &attributeIndex;
   Local object &attribute;
   For &attributeIndex = 1 To ObjectGetProperty(&obj, "Count_Attr")
      &attribute = ObjectDoMethodArray(&obj, "Get_Attr", CreateArrayAny(&attributeIndex));
      If ObjectGetProperty(&attribute, "Count_AttrValue") <> 1 Then
         throw CreateException(0, 0, "Portal attribute " | String(ObjectGetProperty(&attribute, "AttrName")) | " on " | String(ObjectGetProperty(&obj, "ObjName")) | " must have exactly one native value row for PIA compatibility. Keep one string value; separate logical values with semicolons.");
      End-If;
   End-For;
   If ObjectGetProperty(&obj, "IsLink") Then
      Local object &contentKey = CreateObject("%metadata:Key", &ids [1], String(ObjectGetProperty(&obj, "LinksPortalName")));
      ObjectDoMethod(&contentKey, "AddItem", &ids [2], "C");
      ObjectDoMethod(&contentKey, "AddItem", &ids [3], String(ObjectGetProperty(&obj, "LinksObjectName")));
      If Not ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&contentKey)) Then
         throw CreateException(0, 0, "Link target does not exist");
      End-If;
      Local object &content = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&contentKey));
      If ObjectGetProperty(&content, "IsLink") Then
         throw CreateException(0, 0, "A link cannot target another link");
      End-If;
      %This.CheckPortalContent(&content, &mgr, &ids);
   End-If;
end-method;

method SyncServiceMembership
   /+ &operationName as String, +/
   /+ &oldService as String, +/
   /+ &newService as String +/
   Local object &serviceManager = CreateObject("%metadata:ServiceDefn:ServiceDefn_Manager");
   Local array of string &serviceNames = CreateArray(&newService, &oldService);
   Local object &serviceKey, &service, &member;
   Local integer &si, &mi, &memberCount, &memberIndex;
   Local boolean &changed;
   For &si = 1 To &serviceNames.Len
      If None(&serviceNames [&si]) Or
            (&si = 2 And
               &oldService = &newService) Then
         Continue;
      End-If;
      &serviceKey = create %metadata:Key(key:Class_ServiceName, &serviceNames [&si]);
      If Not ObjectDoMethodArray(&serviceManager, "DefnExists", CreateArrayAny(&serviceKey)) Then
         If &si = 1 Then
            throw CreateException(0, 0, "Parent service does not exist");
         Else
            Continue;
         End-If;
      End-If;
      &service = ObjectDoMethodArray(&serviceManager, "GetDefnToUpdate", CreateArrayAny(&serviceKey));
      &memberCount = ObjectGetProperty(&service, "Count_Serviceopr");
      &memberIndex = 0;
      &changed = False;
      For &mi = 1 To &memberCount
         &member = ObjectDoMethodArray(&service, "Get_Serviceopr", CreateArrayAny(&mi));
         If ObjectGetProperty(&member, "Operationname") = &operationName Then
            &memberIndex = &mi;
            Break;
         End-If;
      End-For;
      If &si = 1 And
            &memberIndex = 0 Then
         &member = ObjectDoMethodArray(&service, "Append_Serviceopr", CreateArrayAny(&memberCount));
         ObjectSetProperty(&member, "Operationname", &operationName);
         &changed = True;
      Else
         If &si = 2 And
               &memberIndex > 0 Then
            If Not ObjectDoMethodArray(&service, "Delete_Serviceopr", CreateArrayAny(&memberIndex)) Then
               throw CreateException(0, 0, "Service membership deletion failed");
            End-If;
            &changed = True;
         End-If;
      End-If;
      If &changed And
            Not ObjectDoMethodArray(&service, "UpdateDefn", CreateArrayAny()) Then
         throw CreateException(0, 0, "Service membership save failed");
      End-If;
      &service = ObjectDoMethodArray(&serviceManager, "GetDefnToUpdate", CreateArrayAny(&serviceKey));
      &memberIndex = 0;
      For &mi = 1 To ObjectGetProperty(&service, "Count_Serviceopr")
         &member = ObjectDoMethodArray(&service, "Get_Serviceopr", CreateArrayAny(&mi));
         If ObjectGetProperty(&member, "Operationname") = &operationName Then
            &memberIndex = &mi;
            Break;
         End-If;
      End-For;
      If (&si = 1 And
            &memberIndex = 0) Or
            (&si = 2 And
               &memberIndex > 0) Then
         throw CreateException(0, 0, "Service membership readback failed");
      End-If;
   End-For;
end-method;

method Run
   /+ &req as JsonObject +/
   /+ Returns JsonObject +/
   Local string &kind = &req.GetString("kind");
   If &kind = "permission" Then
      Local object &security = CreateObject("C_META_DATA_PKG:Utility:OperationSecurityAdapter");
      Return ObjectDoMethodArray(&security, "Run", CreateArrayAny(&req));
   End-If;
   If &kind = "catalog" Then
      Local object &catalog = CreateObject("C_META_DATA_PKG:Utility:CatalogAdapter");
      Return ObjectDoMethodArray(&catalog, "Run", CreateArrayAny(&req));
   End-If;
   Local string &action = &req.GetString("operationType");
   Local string &name = &req.GetString("name");
   Local string &className, &collection, &childKey, &childName, &keyProp, &saveMethod;
   Local object &mgr, &defn, &child;
   Local object &key;
   Local JsonObject &before, &after, &result, &patch, &row, &childPatches;
   Local JsonArray &rows;
   Local array of string &fields, &collections, &childFields, &childKeys, &keys, &names;
   Local C_META_DATA_PKG:Utility:ObjectKeyResolver &objectKeys;
   Local integer &i, &j, &n, &count, &found;
   Local boolean &exists, &ok;
   Local boolean &dryRun = False;
   If &kind = "menu" And
         (&action = "viewCode" Or
            &action = "modifyCode" Or
            &action = "deleteCode") Then
      Local object &menuCode = CreateObject("C_META_DATA_PKG:Utility:MenuCodeAdapter");
      Return ObjectDoMethodArray(&menuCode, "Run", CreateArrayAny(&req));
   End-If;
   If None(&name) Or
         Len(&name) > 30 Then
      throw CreateException(0, 0, "Definition name must have 1-30 characters");
   End-If;
   &collections = CreateArrayRept("", 0);
   &childFields = CreateArrayRept("", 0);
   &childKeys = CreateArrayRept("", 0);
   &keys = CreateArrayRept("", 0);
   Evaluate &kind
   When "service"
      &className = "ServiceDefn";
      &keyProp = "Ib_servicename";
      &fields = CreateArray("Ib_servicename", "Ib_namespace", "Ib_aliasname", "RestService#", "Psftservice_flag", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId", "Ptibappsrvgrp", "Ptibapplname", "OpenAPI#");
      &key = create %metadata:Key(key:Class_ServiceName, &name);
      &collections.Push("Serviceopr");
      &childFields.Push("Operationname");
      &childKeys.Push("Operationname");
      Break;
   When "operation"
      &className = "OperationDefn";
      &keyProp = "Operationname";
      &fields = CreateArray("Operationname", "Servicename", "Defaultversion", "Rtngtype", "Userpwdreq", "RequestStatus", "ActiveDataGuard#", "ThinkTime#", "ConNav#", "Restmethod", "RestService#", "RestBaseurl", "RestOverride#", "Ib_aliasname", "Messagename", "Messageversion", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &key = create %metadata:Key(key:Class_OperationName, &name);
      &collections.Push("Operationuritemplate");
      &childFields.Push("URISeq# URITemplate RootResource Ibtransactionid");
      &childKeys.Push("URISeq");
      &collections.Push("Operationhandler");
      &childFields.Push("Handlername Handlerid Active_flag Seqnumber#");
      &childKeys.Push("Handlername");
      &collections.Push("Operationversion");
      &childFields.Push("Versionname");
      &childKeys.Push("Versionname");
      Break;
   When "version"
      &className = "OperationVersionDefn";
      &keyProp = "Operationname";
      &fields = CreateArray("Operationname", "Versionname", "Active_flag", "Validation", "Nr_flag", "Syncnonblock", "Export_flag", "Multi_queue", "Clientimplement", "ExcludeToken", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &keys.Push("Versionname");
      &key = create %metadata:Key(key:Class_OperationName, &name, key:Class_VersionName, &req.GetString("Versionname"));
      &collections.Push("Oprverdfnparm");
      &childFields.Push("Parametername Messagename Messageversion HTTPStatusCode# ContentType Queuename Xfrmname Outxfrmname");
      &childKeys.Push("Parametername");
      &collections.Push("Oprvgenrtgparm");
      &childFields.Push("Parametername Routingdefnname");
      &childKeys.Push("Parametername");
      Break;
   When "handler"
      &className = "OperationHandlerDefn";
      &keyProp = "Operationname";
      &fields = CreateArray("Operationname", "Handlername", "Handlerid", "Handlertype", "Active_flag", "Seqnumber#", "Rollback_flag", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &keys.Push("Handlername");
      &key = create %metadata:Key(key:Class_OperationName, &name, key:Class_HandlerName, &req.GetString("Handlername"));
      &collections.Push("Operationac");
      &childFields.Push("Packageid Packageroot Qualifypath Classname Methodname");
      &childKeys.Push("Classname");
      Break;
   When "routing"
      &className = "RoutingDefn";
      &keyProp = "Routingdefnname";
      &fields = CreateArray("Routingdefnname", "Effdt@", "Eff_status", "Sendernodename", "Receivernodename", "Operationname", "Operationversion", "Rtngtype", "Restmethod", "LocalIndication#", "Generated", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &keys.Push("Effdt");
      &key = create %metadata:Key(key:Class_RoutingDefnName, &name, key:Class_EffDt, String(Date(&req.GetString("Effdt"))));
      &collections.Push("Ibrtngsubdefn");
      &childFields.Push("Seqnum# Direction Rtngtype Sendernodename Receivernodename Aliasname");
      &childKeys.Push("Seqnum");
      &collections.Push("Rtngdfnparm");
      &childFields.Push("Parametername Sendernodename Receivernodename Aliasname Operationversion");
      &childKeys.Push("Parametername");
      Break;
   When "menu"
      &className = "MenuDefn";
      &keyProp = "Menuname";
      &fields = CreateArray("Menuname", "Menutype#", "MenuLabel", "MenuGroup", "MenuOrder#", "GroupOrder#", "Installed!", "GroupSep!", "MenuSep!", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local array of integer &menuIDs = &objectKeys.GetObjectIDs(6, CreateArray(&name, " ", " ", " "));
      &key = CreateObject("%metadata:Key", &menuIDs [1], &name);
      &collections.Push("Mit");
      &childFields.Push("BarName BarLabel ItemName ItemLabel ItemType# PnlGrpName Market ItemNum# AllowedActions# DisplayOnly! SearchRecName AddSearchRecName SearchPnlName");
      &childKeys.Push("BarName|ItemName");
      Break;
   When "portal"
      &className = "PortalRegStructDefn";
      &keyProp = "ObjName";
      &fields = CreateArray("PortalName", "RefType", "ObjName", "PrntObjName", "SeqNum#", "LabelName", "CntPrvName", "CrefUsageType", "CrefTemplateType", "CrefStorageType", "CrefURLType", "Descr", "Product", "EffectiveDate", "CreationDate", "ExpirationDate", "TemplateName", "StorageName", "IsPublic#", "LinksPortalName", "LinksObjectName", "URISeg1", "URISeg2", "URISeg3", "URISeg4", "Fluid!", "SmallFFOpt!", "IsVisible!", "URLLogical", "IsLink!");
      Local string &portalName = &req.GetString("PortalName");
      Local string &refType = &req.GetString("RefType");
      If &refType <> "F" And
            &refType <> "C" Then
         throw CreateException(0, 0, "RefType must be F or C; links use C with IsLink true");
      End-If;
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local array of integer &portalIDs = &objectKeys.GetObjectIDs(55, CreateArray(&portalName, &refType, &name, " "));
      &key = CreateObject("%metadata:Key", &portalIDs [1], &portalName);
      ObjectDoMethod(&key, "AddItem", &portalIDs [2], &refType);
      ObjectDoMethod(&key, "AddItem", &portalIDs [3], &name);
      &keys.Push("PortalName");
      &keys.Push("RefType");
      &keys.Push("IsLink");
      &collections.Push("Attr");
      &childFields.Push("AttrName AttrNameDsply Values~");
      &childKeys.Push("AttrName");
      &collections.Push("Permission");
      &childFields.Push("PermType PermName IsCascade!");
      &childKeys.Push("PermType|PermName");
      &collections.Push("InheritPermission");
      &childFields.Push("PermType PermName IsCascade!");
      &childKeys.Push("PermType|PermName");
      &collections.Push("ChildFldr");
      &childFields.Push("ObjName SeqNum#");
      &childKeys.Push("ObjName");
      &collections.Push("ChildCref");
      &childFields.Push("ObjName SeqNum#");
      &childKeys.Push("ObjName");
      Break;
   When-Other
      throw CreateException(0, 0, "Unsupported metadata kind");
   End-Evaluate;
   &keys.Push(&keyProp);
   If &kind = "version" Or
         &kind = "handler" Then
      Local string &secondaryKey = &req.GetString(&keys [1]);
      If None(&secondaryKey) Or
            Len(&secondaryKey) > 30 Then
         throw CreateException(0, 0, "Version/handler key must have 1-30 characters");
      End-If;
   End-If;
   &mgr = CreateObject("%metadata:" | &className | ":" | &className | "_Manager");
   &exists = ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&key));
   If &action = "exists" Then
      &result = CreateJsonObject();
      &result.AddProperty("exists", &exists);
      Return &result;
   End-If;
   If &action = "create" Then
      If &exists Then
         throw CreateException(0, 0, "Definition already exists");
      End-If;
      &defn = ObjectDoMethodArray(&mgr, "CreateDefn", CreateArrayAny());
      ObjectSetProperty(&defn, &keyProp, &name);
      If &kind = "portal" Then
         ObjectSetProperty(&defn, "PortalName", &req.GetString("PortalName"));
         ObjectSetProperty(&defn, "RefType", &req.GetString("RefType"));
         ObjectSetProperty(&defn, "IsVisible", True);
         ObjectSetProperty(&defn, "EffectiveDate", "1900-01-01");
         ObjectSetProperty(&defn, "CreationDate", DateTimeToLocalizedString(%Date, "yyyy-MM-dd"));
         If &req.GetString("RefType") = "C" Then
            ObjectSetProperty(&defn, "CrefUsageType", "TARG");
            ObjectSetProperty(&defn, "CrefStorageType", "RMTE");
            ObjectSetProperty(&defn, "CrefTemplateType", "HTML");
         End-If;
         If &req.IsExist("properties") Then
            &patch = &req.GetJsonObject("properties");
            If &patch.IsExist("IsLink") Then
               ObjectSetProperty(&defn, "IsLink", &patch.GetBoolean("IsLink"));
            End-If;
         End-If;
      End-If;
      If &kind = "version" Or
            &kind = "handler" Then
         ObjectSetProperty(&defn, &keys [1], &req.GetString(&keys [1]));
      End-If;
      If &kind = "routing" Then
         ObjectSetProperty(&defn, "Effdt", Date(&req.GetString("Effdt")));
      End-If;
   Else
      If Not &exists Then
         throw CreateException(0, 0, "Definition does not exist");
      End-If;
      &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&key));
   End-If;
   &before = %This.Snapshot(&defn, &fields, &collections, &childFields);
   If &kind = "portal" And
         &action <> "create" Then
      If ObjectGetProperty(&defn, "IsLink") Then
         try
            %This.CheckPortalContent(&defn, &mgr, &portalIDs);
         catch Exception &linkPreflightEx
            If &action <> "validate" Then
               throw &linkPreflightEx;
            End-If;
            Local JsonObject &invalidLink = CreateJsonObject();
            Local C_PORTAL_PKG:Util:CommonUtil &linkPreflightUtil = create C_PORTAL_PKG:Util:CommonUtil();
            &invalidLink.AddProperty("valid", False);
            &invalidLink.AddProperty("error", &linkPreflightUtil.EscapeJSON(&linkPreflightEx.ToString()));
            Return &invalidLink;
         end-try;
      End-If;
      Local ApiObject &checkRegistry = %Session.GetPortalRegistry();
      &checkRegistry.Open(&req.GetString("PortalName"));
      Local ApiObject &checkPortalObj;
      If &req.GetString("RefType") = "F" Then
         &checkPortalObj = &checkRegistry.FindFolderByName(&name);
      Else
         If ObjectGetProperty(&defn, "IsLink") Then
            &checkPortalObj = &checkRegistry.FindCRefLinkByName(&name);
         Else
            &checkPortalObj = &checkRegistry.FindCRefByName(&name);
         End-If;
      End-If;
      If &checkPortalObj = Null Then
         throw CreateException(0, 0, "Portal object could not be loaded");
      End-If;
      If Not &checkPortalObj.Authorized Then
         throw CreateException(0, 0, "User is not authorized for portal object");
      End-If;
      If &action = "validate" Then
         Local JsonObject &validation = CreateJsonObject();
         Local JsonArray &runtimeRows = CreateJsonArray();
         Local ApiObject &runtimeCref, &runtimeCollection, &runtimeLink;
         Local boolean &runtimeValid = True;
         try
            %This.CheckPortalContent(&defn, &mgr, &portalIDs);
            If &req.GetString("RefType") = "F" Then
               Local integer &preIndex;
               Local object &preChild, &preKey, &preDefn;
               For &preIndex = 1 To ObjectGetProperty(&defn, "Count_ChildCref")
                  &preChild = ObjectDoMethodArray(&defn, "Get_ChildCref", CreateArrayAny(&preIndex));
                  &preKey = CreateObject("%metadata:Key", &portalIDs [1], &req.GetString("PortalName"));
                  ObjectDoMethod(&preKey, "AddItem", &portalIDs [2], "C");
                  ObjectDoMethod(&preKey, "AddItem", &portalIDs [3], String(ObjectGetProperty(&preChild, "ObjName")));
                  &preDefn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&preKey));
                  %This.CheckPortalContent(&preDefn, &mgr, &portalIDs);
               End-For;
            End-If;
         catch Exception &preEx
            Local C_PORTAL_PKG:Util:CommonUtil &preUtil = create C_PORTAL_PKG:Util:CommonUtil();
            &validation.AddProperty("valid", False);
            &validation.AddProperty("error", &preUtil.EscapeJSON(&preEx.ToString()));
            &checkRegistry.Close();
            Return &validation;
         end-try;
         If &req.GetString("RefType") = "F" Then
            &runtimeCollection = &checkPortalObj.ContentRefs;
            &runtimeCref = &runtimeCollection.First();
         Else
            &runtimeCref = &checkRegistry.FindCRefByName(&name);
         End-If;
         Local C_PORTAL_PKG:Util:CommonUtil &runtimeUtil = create C_PORTAL_PKG:Util:CommonUtil();
         While &runtimeCref <> Null
            Local JsonObject &runtimeRow = CreateJsonObject();
            &runtimeRow.AddProperty("name", &runtimeCref.Name);
            try
               &runtimeRow.AddProperty("label", &runtimeUtil.EscapeJSON(&runtimeCref.Label));
               &runtimeRow.AddProperty("node", &runtimeUtil.EscapeJSON(String(&runtimeCref.NodeName)));
               If &runtimeCref.IsLink Then
                  &runtimeLink = &checkRegistry.FindCRefLinkByName(&runtimeCref.Name);
                  If &runtimeLink = Null Then
                     throw CreateException(0, 0, "Content reference link could not be loaded");
                  End-If;
               End-If;
               &runtimeRow.AddProperty("qualifiedURL", &runtimeUtil.EscapeJSON(String(&runtimeCref.QualifiedURL)));
               If &runtimeCref.IsLink Then
                  &runtimeRow.AddProperty("linkCount", &runtimeLink.Links.Count);
               Else
                  &runtimeRow.AddProperty("linkCount", &runtimeCref.Links.Count);
               End-If;
               &runtimeRow.AddProperty("valid", True);
            catch Exception &runtimeEx
               &runtimeValid = False;
               &runtimeRow.AddProperty("valid", False);
               &runtimeRow.AddProperty("error", &runtimeUtil.EscapeJSON(&runtimeEx.ToString()));
            end-try;
            &runtimeRows.AddJsonObjectElement("", &runtimeRow);
            If &req.GetString("RefType") = "F" Then
               &runtimeCref = &runtimeCollection.Next();
            Else
               Break;
            End-If;
         End-While;
         &checkRegistry.Close();
         &validation.AddProperty("valid", &runtimeValid);
         &validation.AddJsonArray("content", &runtimeRows);
         Return &validation;
      End-If;
      &checkRegistry.Close();
   End-If;
   If &action = "view" Or
         &action = "struct" Then
      Local C_PORTAL_PKG:Util:CommonUtil &stateUtil = create C_PORTAL_PKG:Util:CommonUtil();
      &before.AddProperty("stateToken", &stateUtil.EscapeJSON(&before.ToString()));
      Return &before;
   End-If;
   If &kind = "service" Then
      If &action = "create" Then
         ObjectSetProperty(&defn, "RestService", 2);
      Else
         If ObjectGetProperty(&defn, "RestService") <> 2 Then
            throw CreateException(0, 0, "Only REST Provider services can be modified in this release");
         End-If;
      End-If;
   End-If;
   If &kind = "operation" And
         &action <> "create" Then
      If ObjectGetProperty(&defn, "RestService") <> 2 Or
            ObjectGetProperty(&defn, "Rtngtype") <> "S" Then
         throw CreateException(0, 0, "Only synchronous REST Provider operations can be modified");
      End-If;
   End-If;
   If &kind = "version" Or
         &kind = "handler" Or
         &kind = "routing" Then
      Local string &ownerOp = &name;
      If &kind = "routing" Then
         If &action = "create" Then
            &ownerOp = &req.GetJsonObject("properties").GetString("Operationname");
         Else
            &ownerOp = ObjectGetProperty(&defn, "Operationname");
         End-If;
      End-If;
      Local object &ownerManager = CreateObject("%metadata:OperationDefn:OperationDefn_Manager");
      Local object &ownerKey = create %metadata:Key(key:Class_OperationName, &ownerOp);
      If ObjectDoMethodArray(&ownerManager, "DefnExists", CreateArrayAny(&ownerKey)) Then
         Local object &ownerDefn = ObjectDoMethodArray(&ownerManager, "GetDefnToUpdate", CreateArrayAny(&ownerKey));
         If ObjectGetProperty(&ownerDefn, "RestService") <> 2 Or
               ObjectGetProperty(&ownerDefn, "Rtngtype") <> "S" Then
            throw CreateException(0, 0, "Parent operation must be synchronous REST Provider");
         End-If;
      Else
         If Not (&req.IsExist("dryRun") And
               &req.GetBoolean("dryRun")) Then
            throw CreateException(0, 0, "Parent operation does not exist");
         End-If;
      End-If;
   End-If;
   If &kind = "portal" And
         &name = "PORTAL_ROOT_OBJECT" Then
      throw CreateException(0, 0, "Portal root is read-only");
   End-If;
   If &req.IsExist("expectedState") And
         &req.GetString("expectedState") <> &before.ToString() Then
      throw CreateException(0, 0, "Definition changed since snapshot; read again");
   End-If;
   If &req.IsExist("dryRun") Then
      &dryRun = &req.GetBoolean("dryRun");
   End-If;
   If &action = "delete" Then
      If &kind <> "operation" And
            &kind <> "version" And
            &kind <> "handler" And
            &kind <> "routing" And
            &kind <> "portal" Then
         throw CreateException(0, 0, "Whole-definition deletion is not enabled for this kind");
      End-If;
      If &kind = "portal" And
            &req.GetString("RefType") <> "C" Then
         throw CreateException(0, 0, "Portal folder deletion is disabled, including empty folders");
      End-If;
      If &kind = "portal" And
            Not ObjectGetProperty(&defn, "IsLink") Then
         Local Rowset &referencingLinks = CreateRowset(Record.PSPRSMDEFN);
         If &referencingLinks.Fill("WHERE PORTAL_LINKOBJNAME = :1 AND PORTAL_LINK_PORTAL = :2", &name, &req.GetString("PortalName")) > 0 Then
            throw CreateException(0, 0, "CREF has referencing links; delete those exact links first");
         End-If;
      End-If;
      If Not &dryRun Then
         &ok = ObjectDoMethodArray(&mgr, "DeleteDefn", CreateArrayAny(&key));
         If Not &ok Then
            throw CreateException(0, 0, "Native DeleteDefn failed");
         End-If;
         If ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&key)) Then
            throw CreateException(0, 0, "Definition still exists after native deletion");
         End-If;
         If &kind = "operation" Then
            %This.SyncServiceMembership(&name, &before.GetString("Servicename"), "");
            Local object &cleanup = CreateObject("C_META_DATA_PKG:Utility:OperationSecurityAdapter");
            ObjectDoMethodArray(&cleanup, "Cleanup", CreateArrayAny(&name));
         End-If;
      End-If;
      &result = CreateJsonObject();
      &result.AddProperty("deleted", ( Not &dryRun));
      &result.AddProperty("dryRun", &dryRun);
      &result.AddJsonObject("before", &before);
      Return &result;
   End-If;
   If &action <> "create" And
         &action <> "modify" And
         &action <> "deleteChild" Then
      throw CreateException(0, 0, "Unsupported operationType");
   End-If;
   If &req.IsExist("properties") Then
      &patch = &req.GetJsonObject("properties");
      %This.PatchFields(&defn, &patch, &fields, &keys);
   End-If;
   If &req.IsExist("collections") Then
      &childPatches = &req.GetJsonObject("collections");
      For &i = 1 To &childPatches.ChildCount
         &collection = &childPatches.GetPropertyNameAt(&i);
         If (&kind = "service" And
               &collection = "Serviceopr") Or
               (&kind = "operation" And
                  (&collection = "Operationhandler" Or
                     &collection = "Operationversion")) Then
            throw CreateException(0, 0, "Derived definition references are read-only; create/modify the child definition instead");
         End-If;
         If &kind = "portal" And
               &collection <> "Attr" And
               &collection <> "Permission" Then
            throw CreateException(0, 0, "Portal navigation/inherited collections are read-only");
         End-If;
         &n = &collections.Find(&collection);
         If &n = 0 Then
            throw CreateException(0, 0, "Unsupported collection: " | &collection);
         End-If;
         &rows = &childPatches.GetJsonArray(&collection);
         &names = Split(&childFields [&n], " ");
         &childKey = &childKeys [&n];
         Local array of string &patchKeys = CreateArrayRept("", 0);
         For &j = 1 To &rows.Size
            &row = &rows.GetJsonObject(&j);
            If &kind = "menu" And
                  (&row.IsExist("AllowedActions") Or
                     &row.IsExist("AddSearchRecName")) Then
               throw CreateException(0, 0, "AllowedActions and AddSearchRecName are read-only in the native menu API");
            End-If;
            &childName = %This.ChildKey( Null, &row, &childKey);
            If &patchKeys.Find(&childName) > 0 Then
               throw CreateException(0, 0, "Duplicate child key in patch: " | &childName);
            End-If;
            &patchKeys.Push(&childName);
            &count = ObjectGetProperty(&defn, "Count_" | &collection);
            &found = 0;
            Local integer &k;
            For &k = 1 To &count
               &child = ObjectDoMethodArray(&defn, "Get_" | &collection, CreateArrayAny(&k));
               If %This.ChildKey(&child, Null, &childKey) = &childName Then
                  &found = &k;
                  Break;
               End-If;
            End-For;
            If &action = "deleteChild" Then
               If &found = 0 Then
                  throw CreateException(0, 0, "Child does not exist");
               End-If;
               &ok = ObjectDoMethodArray(&defn, "Delete_" | &collection, CreateArrayAny(&found));
               If Not &ok Then
                  throw CreateException(0, 0, "Native child deletion failed");
               End-If;
            Else
               If &found = 0 Then
                  &child = ObjectDoMethodArray(&defn, "Append_" | &collection, CreateArrayAny(&count));
               End-If;
               %This.PatchFields(&child, &row, &names, CreateArrayRept("", 0));
               If &kind = "menu" And
                     &found > 0 Then
                  ObjectSetProperty(&child, "Status", 1);
               End-If;
            End-If;
         End-For;
      End-For;
   End-If;
   &after = %This.Snapshot(&defn, &fields, &collections, &childFields);
   If &kind = "service" Or
         &kind = "operation" Then
      If ObjectGetProperty(&defn, "RestService") <> 2 Then
         throw CreateException(0, 0, "RestService must be 2 (REST Provider)");
      End-If;
   End-If;
   If &kind = "operation" Then
      Local string &restMethod = ObjectGetProperty(&defn, "Restmethod");
      If ObjectGetProperty(&defn, "Rtngtype") <> "S" Then
         throw CreateException(0, 0, "Rtngtype must be S (synchronous)");
      End-If;
      If &restMethod <> "GET" And
            &restMethod <> "POST" And
            &restMethod <> "PUT" And
            &restMethod <> "DELETE" And
            &restMethod <> "PATCH" Then
         throw CreateException(0, 0, "Unsupported REST method");
      End-If;
      Local object &serviceMgr = CreateObject("%metadata:ServiceDefn:ServiceDefn_Manager");
      Local object &serviceKey = create %metadata:Key(key:Class_ServiceName, String(ObjectGetProperty(&defn, "Servicename")));
      If Not ObjectDoMethodArray(&serviceMgr, "DefnExists", CreateArrayAny(&serviceKey)) Then
         throw CreateException(0, 0, "Parent service does not exist");
      End-If;
      Local object &parentServiceDefn = ObjectDoMethodArray(&serviceMgr, "GetDefnToUpdate", CreateArrayAny(&serviceKey));
      If ObjectGetProperty(&parentServiceDefn, "RestService") <> 2 Then
         throw CreateException(0, 0, "Parent service must be a REST Provider");
      End-If;
   End-If;
   If &kind = "menu" Then
      If ObjectGetProperty(&defn, "Menutype") <> 0 And
            ObjectGetProperty(&defn, "Menutype") <> 1 Then
         throw CreateException(0, 0, "Menutype must be 0 (Standard) or 1 (Pop-up)");
      End-If;
      Local integer &mi;
      Local Record &componentRec;
      Local string &componentName;
      For &mi = 1 To ObjectGetProperty(&defn, "Count_Mit")
         &child = ObjectDoMethodArray(&defn, "Get_Mit", CreateArrayAny(&mi));
         &componentName = ObjectGetProperty(&child, "PnlGrpName");
         If All(&componentName) Then
            &componentRec = CreateRecord(Record.PSPNLGRPDEFN);
            &componentRec.PNLGRPNAME.Value = &componentName;
            &componentRec.MARKET.Value = ObjectGetProperty(&child, "Market");
            If Not &componentRec.SelectByKey() Then
               throw CreateException(0, 0, "Menu references a missing component/market");
            End-If;
         End-If;
      End-For;
   End-If;
   If &kind = "version" Then
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local object &msgManager = CreateObject("%metadata:MessageDefn:MessageDefn_Manager");
      Local object &msgKey, &messageDefn, &messageVersion;
      Local array of integer &messageIDs;
      Local string &messageName, &messageVersionName;
      Local integer &mp, &mv;
      Local boolean &versionFound;
      For &mp = 1 To ObjectGetProperty(&defn, "Count_Oprverdfnparm")
         &child = ObjectDoMethodArray(&defn, "Get_Oprverdfnparm", CreateArrayAny(&mp));
         &messageName = ObjectGetProperty(&child, "Messagename");
         &messageVersionName = ObjectGetProperty(&child, "Messageversion");
         If None(&messageName) Or
               None(&messageVersionName) Then
            throw CreateException(0, 0, "Message bindings require message name and version");
         End-If;
         &messageIDs = &objectKeys.GetObjectIDs(37, CreateArray(&messageName, " ", " ", " "));
         &msgKey = CreateObject("%metadata:Key", &messageIDs [1], &messageName);
         If Not ObjectDoMethodArray(&msgManager, "DefnExists", CreateArrayAny(&msgKey)) Then
            throw CreateException(0, 0, "Referenced Message does not exist");
         End-If;
         &messageDefn = ObjectDoMethodArray(&msgManager, "GetDefnToUpdate", CreateArrayAny(&msgKey));
         &versionFound = False;
         For &mv = 1 To ObjectGetProperty(&messageDefn, "Count_Mvt")
            &messageVersion = ObjectDoMethodArray(&messageDefn, "Get_Mvt", CreateArrayAny(&mv));
            If ObjectGetProperty(&messageVersion, "VerName") = &messageVersionName Then
               &versionFound = True;
               Break;
            End-If;
         End-For;
         If Not &versionFound Then
            throw CreateException(0, 0, "Referenced Message version does not exist");
         End-If;
      End-For;
   End-If;
   If &kind = "handler" Then
      If ObjectGetProperty(&defn, "Handlertype") <> "ApplicationClass" Or
            ObjectGetProperty(&defn, "Handlerid") <> "RQST" Then
         throw CreateException(0, 0, "REST Provider requires an Application Class request handler");
      End-If;
      Local object &classKey;
      Local object &classManager = CreateObject("%metadata:PeopleCodeProgram:PeopleCodeProgram_Manager");
      Local array of string &qualifiers;
      Local integer &hi, &hq;
      For &hi = 1 To ObjectGetProperty(&defn, "Count_Operationac")
         &child = ObjectDoMethodArray(&defn, "Get_Operationac", CreateArrayAny(&hi));
         &classKey = create %metadata:Key(key:Class_ApplicationPackage, String(ObjectGetProperty(&child, "Packageroot")));
         Local string &qualifierPath = ObjectGetProperty(&child, "Qualifypath");
         If All(&qualifierPath) Then
            &qualifiers = Split(&qualifierPath, ":");
            If &qualifiers.Len > 2 Then
               throw CreateException(0, 0, "Application Class qualifier depth exceeds PeopleTools limit");
            End-If;
            For &hq = 1 To &qualifiers.Len
               If &hq = 1 Then
                  ObjectDoMethod(&classKey, "AddItem", key:Class_ApplicationPackage1, &qualifiers [&hq]);
               Else
                  ObjectDoMethod(&classKey, "AddItem", key:Class_ApplicationPackage2, &qualifiers [&hq]);
               End-If;
            End-For;
         End-If;
         ObjectDoMethod(&classKey, "AddItem", key:Class_ApplicationClass, String(ObjectGetProperty(&child, "Classname")));
         ObjectDoMethod(&classKey, "AddItem", key:Class_Method, "OnExecute");
         If Not ObjectDoMethodArray(&classManager, "DefnExists", CreateArrayAny(&classKey)) Then
            throw CreateException(0, 0, "Referenced Application Class does not exist");
         End-If;
         If ObjectGetProperty(&child, "Methodname") <> "OnRequest" Then
            throw CreateException(0, 0, "REST request handler method must be OnRequest");
         End-If;
      End-For;
   End-If;
   If &kind = "routing" Then
      If ObjectGetProperty(&defn, "Rtngtype") <> "S" Then
         throw CreateException(0, 0, "Only synchronous routing is supported");
      End-If;
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local object &nodeManager = CreateObject("%metadata:NodeDefn:NodeDefn_Manager");
      Local object &nodeKey;
      Local array of integer &nodeIDs;
      Local array of string &nodeNames = CreateArray(String(ObjectGetProperty(&defn, "Sendernodename")), String(ObjectGetProperty(&defn, "Receivernodename")));
      Local integer &ni;
      For &ni = 1 To &nodeNames.Len
         If &nodeNames [&ni] <> "~~ANY~~" Then
            &nodeIDs = &objectKeys.GetObjectIDs(35, CreateArray(&nodeNames [&ni], " ", " ", " "));
            &nodeKey = CreateObject("%metadata:Key", &nodeIDs [1], &nodeNames [&ni]);
            If Not ObjectDoMethodArray(&nodeManager, "DefnExists", CreateArrayAny(&nodeKey)) Then
               throw CreateException(0, 0, "Referenced IB Node does not exist");
            End-If;
         End-If;
      End-For;
   End-If;
   If &kind = "portal" Then
      %This.CheckPortalContent(&defn, &mgr, &portalIDs);
      Local string &parentName = ObjectGetProperty(&defn, "PrntObjName");
      If None(&parentName) Then
         throw CreateException(0, 0, "PrntObjName is required");
      End-If;
      Local object &parentKey, &parentDefn;
      Local array of string &visited = CreateArrayRept("", 0);
      Local ApiObject &registry = %Session.GetPortalRegistry();
      &registry.Open(&req.GetString("PortalName"));
      Local ApiObject &parentFolder = &registry.FindFolderByName(&parentName);
      If &parentFolder = Null Then
         throw CreateException(0, 0, "Parent folder does not exist");
      End-If;
      If Not &parentFolder.Authorized Then
         throw CreateException(0, 0, "User is not authorized for parent folder");
      End-If;
      If &action <> "create" Then
         Local ApiObject &portalObj;
         If &req.GetString("RefType") = "F" Then
            &portalObj = &registry.FindFolderByName(&name);
         Else
            If ObjectGetProperty(&defn, "IsLink") Then
               &portalObj = &registry.FindCRefLinkByName(&name);
            Else
               &portalObj = &registry.FindCRefByName(&name);
            End-If;
         End-If;
         If &portalObj = Null Then
            throw CreateException(0, 0, "Portal object could not be loaded");
         End-If;
         If Not &portalObj.Authorized Then
            throw CreateException(0, 0, "User is not authorized for portal object");
         End-If;
      End-If;
      While All(&parentName)
         If &parentName = &name Or
               &visited.Find(&parentName) > 0 Then
            throw CreateException(0, 0, "Portal parent would create a cycle");
         End-If;
         &visited.Push(&parentName);
         &parentKey = CreateObject("%metadata:Key", &portalIDs [1], &req.GetString("PortalName"));
         ObjectDoMethod(&parentKey, "AddItem", &portalIDs [2], "F");
         ObjectDoMethod(&parentKey, "AddItem", &portalIDs [3], &parentName);
         &parentDefn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&parentKey));
         &parentName = ObjectGetProperty(&parentDefn, "PrntObjName");
      End-While;
      Local string &portalLabel = ObjectGetProperty(&defn, "LabelName");
      If None(&portalLabel) Then
         throw CreateException(0, 0, "LabelName is required");
      End-If;
      If ObjectGetProperty(&defn, "IsPublic") <> 0 And
            ObjectGetProperty(&defn, "IsPublic") <> 1 Then
         throw CreateException(0, 0, "IsPublic must be 0 or 1");
      End-If;
      Local integer &pi;
      Local string &permissionType;
      Local Record &permissionRec;
      For &pi = 1 To ObjectGetProperty(&defn, "Count_Permission")
         &child = ObjectDoMethodArray(&defn, "Get_Permission", CreateArrayAny(&pi));
         &permissionType = ObjectGetProperty(&child, "PermType");
         If &permissionType = "P" Then
            &permissionRec = CreateRecord(Record.PSCLASSDEFN);
            &permissionRec.CLASSID.Value = ObjectGetProperty(&child, "PermName");
         Else
            If &permissionType <> "R" Then
               throw CreateException(0, 0, "PermType must be P (Permission List) or R (Role)");
            End-If;
            &permissionRec = CreateRecord(Record.PSROLEDEFN);
            &permissionRec.ROLENAME.Value = ObjectGetProperty(&child, "PermName");
         End-If;
         If Not &permissionRec.SelectByKey() Then
            throw CreateException(0, 0, "Portal permission principal does not exist");
         End-If;
         If &req.GetString("RefType") <> "F" And
               ObjectGetProperty(&child, "IsCascade") Then
            throw CreateException(0, 0, "Only folder permissions may cascade");
         End-If;
      End-For;
      If ObjectGetProperty(&defn, "CrefUsageType") = "LINK" Then
         Local object &targetKey = CreateObject("%metadata:Key", &portalIDs [1], String(ObjectGetProperty(&defn, "LinksPortalName")));
         ObjectDoMethod(&targetKey, "AddItem", &portalIDs [2], "C");
         ObjectDoMethod(&targetKey, "AddItem", &portalIDs [3], String(ObjectGetProperty(&defn, "LinksObjectName")));
         If Not ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&targetKey)) Then
            throw CreateException(0, 0, "Link target does not exist");
         End-If;
         Local object &targetDefn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&targetKey));
         If ObjectGetProperty(&targetDefn, "IsLink") Then
            throw CreateException(0, 0, "A link cannot target another link");
         End-If;
         ObjectSetProperty(&defn, "CrefURLType", ObjectGetProperty(&targetDefn, "CrefURLType"));
         ObjectSetProperty(&defn, "CrefTemplateType", ObjectGetProperty(&targetDefn, "CrefTemplateType"));
         ObjectSetProperty(&defn, "CrefStorageType", ObjectGetProperty(&targetDefn, "CrefStorageType"));
         ObjectSetProperty(&defn, "CntPrvName", ObjectGetProperty(&targetDefn, "CntPrvName"));
         Local string &linkURL = ObjectGetProperty(&targetDefn, "URLLogical");
         Local string &linkFragment = "";
         Local integer &fragmentAt = Find("#", &linkURL);
         If &fragmentAt > 0 Then
            &linkFragment = Substring(&linkURL, &fragmentAt, Len(&linkURL) - &fragmentAt + 1);
            &linkURL = Substring(&linkURL, 1, &fragmentAt - 1);
         End-If;
         If Find("?", &linkURL) > 0 Then
            &linkURL = &linkURL | "&";
         Else
            &linkURL = &linkURL | "?";
         End-If;
         ObjectSetProperty(&defn, "URLLogical", &linkURL | "pslnkid=" | &name | &linkFragment);
         &after = %This.Snapshot(&defn, &fields, &collections, &childFields);
      End-If;
      &registry.Close();
   End-If;
   If Not &dryRun Then
      If &action = "create" Then
         &saveMethod = "SaveNewDefn";
      Else
         &saveMethod = "UpdateDefn";
      End-If;
      &ok = ObjectDoMethodArray(&defn, &saveMethod, CreateArrayAny());
      If Not &ok Then
         throw CreateException(0, 0, "Native " | &saveMethod | " failed");
      End-If;
      &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&key));
      &after = %This.Snapshot(&defn, &fields, &collections, &childFields);
      If &kind = "operation" Then
         %This.SyncServiceMembership(&name, &before.GetString("Servicename"), &after.GetString("Servicename"));
      End-If;
      If &kind = "menu" And
            &action = "deleteChild" And
            &req.IsExist("collections") Then
         Local JsonObject &deletedCollections = &req.GetJsonObject("collections");
         If &deletedCollections.IsExist("Mit") Then
            Local JsonArray &deletedItems = &deletedCollections.GetJsonArray("Mit");
            If &objectKeys = Null Then
               &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
            End-If;
            Local object &pcManager = CreateObject("%metadata:PeopleCodeProgram:PeopleCodeProgram_Manager");
            Local object &pcKey;
            Local array of integer &pcIDs;
            Local integer &di;
            Local string &deletedBar, &deletedItem;
            For &di = 1 To &deletedItems.Size
               &row = &deletedItems.GetJsonObject(&di);
               &deletedBar = &row.GetString("BarName");
               &deletedItem = &row.GetString("ItemName");
               &pcIDs = &objectKeys.GetObjectIDs(9, CreateArray(&name, &deletedBar, &deletedItem, "ItemSelected"));
               &pcKey = CreateObject("%metadata:Key", &pcIDs [1], &name);
               ObjectDoMethod(&pcKey, "AddItem", &pcIDs [2], &deletedBar);
               ObjectDoMethod(&pcKey, "AddItem", &pcIDs [3], &deletedItem);
               ObjectDoMethod(&pcKey, "AddItem", &pcIDs [4], "ItemSelected");
               If ObjectDoMethodArray(&pcManager, "DefnExists", CreateArrayAny(&pcKey)) Then
                  If Not ObjectDoMethodArray(&pcManager, "DeleteDefn", CreateArrayAny(&pcKey)) Then
                     throw CreateException(0, 0, "Menu item saved, but owned PeopleCode deletion failed");
                  End-If;
                  If ObjectDoMethodArray(&pcManager, "DefnExists", CreateArrayAny(&pcKey)) Then
                     throw CreateException(0, 0, "Deleted menu item still owns PeopleCode");
                  End-If;
               End-If;
            End-For;
         End-If;
      End-If;
   End-If;
   &result = CreateJsonObject();
   &result.AddProperty("dryRun", &dryRun);
   &result.AddJsonObject("before", &before);
   &result.AddJsonObject("after", &after);
   Return &result;
end-method;

import %metadata:ProjectDefn:*;

/* Resolve native key types without loading, naming, or saving a Project. */
class ObjectKeyResolver
   method ObjectKeyResolver();
   method GetObjectIDs(&objectType As integer, &objectValues As array of string) Returns array of integer;
private
   instance %metadata:ProjectDefn:ProjectDefn &keySource;
end-class;

method ObjectKeyResolver
   Local %metadata:ProjectDefn:ProjectDefn_Manager &manager = create %metadata:ProjectDefn:ProjectDefn_Manager();
   &keySource = &manager.CreateDefn();
end-method;

method GetObjectIDs
   /+ &objectType as Integer, +/
   /+ &objectValues as Array of String +/
   /+ Returns Array of Integer +/
   If &objectType < 0 Then
      throw CreateException(0, 0, "ObjectType must be nonnegative");
   End-If;
   If &objectValues = Null Then
      throw CreateException(0, 0, "ObjectValues are required");
   End-If;
   If &objectValues.Len <> 4 Then
      throw CreateException(0, 0, "ObjectValues must contain all four key positions; use blanks for unused positions");
   End-If;
   Local array of integer &ids = &keySource.GetObjectIDs(&objectType, &objectValues);
   If &ids = Null Then
      throw CreateException(0, 0, "Native ObjectID resolution returned no result");
   End-If;
   If &ids.Len <> 4 Then
      throw CreateException(0, 0, "Native ObjectID resolution must return four key positions");
   End-If;
   If &ids [1] <= 0 Then
      throw CreateException(0, 0, "Native ObjectID resolution returned an invalid primary key type");
   End-If;
   Return &ids;
end-method;

import %metadata:Key;
import C_PORTAL_PKG:Util:CommonUtil;

class OperationSecurityAdapter
   method OperationSecurityAdapter();
   method Run(&req As JsonObject) Returns JsonObject;
   method Cleanup(&operation As string) Returns integer;
private
   method Read(&defn As object, &operation As string, &permissionList As string) Returns JsonObject;
end-class;

method OperationSecurityAdapter
end-method;

method Read
   /+ &defn as Object, +/
   /+ &operation as String, +/
   /+ &permissionList as String +/
   /+ Returns JsonObject +/
   Local integer &i;
   Local integer &access = 0;
   Local boolean &exists = False;
   Local object &row;
   For &i = 1 To ObjectGetProperty(&defn, "Count_Awst")
      &row = ObjectDoMethodArray(&defn, "Get_Awst", CreateArrayAny(&i));
      If ObjectGetProperty(&row, "WSOperationName") = &operation Then
         &access = ObjectGetProperty(&row, "AuthActions");
         &exists = True;
         Break;
      End-If;
   End-For;
   Local JsonObject &out = CreateJsonObject();
   Local C_PORTAL_PKG:Util:CommonUtil &util = create C_PORTAL_PKG:Util:CommonUtil();
   &out.AddProperty("operationName", &util.EscapeJSON(&operation));
   &out.AddProperty("permissionList", &util.EscapeJSON(&permissionList));
   &out.AddProperty("exists", &exists);
   &out.AddProperty("access", &access);
   Return &out;
end-method;

method Cleanup
   /+ &operation as String +/
   /+ Returns Integer +/
   Local object &opMgr = CreateObject("%metadata:OperationDefn:OperationDefn_Manager");
   Local object &opKey = create %metadata:Key(Key:Class_OperationName, &operation);
   If ObjectDoMethodArray(&opMgr, "DefnExists", CreateArrayAny(&opKey)) Then
      throw CreateException(0, 0, "Permission cleanup requires an already deleted operation");
   End-If;
   Local Rowset &rows = CreateRowset(Record.PSAUTHWS);
   Local integer &count = &rows.Fill("WHERE IB_OPERATIONNAME = :1", &operation);
   Local integer &i, &j;
   Local Record &access;
   Local object &mgr = CreateObject("%metadata:PermissionListDefn:PermissionListDefn_Manager");
   Local object &key, &defn, &row;
   For &i = 1 To &count
      &access = &rows.GetRow(&i).GetRecord(Record.PSAUTHWS);
      &key = create %metadata:Key(Key:Class_Class, String(&access.CLASSID.Value));
      &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&key));
      For &j = ObjectGetProperty(&defn, "Count_Awst") To 1 Step - 1
         &row = ObjectDoMethodArray(&defn, "Get_Awst", CreateArrayAny(&j));
         If ObjectGetProperty(&row, "WSOperationName") = &operation Then
            If Not ObjectDoMethodArray(&defn, "Delete_Awst", CreateArrayAny(&j)) Then
               throw CreateException(0, 0, "Native permission cleanup failed");
            End-If;
         End-If;
      End-For;
      If Not ObjectDoMethodArray(&defn, "UpdateDefn", CreateArrayAny()) Then
         throw CreateException(0, 0, "Permission List update failed during cleanup");
      End-If;
   End-For;
   Return &count;
end-method;

method Run
   /+ &req as JsonObject +/
   /+ Returns JsonObject +/
   Local string &operation = &req.GetString("name");
   Local string &permissionList = &req.GetString("permissionList");
   Local string &action = &req.GetString("operationType");
   Local object &opMgr = CreateObject("%metadata:OperationDefn:OperationDefn_Manager");
   Local object &opKey = create %metadata:Key(Key:Class_OperationName, &operation);
   If Not ObjectDoMethodArray(&opMgr, "DefnExists", CreateArrayAny(&opKey)) Then
      throw CreateException(0, 0, "Operation does not exist");
   End-If;
   Local object &op = ObjectDoMethodArray(&opMgr, "GetDefnToUpdate", CreateArrayAny(&opKey));
   If ObjectGetProperty(&op, "RestService") <> 2 Or
         ObjectGetProperty(&op, "Rtngtype") <> "S" Then
      throw CreateException(0, 0, "Only synchronous REST Provider operations are supported");
   End-If;
   Local object &mgr = CreateObject("%metadata:PermissionListDefn:PermissionListDefn_Manager");
   Local object &key = create %metadata:Key(Key:Class_Class, &permissionList);
   If Not ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&key)) Then
      throw CreateException(0, 0, "Existing Permission List is required");
   End-If;
   Local object &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&key));
   Local JsonObject &before = %This.Read(&defn, &operation, &permissionList);
   Local C_PORTAL_PKG:Util:CommonUtil &util = create C_PORTAL_PKG:Util:CommonUtil();
   If &action = "view" Or
         &action = "struct" Then
      &before.AddProperty("stateToken", &util.EscapeJSON(&before.ToString()));
      Return &before;
   End-If;
   If &action <> "modify" Then
      throw CreateException(0, 0, "Use modify to set operation access");
   End-If;
   Local number &newAccess = &req.GetNumber("access");
   If &newAccess <> 0 And
         &newAccess <> 4 Then
      throw CreateException(0, 0, "Access must be 0 (none) or 4 (full)");
   End-If;
   If &req.IsExist("expectedState") And
         &req.GetString("expectedState") <> &before.ToString() Then
      throw CreateException(0, 0, "Operation permission changed since snapshot");
   End-If;
   Local boolean &dry = False;
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   Local boolean &changed = False;
   If Not &before.GetBoolean("exists") Or
         &before.GetNumber("access") <> &newAccess Then
      &changed = True;
   End-If;
   Local integer &i;
   Local integer &found = 0;
   Local object &row;
   For &i = 1 To ObjectGetProperty(&defn, "Count_Awst")
      &row = ObjectDoMethodArray(&defn, "Get_Awst", CreateArrayAny(&i));
      If ObjectGetProperty(&row, "WSOperationName") = &operation Then
         &found = &i;
         Break;
      End-If;
   End-For;
   If &changed Then
      If &found = 0 Then
         &row = ObjectDoMethodArray(&defn, "Append_Awst", CreateArrayAny(ObjectGetProperty(&defn, "Count_Awst")));
         ObjectSetProperty(&row, "WSOperationName", &operation);
      End-If;
      ObjectSetProperty(&row, "AuthActions", &newAccess);
   End-If;
   Local JsonObject &after = %This.Read(&defn, &operation, &permissionList);
   If Not &dry And
         &changed Then
      If Not ObjectDoMethodArray(&defn, "UpdateDefn", CreateArrayAny()) Then
         throw CreateException(0, 0, "Native Permission List update failed");
      End-If;
      /* The CLM manager may retain the pre-save cache until the IB commit. Read
     the exact persisted row here; CLI performs another request after commit. */
      Local Record &saved = CreateRecord(Record.PSAUTHWS);
      &saved.CLASSID.Value = &permissionList;
      &saved.IB_OPERATIONNAME.Value = &operation;
      If Not &saved.SelectByKey() Or
            &saved.AUTHORIZEDACTIONS.Value <> &newAccess Then
         throw CreateException(0, 0, "Operation permission readback failed");
      End-If;
   End-If;
   Local JsonObject &result = CreateJsonObject();
   &result.AddProperty("dryRun", &dry);
   &result.AddProperty("changed", &changed);
   &result.AddJsonObject("before", &before);
   &result.AddJsonObject("after", &after);
   Return &result;
end-method;

import %metadata:Key;
import %metadata:PeopleCodeProgram:*;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;
import C_PORTAL_PKG:Util:CommonUtil;

/* Delete one native program; the caller builds its complete native key. */
class PeopleCodeDeletion
   method PeopleCodeDeletion();
   method Run(&key As %metadata:Key, &projectType As integer, &values As array of string, &req As JsonObject) Returns JsonObject;
end-class;

method PeopleCodeDeletion
end-method;

method Run
   /+ &key as %Metadata:Key, +/
   /+ &projectType as Integer, +/
   /+ &values as Array of String, +/
   /+ &req as JsonObject +/
   /+ Returns JsonObject +/
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgr;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &prog;
   Local C_META_DATA_PKG:Utility:ObjectKeyResolver &resolver;
   Local C_PORTAL_PKG:Util:CommonUtil &util;
   Local JsonObject &out, &item;
   Local array of integer &ids;
   Local boolean &dry;
   Local string &before, &expected;
   Local integer &i;

   If Not &req.IsExist("expectedCode") Then
      throw CreateException(0, 0, "deletePeopleCode requires expectedCode from a fresh viewPeopleCode snapshot");
   End-If;
   &mgr = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   If Not &mgr.DefnExists(&key) Then
      throw CreateException(0, 0, "PeopleCode program does not exist");
   End-If;
   &util = create C_PORTAL_PKG:Util:CommonUtil();
   &prog = &mgr.GetDefn(&key);
   &before = &prog.GetProgram();
   &expected = &util.UnEscapeJSON(&req.GetString("expectedCode"));
   If &before <> &expected Then
      throw CreateException(0, 0, "PeopleCode changed since snapshot; read again before deleting");
   End-If;
   &dry = False;
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   &resolver = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
   &ids = &resolver.GetObjectIDs(&projectType, &values);
   &item = CreateJsonObject();
   &item.AddProperty("objectType", &projectType);
   For &i = 1 To 4
      &item.AddProperty("objectId" | &i, &ids [&i]);
      &item.AddProperty("objectValue" | &i, &values [&i]);
   End-For;
   If Not &dry Then
      If Not &mgr.DeleteDefn(&key) Then
         throw CreateException(0, 0, "PeopleCode DeleteDefn failed; inspect current state before retrying");
      End-If;
      If &mgr.DefnExists(&key) Then
         throw CreateException(0, 0, "PeopleCode program still exists after DeleteDefn");
      End-If;
   End-If;
   &out = CreateJsonObject();
   &out.AddProperty("deleted", ( Not &dry));
   &out.AddProperty("dryRun", &dry);
   &out.AddProperty("programExists", &mgr.DefnExists(&key));
   &out.AddJsonObject("projectItem", &item);
   Return &out;
end-method;

/* 说明：Record Field Property的选项都存储与PSRECFIELD表的USEEDIT\USEEDIT2两个字段中
         使用2的幂次方相加来记录系统勾选了哪些属性
         此类用于计算和还原UseEdit，并按AD GUI的限制规则校验API请求。
         2026-09-05:
           1. PersistInMenu 从USEEDIT数组移到USEEDIT2数组（GUI实测其存储于USEEDIT2高位，带符号-2147483648）；
           2. GetFieldPropertyByUseEdit 支持负数（高位置位）解码，且未知位一律扣减避免贪婪分解错位；
           3. GetUseEdit2ByFieldProperty 写入时高位转为带符号负数；
           4. 新增 ValidateFieldProperty：按 Application Designer GUI 的置灰/联动规则校验 fieldProperty 请求。 */
class RecordUseEdit
   method RecordUseEdit();

   method GetRecordUseProperty(&p_recuse As integer) Returns JsonArray;
   method GetRecuseByRecordUseProperty(&p_arr As JsonArray) Returns integer;
   method GetFieldPropertyByUseEdit(&p_useEdit As number, &p_useEdit2 As number) Returns JsonArray;
   method GetUseEditByFieldProperty(&p_obj As JsonObject) Returns number;
   method GetUseEdit2ByFieldProperty(&p_arr As JsonArray) Returns number;
   method ValidateFieldProperty(&p_FieldProperty As JsonArray, &p_FieldTypeName As string, &p_EditTable As string, &p_DefGuiControl As integer, &p_HasXlat As boolean, &p_IsSubRecord As boolean) Returns string;
private
   instance array of string &_RecordUsePropName;
   instance array of string &_RecFieldPropName;
   instance array of string &_RecFieldPropName2;
   instance array of number &_RecFieldPropNumber;
end-class;

method RecordUseEdit
   &_RecordUsePropName = CreateArray("Add", "Change", "Delete", "Selective");
   &_RecFieldPropName = CreateArray("Key", "DuplicateOrderKey", "SystemMaintainedField", "AuditFieldAdd", "AlternateSearchKey", "ListBoxItem", "DescendingKey", "AuditFieldChange", "RequiredField", "TranslateTableEdit", "AuditFieldDelete", "SearchKey", "ReasonableDate", "Yes/NoTableEdit", "PromptTableEdit", "Auto-Update", "UnKnown", "UnKnown", "FromSearchField", "ThroughSearchField", "1/0TableEdit", "DisableAdvancedSearchOptions", "UnKnown", "RegularField", "DefaultSearchField", "UnKnown", "UnKnown", "AllowSearchEventsForPromptDialogs", "SearchEdit", "DisplayInAutocompleteWindow", "EnableAutocompleteWhenUsedInSearchRecord", "UnKnown");
   &_RecFieldPropName2 = CreateArray("UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "DisableAutocompleteForThisField", "UnKnown", "UnKnown", "InMemory", "UnKnown", "UnKnown", "UnKnown", "DoNotTraceValue", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "PersistInMenu");
   &_RecFieldPropNumber = CreateArray(1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536, 131072, 262144, 524288, 1048576, 2097152, 4194304, 8388608, 16777216, 33554432, 67108864, 134217728, 268435456, 536870912, 1073741824, 2147483648);
end-method;

method GetRecordUseProperty
   /+ &p_recuse as Integer +/
   /+ Returns JsonArray +/
   Local JsonArray &RecuseArr;
   Local integer &i;

   &RecuseArr = CreateJsonArray();
   For &i = 4 To 1 Step - 1
      If &p_recuse >= &_RecFieldPropNumber [&i] Then
         &p_recuse = &p_recuse - &_RecFieldPropNumber [&i];
         &RecuseArr.AddElement(&_RecordUsePropName [&i]);
      End-If;
   End-For;

   Return &RecuseArr;
end-method;

method GetRecuseByRecordUseProperty
   /+ &p_arr as JsonArray +/
   /+ Returns Integer +/
   Local integer &Recuse, &i, &j;
   Local string &PropertyName;

   &Recuse = 0;
   If None(&p_arr) Then
      Return &Recuse;
   End-If;

   For &i = 1 To &p_arr.Size
      &PropertyName = &p_arr.GetString(&i);
      For &j = 1 To &_RecordUsePropName.Len
         If &PropertyName = &_RecordUsePropName [&j] Then
            &Recuse = &Recuse + &_RecFieldPropNumber [&j];
            Break;
         End-If;
      End-For;
   End-For;

   Return &Recuse;
end-method;

method GetFieldPropertyByUseEdit
   /+ &p_useEdit as Number, +/
   /+ &p_useEdit2 as Number +/
   /+ Returns JsonArray +/
   Local integer &i;
   Local JsonArray &FieldProperty;

   &FieldProperty = CreateJsonArray();

   REM 高位带符号：DB中USEEDIT/USEEDIT2占用2^31位时为负数，先转回无符号再贪婪分解;
   If &p_useEdit < 0 Then
      &p_useEdit = &p_useEdit + 4294967296;
   End-If;
   If &p_useEdit2 < 0 Then
      &p_useEdit2 = &p_useEdit2 + 4294967296;
   End-If;

   For &i = &_RecFieldPropNumber.Len To 1 Step - 1
      If &p_useEdit >= &_RecFieldPropNumber [&i] Then
         &p_useEdit = &p_useEdit - &_RecFieldPropNumber [&i];
         If &_RecFieldPropName [&i] <> "UnKnown" And
               &_RecFieldPropName [&i] <> "RegularField" Then
            &FieldProperty.AddElement(&_RecFieldPropName [&i]);
         End-If;
      End-If;
   End-For;

   For &i = &_RecFieldPropNumber.Len To 1 Step - 1
      If &p_useEdit2 >= &_RecFieldPropNumber [&i] Then
         &p_useEdit2 = &p_useEdit2 - &_RecFieldPropNumber [&i];
         If &_RecFieldPropName2 [&i] <> "UnKnown" Then
            &FieldProperty.AddElement(&_RecFieldPropName2 [&i]);
         End-If;
      End-If;
   End-For;
   Return &FieldProperty;
end-method;

method GetUseEditByFieldProperty
   /+ &p_obj as JsonObject +/
   /+ Returns Number +/
   Local number &UseEdit;
   Local integer &i, &j;
   Local string &PropertyName, &LabelId, &SubRecord;
   Local JsonArray &p_arr;

   &UseEdit = 0;
   If None(&p_obj) Then
      Return &UseEdit;
   End-If;

   &SubRecord = &p_obj.GetString("subRecord");
   &LabelId = &p_obj.GetString("labelId");
   &p_arr = &p_obj.GetJsonArray("fieldProperty");

   If &SubRecord <> "Y" And
         None(&LabelId) Then
      &UseEdit = 8388608;
   End-If;

   For &i = 1 To &p_arr.Size
      &PropertyName = &p_arr.GetString(&i);
      For &j = 1 To &_RecFieldPropName.Len
         If &PropertyName = &_RecFieldPropName [&j] Then
            &UseEdit = &UseEdit + &_RecFieldPropNumber [&j];
            Break;
         End-If;
      End-For;
   End-For;

   REM 防御：USEEDIT不应用到2^31位，若意外超出转为带符号;
   If &UseEdit >= 2147483648 Then
      &UseEdit = &UseEdit - 4294967296;
   End-If;

   Return &UseEdit;
end-method;

method GetUseEdit2ByFieldProperty
   /+ &p_arr as JsonArray +/
   /+ Returns Number +/
   Local number &UseEdit2;
   Local integer &i, &j;
   Local string &PropertyName;

   &UseEdit2 = 0;
   If None(&p_arr) Then
      Return &UseEdit2;
   End-If;

   For &i = 1 To &p_arr.Size
      &PropertyName = &p_arr.GetString(&i);
      For &j = 1 To &_RecFieldPropName2.Len
         If &PropertyName = &_RecFieldPropName2 [&j] Then
            &UseEdit2 = &UseEdit2 + &_RecFieldPropNumber [&j];
            Break;
         End-If;
      End-For;
   End-For;

   REM PersistInMenu占用2^31高位：按DB带符号存储规则转成负数;
   If &UseEdit2 >= 2147483648 Then
      &UseEdit2 = &UseEdit2 - 4294967296;
   End-If;

   Return &UseEdit2;
end-method;

method ValidateFieldProperty
   /+ &p_FieldProperty as JsonArray, +/
   /+ &p_FieldTypeName as String, +/
   /+ &p_EditTable as String, +/
   /+ &p_DefGuiControl as Integer, +/
   /+ &p_HasXlat as Boolean, +/
   /+ &p_IsSubRecord as Boolean +/
   /+ Returns String +/
   REM 校验规则与 Application Designer 的 Record Field Properties 对话框保持一致：;
   REM GUI中置灰（不可勾选）的组合在此拒绝；GUI中可勾选的组合在此放行。;
   Local string &Err, &Prop;
   Local integer &i;
   Local boolean &IsKey, &IsDupKey, &IsAltKey, &IsSearchKey, &IsSearchEdit, &IsDescKey, &IsLBI, &IsFrom, &IsThrough, &IsDefaultSearch, &IsDisableAdv, &IsAllowSearchEvt, &IsAuditAdd, &IsAuditChg, &IsAuditDel, &IsSysMaint, &IsDoNotTrace, &IsRequired, &IsTranslate, &IsReasonable, &IsYN, &IsPrompt, &IsAutoUpdate, &Is10, &IsDisplay, &IsEnableAC, &IsDisableAC, &IsPersistMenu, &IsRegularField, &IsInMemory, &IsUnKnownName;

   &IsKey = False;
   &IsDupKey = False;
   &IsAltKey = False;
   &IsSearchKey = False;
   &IsSearchEdit = False;
   &IsDescKey = False;
   &IsLBI = False;
   &IsFrom = False;
   &IsThrough = False;
   &IsDefaultSearch = False;
   &IsDisableAdv = False;
   &IsAllowSearchEvt = False;
   &IsAuditAdd = False;
   &IsAuditChg = False;
   &IsAuditDel = False;
   &IsSysMaint = False;
   &IsDoNotTrace = False;
   &IsRequired = False;
   &IsTranslate = False;
   &IsReasonable = False;
   &IsYN = False;
   &IsPrompt = False;
   &IsAutoUpdate = False;
   &Is10 = False;
   &IsDisplay = False;
   &IsEnableAC = False;
   &IsDisableAC = False;
   &IsPersistMenu = False;
   &IsRegularField = False;
   &IsInMemory = False;
   &IsUnKnownName = False;

   If &p_IsSubRecord And
         &p_FieldProperty.Size > 0 Then
      &Err = &Err | "subrecord reference fields cannot have field properties (AD does not allow editing them), ";
      Return &Err;
   End-If;

   For &i = 1 To &p_FieldProperty.Size
      &Prop = &p_FieldProperty.GetString(&i);
      Evaluate &Prop
      When "Key"
         &IsKey = True;
         Break;
      When "DuplicateOrderKey"
         &IsDupKey = True;
         Break;
      When "SystemMaintainedField"
         &IsSysMaint = True;
         Break;
      When "DoNotTraceValue"
         &IsDoNotTrace = True;
         Break;
      When "AuditFieldAdd"
         &IsAuditAdd = True;
         Break;
      When "AlternateSearchKey"
         &IsAltKey = True;
         Break;
      When "ListBoxItem"
         &IsLBI = True;
         Break;
      When "DescendingKey"
         &IsDescKey = True;
         Break;
      When "AuditFieldChange"
         &IsAuditChg = True;
         Break;
      When "RequiredField"
         &IsRequired = True;
         Break;
      When "TranslateTableEdit"
         &IsTranslate = True;
         Break;
      When "AuditFieldDelete"
         &IsAuditDel = True;
         Break;
      When "SearchKey"
         &IsSearchKey = True;
         Break;
      When "ReasonableDate"
         &IsReasonable = True;
         Break;
      When "Yes/NoTableEdit"
         &IsYN = True;
         Break;
      When "PromptTableEdit"
         &IsPrompt = True;
         Break;
      When "Auto-Update"
         &IsAutoUpdate = True;
         Break;
      When "FromSearchField"
         &IsFrom = True;
         Break;
      When "ThroughSearchField"
         &IsThrough = True;
         Break;
      When "1/0TableEdit"
         &Is10 = True;
         Break;
      When "DisableAdvancedSearchOptions"
         &IsDisableAdv = True;
         Break;
      When "DefaultSearchField"
         &IsDefaultSearch = True;
         Break;
      When "AllowSearchEventsForPromptDialogs"
         &IsAllowSearchEvt = True;
         Break;
      When "SearchEdit"
         &IsSearchEdit = True;
         Break;
      When "DisplayInAutocompleteWindow"
         &IsDisplay = True;
         Break;
      When "EnableAutocompleteWhenUsedInSearchRecord"
         &IsEnableAC = True;
         Break;
      When "DisableAutocompleteForThisField"
         &IsDisableAC = True;
         Break;
      When "PersistInMenu"
         &IsPersistMenu = True;
         Break;
      When "RegularField"
         &IsRegularField = True;
         Break;
      When "InMemory"
         &IsInMemory = True;
         Break;
      When-Other
         &IsUnKnownName = True;
      End-Evaluate;
   End-For;

   If &IsUnKnownName Then
      &Err = &Err | "unknown fieldProperty name (see 06-record-defn-api.md for the supported list), ";
   End-If;
   If &IsRegularField Then
      &Err = &Err | "RegularField is an internal storage marker (use-default-label bit) and cannot be set explicitly, ";
   End-If;
   If &IsInMemory Then
      &Err = &Err | "InMemory requires the Oracle In-Memory Column Store option on the record definition; AD disables this check box when the option is unavailable, ";
   End-If;

   REM 字段类型家族（与各类型字段属性面板截图一致）;
   Local boolean &IsChar, &IsNbr, &IsSign, &IsDate, &IsTime, &IsDtTm, &IsLong, &IsImage, &IsImageRef, &IsAttachment;
   &IsChar = (&p_FieldTypeName = "character");
   &IsNbr = (&p_FieldTypeName = "number");
   &IsSign = (&p_FieldTypeName = "signed number");
   &IsDate = (&p_FieldTypeName = "date");
   &IsTime = (&p_FieldTypeName = "time");
   &IsDtTm = (&p_FieldTypeName = "datetime");
   &IsLong = (&p_FieldTypeName = "long character");
   &IsImage = (&p_FieldTypeName = "image");
   &IsImageRef = (&p_FieldTypeName = "imageReference");
   &IsAttachment = (&p_FieldTypeName = "attachment");

   Local boolean &HasKeyGroup, &IsDateFamily, &IsSearchableType, &IsEditTypeType, &IsRequiredType, &IsDisplayType, &IsAutoUpdateType;
   REM Key/LBI/搜索组/Audit组：Long Char、Image、Attachment 的面板没有这些组（ImageRef有）;
   &HasKeyGroup = (&IsChar Or
      &IsNbr Or
      &IsSign Or
      &IsDate Or
      &IsTime Or
      &IsDtTm Or
      &IsImageRef);
   REM Date/Time/DateTime;
   &IsDateFamily = (&IsDate Or
      &IsTime Or
      &IsDtTm);
   &IsSearchableType = (&IsChar Or
      &IsNbr Or
      &IsSign Or
      &IsDate Or
      &IsTime Or
      &IsDtTm Or
      &IsImageRef);
   &IsEditTypeType = (&IsChar Or
      &IsNbr Or
      &IsSign);
   &IsRequiredType = (&IsChar Or
      &IsNbr Or
      &IsSign Or
      &IsDate Or
      &IsTime Or
      &IsDtTm);
   &IsDisplayType = (&IsChar Or
      &IsNbr Or
      &IsSign Or
      &IsDate Or
      &IsTime Or
      &IsDtTm);
   &IsAutoUpdateType = &IsDateFamily;

   If &HasKeyGroup = False Then
      If &IsKey Or
            &IsDupKey Or
            &IsAltKey Or
            &IsSearchKey Or
            &IsSearchEdit Or
            &IsDescKey Or
            &IsLBI Or
            &IsFrom Or
            &IsThrough Or
            &IsDefaultSearch Or
            &IsDisableAdv Or
            &IsAllowSearchEvt Then
         &Err = &Err | "key/search group properties are not available for field type " | &p_FieldTypeName | " (AD does not show them), ";
      End-If;
      If &IsAuditAdd Or
            &IsAuditChg Or
            &IsAuditDel Then
         &Err = &Err | "audit properties are not available for field type " | &p_FieldTypeName | ", ";
      End-If;
   End-If;
   If (&IsImage Or
         &IsAttachment) And
         &IsDoNotTrace Then
      &Err = &Err | "Do Not Trace Value is not available for field type " | &p_FieldTypeName | ", ";
   End-If;

   REM Key依赖链（GUI置灰规则）;
   If &IsSearchKey And
         &IsKey = False Then
      &Err = &Err | "Search Key requires Key (grayed out until Key is checked), ";
   End-If;
   If &IsSearchEdit And
         &IsSearchKey = False Then
      &Err = &Err | "Search Edit requires Search Key (grayed out until Search Key is checked), ";
   End-If;
   If &IsDescKey And
         &IsKey = False And
         &IsAltKey = False And
         &IsSearchKey = False Then
      &Err = &Err | "Descending Key requires Key, Alternate Search Key or Search Key (grayed out otherwise), ";
   End-If;
   If &IsDefaultSearch And
         &IsSearchKey = False And
         &IsAltKey = False Then
      &Err = &Err | "Default Search Field requires Search Key or Alternate Search Key (grayed out otherwise), ";
   End-If;
   If &IsFrom And
         &IsThrough Then
      &Err = &Err | "From Search Field and Through Search Field are mutually exclusive, ";
   End-If;

   REM Table Edit 类型互斥（GUI为单选）与类型限制;
   Local integer &TableEditCount;
   &TableEditCount = 0;
   If &IsYN Then
      &TableEditCount = &TableEditCount + 1;
   End-If;
   If &IsPrompt Then
      &TableEditCount = &TableEditCount + 1;
   End-If;
   If &IsTranslate Then
      &TableEditCount = &TableEditCount + 1;
   End-If;
   If &Is10 Then
      &TableEditCount = &TableEditCount + 1;
   End-If;
   If &TableEditCount > 1 Then
      &Err = &Err | "only one Table Edit type (Yes/No, Prompt, Translate, 1/0) can be selected, ";
   End-If;
   If &IsYN And
         &IsChar = False Then
      &Err = &Err | "Yes/No Table Edit is only available for character fields, ";
   End-If;
   If &Is10 And
         &IsNbr = False And
         &IsSign = False Then
      &Err = &Err | "1/0 Table Edit is only available for number fields, ";
   End-If;
   If &IsTranslate And
         &IsChar = False Then
      &Err = &Err | "Translate Table Edit is only available for character fields, ";
   End-If;
   If &IsTranslate And
         &p_HasXlat = False Then
      &Err = &Err | "Translate Table Edit requires the field to have translate values (Xlat), ";
   End-If;
   If &IsPrompt And
         &IsEditTypeType = False Then
      &Err = &Err | "PromptTableEdit property is only available for character/number fields (date/time/datetime can set a prompt table without the bit, GUI keeps USEEDIT unchanged), ";
   End-If;

   If &IsRequired And
         &IsRequiredType = False Then
      &Err = &Err | "Required is not available for field type " | &p_FieldTypeName | " (Image/ImageReference/Attachment/Long Character do not have it), ";
   End-If;
   If &IsReasonable And
         &IsDate = False Then
      &Err = &Err | "Reasonable Date is only available for date fields, ";
   End-If;
   If &IsAutoUpdate And
         &IsAutoUpdateType = False Then
      &Err = &Err | "Auto-Update is only available for date/time/datetime fields, ";
   End-If;

   REM Autocomplete Configuration（GUI置灰规则，2026-09-05实测）;
   If &IsEnableAC Then
      If &IsChar = False Then
         &Err = &Err | "Enable Autocomplete when used in Search Record is only available for character fields, ";
      End-If;
      If &IsSearchKey = False And
            &IsAltKey = False Then
         &Err = &Err | "Enable Autocomplete when used in Search Record requires Search Key or Alternate Search Key, ";
      End-If;
      If &p_DefGuiControl <> 99 And
            &p_DefGuiControl <> 4 Then
         &Err = &Err | "Enable Autocomplete when used in Search Record requires Default Page Control = Edit Box or System Default, ";
      End-If;
   End-If;
   If &IsDisableAC And
         &p_EditTable = "" Then
      &Err = &Err | "Disable Autocomplete for this field requires the field to have a prompt table (Edit Type = Table Edit with a prompt table), ";
   End-If;
   If &IsDisplay Then
      If &IsDisplayType = False Then
         &Err = &Err | "Display in Autocomplete Window is not available for field type " | &p_FieldTypeName | ", ";
      End-If;
      If &IsLBI = False Then
         &Err = &Err | "Display in Autocomplete Window requires List Box Item, ";
      End-If;
      If &IsSearchKey Or
            &IsAltKey Then
         &Err = &Err | "Display in Autocomplete Window requires the field NOT to be a search item (it is auto-cleared when Search Key/Alternate Search Key is checked), ";
      End-If;
   End-If;
   If &IsPersistMenu And
         &IsLBI = False Then
      &Err = &Err | "Persist in Menu requires List Box Item (grayed out otherwise), ";
   End-If;

   Return &Err;
end-method;

import PS_PT:Integration:IRequestHandler;
import C_PORTAL_PKG:Util:*;

class Login implements PS_PT:Integration:IRequestHandler
   method Login();

   method OnRequest(&message As Message) Returns Message;
private
   Constant &OperationName = "PSTOKEN_GET";
   Constant &DatetimeFormat = "yyyy-MM-dd HH:mm:ss";

   instance C_PORTAL_PKG:Util:JsonUtil &JsonUtil;
   instance C_PORTAL_PKG:Util:HttpUtil &HttpUtil;
end-class;


method Login
   &JsonUtil = create C_PORTAL_PKG:Util:JsonUtil();
   &HttpUtil = create C_PORTAL_PKG:Util:HttpUtil();
end-method;


method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;
   Local JsonObject &RespObject;
   Local string &ErrorTxt, &LanguageCd, &LanguageInstall, &PropValue;
   Local integer &SessionTimeOut;

   try
      &LanguageCd = &HttpUtil.GetHeaderValue(&message, "LanguageCd");

      /* 如果有指定语言，切换语言 */
      If All(&LanguageCd) Then
         SQLExec("SELECT 'Y' FROM PSLANGUAGES WHERE LANGUAGE_CD = :1 AND INSTALLED = 1", &LanguageCd, &LanguageInstall);
         If &LanguageInstall = "Y" Then
            SetLanguage(&LanguageCd);
         Else
            &ErrorTxt = "不支持的语言：" | &LanguageCd;
         End-If;
      End-If;

      If All(&ErrorTxt) Then
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 1, &ErrorTxt);
         Return &RespMsg;
      End-If;

      &RespObject = CreateJsonObject();
      &RespObject.AddProperty("userid", %UserId);
      &RespObject.AddProperty("description", %UserDescription);
      &RespObject.AddProperty("psToken", %AuthenticationToken);
      &RespObject.AddProperty("emplid", %EmployeeId);
      &RespObject.AddProperty("language", %Language);

      /* 获取Token失效时间(由PeopleTools-安全性-安全性对象-单点登录中的Token过期时间决定) */
      SQLExec("SELECT TIMEOUTMINUTES FROM PSOPTIONS", &SessionTimeOut);
      &RespObject.AddProperty("TokenExpireTime", DateTimeToLocalizedString((%Datetime + &SessionTimeOut * 60), &DatetimeFormat));

      &RespMsg = &JsonUtil.CreateSuccessMessage(&OperationName, &RespObject);
   catch Exception &ex
      &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 999, "遇到未知异常：" | &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

class CommonUtil
   method CommonUtil();

   method ReplaceWithRegex(&p_orig As string, &p_regex As string, &p_replace As string) Returns string;
   method EncodeBase64(&p_str As string) Returns string;
   method DecodeBase64(&p_str As string) Returns string;
   method EscapeJSON(&p_str As string) Returns string;
   method UnEscapeJSON(&p_str As string) Returns string;
   method JsonHexDigit(&p_n As number) Returns string;
   method JsonHexValue(&p_c As string) Returns number;
end-class;

method CommonUtil

end-method;

method ReplaceWithRegex
   /+ &p_orig as String, +/
   /+ &p_regex as String, +/
   /+ &p_replace as String +/
   /+ Returns String +/
   Local string &ReplacedStr;
   Local JavaObject &Pattern = GetJavaClass("java.util.regex.Pattern").compile(&p_regex);
   Local JavaObject &PatternClass = &Pattern.getClass();
   Local JavaObject &stringType = CreateJavaObject("java.lang.Class[]", GetJavaClass("java.lang.CharSequence"));
   Local JavaObject &MatcherMethod = &PatternClass.getDeclaredMethod("matcher", &stringType);
   Local JavaObject &JavaString = CreateJavaObject("java.lang.String", &p_orig);
   Local JavaObject &args = CreateJavaObject("java.lang.Object[]", &JavaString);
   Local JavaObject &Mater = &MatcherMethod.invoke(&Pattern, &args);
   &Mater = &Mater.getClass().cast(&Mater);
   &ReplacedStr = &Mater.replaceAll(&p_replace);
   Return &ReplacedStr;
end-method;

method EncodeBase64
   /+ &p_str as String +/
   /+ Returns String +/
   Local string &EncodeStr;
   Local JavaObject &Encoder, &StrBytes;
   try
      &Encoder = GetJavaClass("java.util.Base64").getEncoder();
      &StrBytes = CreateJavaObject("java.lang.String", &p_str).getBytes("UTF-8");
      &EncodeStr = &Encoder.encodeToString(&StrBytes);
   end-try;
   Return &EncodeStr;
end-method;

method DecodeBase64
   /+ &p_str as String +/
   /+ Returns String +/
   Local string &DecodeStr;
   Local JavaObject &Decoder, &StrBytes, &JavaStr;
   try
      &Decoder = GetJavaClass("java.util.Base64").getDecoder();
      &StrBytes = &Decoder.decode(&p_str);
      &JavaStr = CreateJavaObject("java.lang.String", &StrBytes, "UTF-8");
      &DecodeStr = &JavaStr.toString();
   end-try;
   Return &DecodeStr;
end-method;

method EscapeJSON
   /+ &p_str as String +/
   /+ Returns String +/
   rem Local string &EscapeStr;

   rem &EscapeStr = GetJavaClass("org.apache.commons.text.StringEscapeUtils").escapeJson(&p_str);
   Local string &EscapeStr, &Replacement;
   Local number &i;

   &EscapeStr = &p_str;

   /* 必须先转义反斜杠 */
   &EscapeStr = Substitute(&EscapeStr, Char(92), Char(92) | Char(92));

   /* 双引号 */
   &EscapeStr = Substitute(&EscapeStr, Char(34), Char(92) | Char(34));

   /* U+0000 到 U+001F 控制字符 */
   For &i = 0 To 31
      Evaluate &i
      When 8
         &Replacement = Char(92) | "b";
      When 9
         &Replacement = Char(92) | "t";
      When 10
         &Replacement = Char(92) | "n";
      When 12
         &Replacement = Char(92) | "f";
      When 13
         &Replacement = Char(92) | "r";
      When-Other
         &Replacement = Char(92) | "u00" | %This.JsonHexDigit(Int(&i / 16)) | %This.JsonHexDigit(Mod(&i, 16));
      End-Evaluate;

      &EscapeStr = Substitute(&EscapeStr, Char(&i), &Replacement);
   End-For;

   Return &EscapeStr;
end-method;

method UnEscapeJSON
   /+ &p_str as String +/
   /+ Returns String +/
   rem Local string &UnEscapeStr;

   rem &UnEscapeStr = GetJavaClass("org.apache.commons.text.StringEscapeUtils").unescapeJson(&p_str);

   Local string &UnEscapeStr;
   Local string &BackslashToken;
   Local string &JsonText;
   Local JsonParser &Parser;
   Local JsonObject &Wrapper;
   Local boolean &ParseOK;

   /*
    * 包含 \uXXXX 时，使用 PeopleTools 原生 JSON 解析器
    */
   If Find(Char(92) | "u", &p_str) > 0 Then
      &JsonText = "{" | Char(34) | "_v" | Char(34) | ":" | Char(34) | &p_str | Char(34) | "}";

      &Parser = CreateJsonParser();
      &ParseOK = &Parser.Parse(&JsonText);

      If &ParseOK Then
         &Wrapper = &Parser.GetRootObject();
         Return &Wrapper.GetString("_v");
      End-If;
   End-If;

   /*
    * 处理普通 JSON 转义字符
    */
   &BackslashToken = "__PS_JSON_BACKSLASH_TOKEN_7F3A__";

   &UnEscapeStr = Substitute(&p_str, Char(92) | Char(92), &BackslashToken);
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | Char(34), Char(34));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "/", "/");
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "b", Char(8));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "f", Char(12));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "n", Char(10));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "r", Char(13));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "t", Char(9));
   &UnEscapeStr = Substitute(&UnEscapeStr, &BackslashToken, Char(92));

   Return &UnEscapeStr;
end-method;


method JsonHexDigit
   /+ &p_n as Number +/
   /+ Returns String +/

   Local string &HexDigits = "0123456789ABCDEF";

   Return Substring(&HexDigits, &p_n + 1, 1);
end-method;


method JsonHexValue
   /+ &p_c as String +/
   /+ Returns Number +/

   Local string &c;
   Local number &Code;

   &c = Upper(&p_c);
   &Code = Code(&c);

   If &Code >= 48 And
         &Code <= 57 Then
      Return &Code - 48;
   End-If;

   If &Code >= 65 And
         &Code <= 70 Then
      Return &Code - 55;
   End-If;

   Return - 1;
end-method;

