method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;


   Return &RespMsg;
end-method;

class HttpUtil
   method HttpUtil();

   method GetHeaderValue(&p_msg As Message, &p_key As string) Returns string;
end-class;

method HttpUtil

end-method;

method GetHeaderValue
   /+ &p_msg as Message, +/
   /+ &p_key as String +/
   /+ Returns String +/
   Local string &Value;
   Local integer &i;
   Local IBConnectorInfo &IBConnectorInfo;

   &IBConnectorInfo = &p_msg.IBInfo.IBConnectorInfo;
   For &i = 1 To &IBConnectorInfo.GetNumberOfConnectorProperties()
      Local string &PropName = &IBConnectorInfo.GetConnectorPropertiesName(&i);
      If &PropName = &p_key Then
         &Value = &IBConnectorInfo.GetConnectorPropertiesValue(&i);
         Break;
      End-If;
   End-For;

   Return &Value;
end-method;

class JSONObject extends JsonObject
   method JSONObject(&p_obj As JsonObject);

   /* peoplecode的IsNull方法有bug，无法区分传过来的是0还是null，使用面向对象再度封装 */
   method IsNullProperty(&p_ppt As string) Returns boolean;
end-class;


method JSONObject
   /+ &p_obj as JsonObject +/
   %Super = &p_obj;
end-method;

method IsNullProperty
   /+ &p_ppt as String +/
   /+ Returns Boolean +/
   /+ Extends/implements JsonObject.IsNullProperty +/
   If %Super.IsNullProperty(&p_ppt) Then
      If %Super.GetAsString(&p_ppt) = "null" Then
         Return True;
      Else
         Return False;
      End-If;
   Else
      Return False;
   End-If;
end-method;

class JsonUtil
   method JsonUtil();

   method GetRootObject(&MessageContent As string) Returns JsonObject;
   method CreateSuccessMessage(&OperationName As string, &Data As JsonObject) Returns Message;
   method CreateFailedMessage(&OperationName As string, &Code As integer, &ErrStr As string) Returns Message;
end-class;


method JsonUtil

end-method;


method GetRootObject
   /+ &MessageContent as String +/
   /+ Returns JsonObject +/
   Local JsonObject &RootObject;
   Local JsonParser &JParser;
   Local boolean &Bool;

   &JParser = CreateJsonParser();

   try
      &Bool = &JParser.Parse(&MessageContent);
      &RootObject = &JParser.GetRootObject();
   end-try;
   Return &RootObject;
end-method;


method CreateSuccessMessage
   /+ &OperationName as String, +/
   /+ &Data as JsonObject +/
   /+ Returns Message +/
   Local Message &RespMsg;
   Local string &t_Operation;
   Local JsonNode &DataNode;
   Local JsonObject &RespObj;
   Local boolean &Bool;

   If Upper(Left(&OperationName, 10)) = "OPERATION." Then
      &t_Operation = Substring(&OperationName, 11, Len(&OperationName));
   Else
      &t_Operation = &OperationName;
   End-If;
   &RespObj = CreateJsonObject();
   try
      &RespMsg = CreateMessage(@("Operation." | &t_Operation), %IntBroker_Response);
      &RespObj.AddProperty("code", 0);
      &RespObj.AddProperty("message", "success");
      If &Data <> Null Then
         &RespObj.AddJsonObject("data", &Data);
      Else
         &RespObj.AddProperty("data", 0);
         &DataNode = &RespObj.GetJsonNode("data");
         &DataNode.SetNull();
         &DataNode.SetNodeName("data");
      End-If;
      &Bool = &RespMsg.SetContentString(&RespObj.ToString());
   end-try;
   Return &RespMsg;
end-method;


method CreateFailedMessage
   /+ &OperationName as String, +/
   /+ &Code as Integer, +/
   /+ &ErrStr as String +/
   /+ Returns Message +/
   Local Message &RespMsg;
   Local string &t_Operation;
   Local JsonBuilder &RespObj;
   Local boolean &Bool;

   If Upper(Left(&OperationName, 10)) = "OPERATION." Then
      &t_Operation = Substring(&OperationName, 11, Len(&OperationName));
   Else
      &t_Operation = &OperationName;
   End-If;
   &RespObj = CreateJsonBuilder();

   try
      &RespMsg = CreateMessage(@("Operation." | &t_Operation), %IntBroker_Response);
      &RespObj.StartObject("");
      &RespObj.AddProperty("code", &Code);
      &RespObj.AddProperty("message", &ErrStr);
      &RespObj.AddNullProperty("data");
      &RespObj.EndObject("");
      &Bool = &RespMsg.SetContentString(&RespObj.ToString());
   end-try;
   Return &RespMsg;
end-method;
